quests[10995] = { id = 10995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grulloc hat zwei Schädel", description = "Im Osten, am Rand von Drachenend, könnt Ihr das Verfluchte Dunkel finden. An diesem Ort schmiedet Grulloc, Sohn des Gruul, seine dümmlichen Pläne.\n\nIch habe gehört, dass er trickreich um eines seiner Besitztümer gebracht wurde. Wart Ihr das etwa? Nur zu schade, dass er bei dieser Gelegenheit nicht gleich umgebracht wurde.\n\nWenn wir unsere Freiheit wiedererlangen wollen, müsst Ihr ihm seinen wertvollsten Besitz rauben: einen Drachenschädel, den er als Erinnerung an das Gemetzel seines Vaters am schwarzen Drachenschwarm bewahrt. Doch um an den Schädel heranzukommen, werdet Ihr ihn töten müssen.", sourceObjective = "Beschafft Euch Grullocs Drachenschädel.", progress = "Ist Grulloc schon Geschichte?", completion = "Das muss ein harter Kampf gewesen sein, {class}. Ich bin sehr erleichtert, dass er uns nun nicht mehr auf die Pelle rücken wird.\n\nIch werde diesen Schädel zu Chort schicken, damit er auf ihn aufpasst. Ich glaube, dass wir unser Ziel mit eurer Hilfe erreichen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[10996] = { id = 10996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maggocs Schatztruhe", description = "Im Messergrat über uns und im Südosten zieht Maggoc seine Kreise. Sein Vater hat ihn zum Wächter des östlichen Teils der Berge erkoren, und er benutzt sein Amt, um jegliches Wesen zu terrorisieren, das ihm in die Quere kommt.\n\nAls Sohn des Gruul muss auch er verschwinden, damit mein Klan überleben kann. Und da kommt Ihr ins Spiel.\n\nMaggoc trägt stets eine Schatztruhe bei sich. Beweist mir, dass Ihr ihn umgebracht habt, indem Ihr mir seine teure Truhe bringt. Was auch immer Ihr darin finden mögt, dürft Ihr gerne behalten.", sourceObjective = "Beschafft Euch Maggocs Schatztruhe.", progress = "Habt Ihr die Truhe?", completion = "Sie war leer? Was ein Pech! Aber nun habt Ihr eine Ahnung von der sinnlosen Gewalt, unter der wir leiden müssen.\n\nJetzt, da Maggoc tot ist, sind wir meinem Traum von einem Zuhause, in dem wir Oger unser Schicksal selbst schmieden können, einen entscheidenden Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[10997] = { id = 10997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sogar ein Gronn hat Standards", description = "Kennt Ihr Euch in Shattrath aus, {class}? Über der Stadt im Nordwesten gibt es einen Ort, den man die Hügelwand nennt. Man kann nur mit einem fliegenden Reittier dorthin gelangen.\n\nEiner der Söhne Gruuls, Slaag, hat sich selbst ins Exil dorthin begeben und die Herrschaft über die Oger der Gordunni, die dort leben, an sich gerissen. Auch wenn er so weit entfernt lebt, können wir ihn nicht am Leben lassen. Er könnte zurückkommen, wenn er erfährt, dass seine Brüder tot sind!\n\n{name}, Ihr müsst dorthin reisen und seine Standarte als Beweis für seinen Tod mitbringen.", sourceObjective = "Beschafft Euch Slaags Standarte.", progress = "Haltet Ihr Slaags Standarte schon in Euren Händen?", completion = "Ich bin erleichtert, dass Slaag nicht mehr unter uns weilt. Nun müssen wir nicht länger in Angst vor seiner drohenden Rückkehr leben!\n\nWenn Ihr nichts dagegen habt, würde ich die Standarte gerne als Symbol der Hoffnung für alle Oger dieser Berge entgegennehmen.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10998] = { id = 10998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den übelsten Kreisen", description = "Es gibt einen weiteren Gronn, der getötet werden muss: Skulloc Seelenschänder. Er weiß sich zu verstecken, doch es gibt einen Weg, ihn hervorzulocken.\n\nEr wurde von einem Ogerhexenmeister namens Vim'gol der Üble ausgebildet, an dessen Zauberfolianten Ihr gelangen müsst!\n\nMan beschwört Vim'gol, indem man innerhalb eines Feuerkreises bei seinem Zirkel steht. Findet Vim'gols Kreis in den Bergen im Nordosten, nahe der Zerschlagenen Wildnis.", sourceObjective = "Beschafft Euch Vim'gols üblen Zauberfolianten.", progress = "Habt Ihr Vim'gol den Üblen beschworen und seinen toten Klauen den Zauberfolianten entrissen?", completion = "Ich scheue mich davor, ein Ding von solcher Abscheulichkeit auch nur anzufassen. Und doch müssen wir den Folianten lesen, wenn wir sein Wissen erkunden und Skulloc aus seinem Versteck locken möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[10999] = { id = 10999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schuss, ein Treffer", description = "Bringt mir 8 Troggsteinzähne." }
quests[11000] = { id = 11000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schänder der Seelen", description = "Der Zauberfoliant ist der Schlüssel zu Skullocs Untergang.\n\nUm das Ritual zu beginnen, müsst Ihr am Hügel des Seelenschänders laut aus dem Buch vorlesen. Daraufhin werden der Geist des Seelenschänders sowie die Geister seiner Opfer erscheinen. Sie werden versuchen, den Seelenschänder zu vernichten. Ihr müsst sie so lange daran hindern, bis Skulloc vollständig in diese Welt übergetreten ist.\n\nDurchquert den Dolchrachenklamm Richtung Norden. Ihr findet den Grabhügel auf der anderen Seite des Zirkels des Blutes auf der rechten Seite vor Gruuls Unterschlupf.\n\nBringt mir Skullocs Seele!", sourceObjective = "Beschafft Euch Skullocs Seele.", progress = "Habt Ihr Skullocs Seele schon geraubt?", completion = "Es ist also vorüber. Ihr habt uns von den Fesseln der Sklaverei durch die Söhne von Gruul befreit. Ihr habt den Klan der Blutschläger vor der sicheren Auslöschung bewahrt.\n\nEs gibt keine Worte um zu beschreiben, wie tief ALLE Oger des Schergrats, Blutschläger wie Speerspießer, in Eurer Schuld stehen, {name}.\n\nSchaut dort, wie all die Oger sich versammeln um Euch Tribut zu zollen! Sollen Gruul und seine Marionette, der alte König Maulgar, sich ruhig in ihrem Unterschlupf verkriechen. Geht zu den Ogern als ihr neuer König!", sourceObjectiveStatus = "unverified-source-field" }
quests[11001] = { id = 11001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet den Rabengott", description = "Wir haben bei der Vernichtung des Rabengottes keine Zeit zu verlieren. Ihr müsst den mit Essenz erfüllten Mondstein zu einem Ort von großer Macht bringen, um den Gott aus der relativen Sicherheit des Smaragdgrünen Traums zu locken.\n\nSteigt in die Sethekkhallen hinab und setzt den Mondstein in die Fänge der Rabenklaue ein. Ihr findet den Raum vor der Halle des Klauenkönigs.\n\nAnzu muss glauben, dass seine Anhänger sich versammelt haben, um ihn wieder in dieser Welt willkommen zu heißen. Zeigt keine Gnade, sobald er sich manifestiert hat!", sourceObjective = "Tötet den Rabengott und kehrt dann zu Morthis Flügelraunen bei der Zuflucht des Cenarius zurück.\n\nDiese Aufgabe muss auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Was gibt es neues aus den Sethekkhallen? Habt Ihr Anzu besiegt?", completion = "Schön, Euch wiederzusehen, {name}. Euer Sieg über den Rabengott ist weit mehr als nur ein Test oder ein Aufnahmeritual.\n\nIhr habt Euch als würdig bewiesen, das Wissen, das die Druiden der Klaue seit unzähligen Generationen bewahren, zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11002] = { id = 11002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magtheridons Untergang", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Allianz!\n\nBringt Magtheridons Kopf zu Danath Trollbann in der Ehrenfeste.", sourceObjective = "Bringt Magtheridons Kopf zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, {name}. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Belagerung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[11003] = { id = 11003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magtheridons Untergang", description = "Nun ist die Quelle von Illidan Sturmgrimms Höllenorcarmee versiegt. Die Manufaktur hat die Produktion ihres üblen Erzeugnisses gestoppt - zumindest fürs Erste. Jetzt sind nur noch Schrott und dieser abgetrennte Kopf übrig. Welch passende Trophäe für einen Helden der Horde!\n\nBringt Magtheridons Kopf zu Nazgrel in Thrallmar.", sourceObjective = "Bringt Magtheridons Kopf zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel.", progress = "Zum ersten Mal seit ich mich erinnern kann herrscht Stille.", completion = "Dieser Sieg ist nicht nur ein Schlag gegen Illidan, {name}. Auch die Legion schwankt... Ein Kommandant der Grubenlords wurde vernichtet. Die Besetzung der Höllenfeuerzitadelle ist jetzt für die Brennende Legion nicht länger von Bedeutung. All ihre Bemühungen werden sich nun ohne Zweifel auf den Schwarzen Tempel konzentrieren.\n\nFür Illidan kommt der Tag der Abrechnung... schon bald.", sourceObjectiveStatus = "unverified-source-field" }
quests[11004] = { id = 11004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwelt", description = "Himmelskommandant Adaris wurde bei einem Überfall der Skettis schwer verletzt. Seitdem hat er immer und immer wieder sein Bewusstsein verloren.\n\nIch befürchte, dass er Opfer einer Fieberphantasie wurde. In seinen wenigen wachen Momenten bat er mich darum, ein Elixier aus Schattenstaub herzustellen, wie ihn die Arakkoa bei sich tragen. Er scheint zu glauben, dass er dank des Elixiers in eine Art \"Schattenwelt\" sehen könne, in welcher die wahren Anführer der Arakkoa hausen.\n\nIch schenke diesem Unsinn natürlich keinen Glauben, fürchte jedoch, dass er nicht eher ruhen wird, bis er eines dieser Elixiere in Händen hält. Werdet Ihr uns helfen?", sourceObjective = "Severin möchte, dass Ihr nach Skettis reist und 6 Einheiten Schattenstaub von den dort lebenden Arakkoa sammelt.", progress = "Habt Ihr den Staub, {name}?", completion = "Ich danke Euch, {name}. Ich werde dem Kommandanten eine kleine Menge zukommen lassen... damit er seinen Willen bekommt. Ihr könnt den Rest behalten, vielleicht findet Ihr ja eine Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[11005] = { id = 11005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse der Krallenpriester", description = "Danke, dass Ihr mir im Fieberwahn zugehört habt. Schon seit geraumer Zeit versuchen wir die Kommandokette der Skettis aufzudecken und sie zu zerschlagen. Wir wussten von der Existenz dreier Kleriker, den Krallenpriestern, jedoch haben wir niemals einen von ihnen zu Gesicht bekommen. Nun wissen wir warum.\n\nSprecht mit Severin und beschafft Euch mehr von seinem Elixier. Verwendet das Elixier, um die drei Krallenpriester, Ishaal, Skizzik und Zellek ausfindig zu machen und zu töten. Gerüchten zur Folge findet man sie im Ala'rakversteck, am östlichen Ufer des Schattenwindsees.", sourceObjective = "Beschafft Euch von Severin ein Elixier der Schatten und verwendet es, um Krallenpriester Ishaal, Krallenpriester Skizzik und Krallenpriester Zellek in Skettis ausfindig zu machen und sie zu töten. Kehrt nach Abschluss Eurer Aufgabe zu Kommandant Adaris zurück.", completion = "Ihr habt Euch mit Bravour geschlagen, {name}. Durch den Verlust der Krallenpriester wurde dem Feind ein empfindlicher Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11006] = { id = 11006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Schattenstaub", progress = "Der Kommandant scheint doch nicht aus einem Fieberwahn heraus gesprochen zu haben. Bringt mir mehr Staub und ich werde ein weiteres Elixier für Euch herstellen.", completion = "Ihr könnt mir auch weiterhin noch Staub bringen. Ich werde so viele Elixiere für Euch herstellen, wie Ihr benötigt.\n\nAuf Befehl des Kommandanten." }
quests[11007] = { id = 11007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kael'thas und die tiefgrüne Sphäre", description = "Die Luft um Euch herum ist von einem Summen erfüllt - einem freundlichen Summen. Die Naaru wissen von Eurem Sieg. Vielleicht sind sie der Grund für Euer Bedürfnis, die Sphäre inmitten der immer noch zuckenden Überreste von Kael'thas Sonnenwanderer aufzuheben. Welche Geheimnisse mögen darin stecken?\n\nVielleicht weiß A'dal in Shattrath mehr über diesen Gegendstand.", sourceObjective = "Bringt die tiefgrüne Sphäre zu A'dal in Shattrath.", progress = "Ihr habt meinen Ruf vernommen? Ja...", completion = "<A'dals Gedanken vermischen sich mit den Euren.>\n\nDie Sphäre... Sonderbar. Wusstet Ihr, dass er überlebt hat? Ja. Hier drin, in der Sphäre selbst. Ganz sicher verstümmelt. Er gehorcht nun einer höheren Macht. Nein, nicht Illidan.\n\nHöher.\n\nKil'jaeden der Betrüger kommt...\n\nNicht hierher...\n\n<A'dal führt Euren Geist an einen anderen Ort.>\n\nAzeroth. Unbekannt.\n\nRuht Euch aus. Eure Brüder und Schwestern werden die Festung der Stürme wieder übernehmen.\n\n<A'dal summt eine Kriegshymne.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11008] = { id = 11008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer über Skettis", description = "Glaubt Ihr, dass Ihr das Zeug dazu habt, ein Teil der Himmelswache zu sein? Wir werden überprüfen müssen, wie gut Ihr in der Luft zurechtkommt.\n\nDie Arakkoa züchten eine gigantische Menge von ihren Kampfvögeln, die sie auf unsere Späher hetzen! Ich möchte, dass Ihr diese Sprengladungen nehmt und ihre Brutstätten über den Siedlungen der Arakkoa zerstört. Macht aber einen Bogen um die monströsen Kaliri, welche die Brutstätten bewachen. Sie werden Euch vom Reittier holen, bevor Ihr wisst, wie Euch geschieht!", sourceObjective = "Haltet nach monströsen Kalirieiern oben in den Siedlungen von Skettis Ausschau und benutzt die Sprengladungen der Himmelswache, um sie in die Luft zu sprengen. Kehrt danach zu Himmelsoffizier Doryn zurück.", progress = "Habt Ihr Euren Auftrag schon erledigt?", completion = "Ausgezeichnete Arbeit, {name}! Das wird diesen Vogelwesen zeigen, wer die wahren Herren der Lüfte sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[11009] = { id = 11009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerhimmel", description = "Jetzt, da Ihr uns aus der Knechtschaft befreit habt, können wir mit der Wiedervereinigung der Klans beginnen. Es wird einige Zeit dauern; lange geschürter Zorn kühlt nur langsam wieder ab.\n\nEs ist umso eiliger, dass Ihr nach Ogri'la, hoch oben im Westen, reist. Verteidigt es und uns so gut, wie Ihr könnt. Schützt uns vor den Mächten, wie es einst die Gronn taten: Astrale, Dämonen und noch viel schlimmer, der schwarze Drachenschwarm, erwarten Euch.\n\nSolltet Ihr den Himmel der Oger gefunden haben, ersucht Chu'a'lor um Rat für die weitere Vorgehensweise.", sourceObjective = "Mog'dorg der Weise hat Euch gebeten, mit Chu'a'lor in Ogri'la im Schergrat zu sprechen.", completion = "Mog'dorg hat eine Nachricht voraus geschickt, um mich über Euer Kommen zu informieren. Ich bin froh, dass Ihr hier seid.\n\nNach dem Fall der Söhne des Gruul, ist es nur noch eine Frage der Zeit - es dürfte nicht sehr lange dauern - bevor die unterschiedlichen Bewohner dieser Bergterrasse und die des Nordens beginnen, Jagd auf unsere Ogerbrüder dort unten zu machen.\n\nDies gilt es zu verhindern und ich vertraue auf Eure Unterstützung, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11010] = { id = 11010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomberangriff", description = "Ihr habt ein fliegendes Reittier... ja und! Glaubt Ihr denn, dass Ihr das Zeug dazu habt, es gekonnt einzusetzen?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und obendrein bedrohen sie das friedliche Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nehmen, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", sourceObjective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n<Himmelsoffizier Vanderlip grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11011] = { id = 11011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Wachsamkeit", description = "Euer Sieg über Anzu, den Rabengott, ist eine wahrhaft heldenhafte Leistung. Ich fürchte allerdings, dass er nicht aufgeben und weiterhin versuchen wird, in die Scherbenwelt zurückzukehren.\n\nSolange seine Gefolgsleute am Leben sind, wird er sich immer wieder erheben. Daher solltet Ihr den mit Essenz erfüllten Mondstein stets bei Euch haben, falls Anzu sich erneut regt.", sourceObjective = "Sprecht mit Morthis Flügelraunen, um einen mit Essenz erfüllten Mondstein zu erhalten.", completion = "Behaltet den Mondstein bei Euch, {name}. Wenn Ihr glaubt, dass Anzu seine Kräfte sammelt, um in diese Welt zurückzukehren, verwendet den Stein um ihn zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11012] = { id = 11012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Blutschwur der Netherschwingen", sourceObjective = "Unser Land ist verloren. Man entführt unsere Kinder in der Nacht, versklavt sie - oder schlimmer...\n\n<Mordenais Stimme wird angespannt.>\n\nEs ist an der Zeit, mein Freund. Zeit, uns wieder das zu nehmen, was einst unser war! Ihr habt Euch als tapferer Kämpfer und verständnisvolle Seele erwiesen.\n\nWerdet Ihr schwören, dem Drachenschwarm der Netherschwingen beim Kampf um unser Land und den Wiederaufbau unserer Heimstätten zu helfen? Werdet Ihr schwören, über den Schwarm zu wachen, damit unser Fleisch und Blut aufs Neue zum Leben erwachen kann? Schwört und lasst uns im Namen unserer Heimat und unserer Familien kämpfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11013] = { id = 11013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste der Illidari", description = "Die Netherschwingenscherbe... Was einst eine Feste der Zuflucht für die Netherschwingen war, ist nun das Zuhause des Drachenmalklans. Die Orcs haben vielleicht die Kontrolle über unser Land gewonnen, unsere Magie ist dort jedoch noch stark. Stark genug, um Eure wahre Identität zu verschleiern und um Euch in die Ränge des Drachenmalklans einzuschleusen.\n\nIch habe dieses Schreiben für Euch aufgesetzt, überreicht es ihrem Anführer, Oberanführer Mor'ghor. Fliegt den Fängen unseres Feindes entgegen, reist zum Basislager des Drachenmals und beginnt Euer neues Leben als Höllenorc Illidan Sturmgrimms.", sourceObjective = "Reist zur Netherschwingenscherbe und überreicht Oberanführer Mor'ghor beim Basislager des Drachenmals das Empfehlungsschreiben der Illidari.", progress = "<Mor'ghor grunzt.>\n\nIhr seid spät...", completion = "<Mor'ghor überfliegt das Schreiben und lacht.>\n\nEin Todesritter? Ihr könnt einem Todesritter nicht mal das Wasser reichen, Wurm.\n\n<Mor'ghor mustert Euch scharf.>\n\nNun gut... Ihr könntet es vielleicht noch zum Peon schaffen. Im schlimmsten Fall werfe ich Euch in die Grube und lasse Euch dort verrotten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11014] = { id = 11014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Höhle des Löwen", description = "<Mor'ghor zerknüllt das Empfehlungsschreiben und wirft es beiseite.>\n\nAlso Grunzer, eins nach dem anderen. Wenn Ihr meiner teuren Armee des Drachenmals beitreten wollt, dann müsst Ihr arbeiten. Jeder arbeitet hier auf der Scherbe. Sucht Euch Arbeit und seht zu, dass Ihr Euch nicht zu dämlich anstellt. Eventuell werde ich Euch später mit interessanteren Dingen beauftragen.\n\nSprecht mit Zuchtmeister Varkule Drachenodem, er steht in der Mitte des Lagers. Nach Einschätzung Eurer Fertigkeiten, wird er Euch eine entsprechende Arbeit zuteilen.\n\nUnd jetzt verschwindet!", sourceObjective = "Sprecht mit Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals.", completion = "Varkule findet schon was für Euch, Grunzer. Euch steht eine Aufgabe zu, die Euren Fertigkeiten am besten gerecht wird und unserer Kristallförderung zu Gute kommt. Ihr müsst Euren Arbeitsauftrag einmal am Tag ausfüllen.\n\nJa, es gibt da einen Haufen Drecksarbeit zu erledigen, aber auch die Ahnen haben mal als Peon begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11015] = { id = 11015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristalle der Netherschwingen", description = "Ihr taugt zu nichts, was? In Ordnung, auch Vollidioten wie Ihr können uns hier noch zur Hand gehen. Sucht auf der Scherbe einfach nach Kreaturen und tötet sie. Manchmal befinden sich auf ihren Körpern Kristalle der Netherschwingen. Sammelt und bringt sie mir, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 30 Kristalle der Netherschwingen bringt.", progress = "Kristalle der Netherschwingen werden für vielerlei Dinge verwendet. Hauptsächlich zur Herstellung von Waffen und Rüstungen...", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11016] = { id = 11016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balg eines Netherminenschinders", description = "Ein Kürschner, ja? Nun, Ihr werdet hier mehr als genug Häutbares finden! Sucht in der Nähe der Kristallformationen nach Schindern. Tötet sie und nehmt ihre Bälge an Euch. Vielleicht sind die ein oder anderen sogar etwas wert, bringt mir genau diese.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 35 Bälge eines Netherminenschinders bringt.", progress = "Wir verwenden die Bälge von Schindern zum Ausfüttern von Rüstungen und die Herstellung von Planen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11017] = { id = 11017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherstaubpollen", description = "Ein Blümchenpflücker?! Köstlich... bedauerlicherweise benötigen unsere Magier und Schamanen Eure Dienste. Die Netherstaubbüsche, die hier auf der Scherbe wachsen, besitzen spezielle Pollen, die bei magischen Angelegenheiten wohl recht nützlich sind. Bringt mir das Zeug, dann habt Ihr Euren Arbeitsauftrag für heute erledigt.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Netherstaubpollen bringt.", progress = "Wie ich schon sagte, Netherstaubpollen werden von unseren Zauberern verwendet.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11018] = { id = 11018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netheriterz", description = "Ein Minenarbeiter!\n\n<Varkule nickt Euch zu.>\n\nEin Orc ganz nach meinem Geschmack! So hat Varkule auch einmal angefangen - mit Bergbau! Es gibt doch nichts Besseres als runter in die Mine zu gehen und richtig schmutzig zu werden, nicht wahr?\n\nGeht jetzt und sucht nach Netheritablagerungen. Holt alles, was wertvoll ist, heraus und bringt mir das Erz.", sourceObjective = "Zuchtmeister Varkule Drachenodem beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 40 Einheiten Netheriterz bringt.", progress = "Gug dort drüben verwendet das Erz zum Verstärken unserer Waffen und Rüstungen.", completion = "Das war's für heute, Kindchen. Kommt morgen wieder, wenn Ihr noch am Leben seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11019] = { id = 11019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund unter Feinden", sourceObjective = "Ihr habt doch nicht etwa geglaubt, dass wir Euch den Armeen der Höllenorcs ganz alleine überlassen würden, oder?\n\n<Yarzills Augen flackern in einem durchscheinenden Blau.>\n\nGenau, wir sind hier an Eurer Seite, {name}. Bei jedem Dienst, den Ihr den Höllenorcs bei Eurem Versuch, die Weiten der Netherschwingen zurückzuerobern, erweist, werden wir dafür sorgen, dass sie einen ausreichenden Rückschlag erleiden.\n\nIhr müsst Euch sehr unauffällig verhalten, um keinerlei Aufmerksamkeit während Euren Sabotageeinsätzen auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11020] = { id = 11020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein langsamer Tod", description = "Die Anhänger des Drachenmals haben bei fast allen Kristallformationen hier oben Peons stationiert. Ein bloßes Töten, würde Euch bei weitem zu viel unerwünschte Aufmerksamkeit einbringen. Wir können ihre Reihen aber auch auf eine andere Art und Weise lichten, ohne bei dem misstrauischen Mor'ghor Verdacht zu erwecken.\n\nReist in die Wildnis des Schattenmondtals und tötet die besudelten Tiere. Nehmt ihre verderbten Teufelsdrüsen an Euch. Wendet die Teufelsdrüsen in der Nähe der Peons auf den Hammel an, den ich Euch geben werde. Ein Biss und sie sind tot!", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr Yarzills Hammel zusammen mit den Teufelsdrüsen verwendet, um 12 Peonlager des Drachenmals zu vergiften.", progress = "Es ist eine schmutzige Arbeit, {name}.", completion = "<Yarzill flüstert ganz leise.>\n\nAusgezeichnete Arbeit, {name}. Verhaltet Euch fürs Erste ruhig. Kommt morgen wieder zu mir, dann können wir das Ganze noch einmal machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11021] = { id = 11021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaals Almanach", description = "Dieser geheimnisvolle Foliant lag bei Krallenpriester Ishaals Leichnam. Die darin abgebildeten arkanen Symbole und Schaubilder von Himmelskörpern sind Euch völlig fremd.\n\nSämtliche Aufzeichnungen wurden in einer für Euch unverständlichen Sprache verfasst; vermutlich eine uralte Form der Arakkoaschriftsprache. Vielleicht solltet Ihr damit zu Himmelskommandant Adaris gehen.", sourceObjective = "Bringt Ishaals Almanach zu Himmelskommandant Adaris im Norden von Skettis.", progress = "Ihr wollt mir etwas zeigen?", completion = "Was habt Ihr mir da gebracht? Die Sprache dieses Folianten ist mir fremd, {name}... mein Blutverlust... muss meinen Geist verschleiert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11022] = { id = 11022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Mog'dorg", description = "<König/Königin> {name}! Bevor Ihr uns verlasst und nach Ogri'la geht, sprecht mit Mog'dorg dem Weisen!", sourceObjective = "Sprecht mit Mog'dorg dem Weisen. Er steht oben auf dem Turm auf der Ostseite des Zirkels des Blutes im Schergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11023] = { id = 11023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und wieder ein Bombenangriff!", description = "Diese Flakgeschütze bereiten uns noch immer Sorgen, {name}.\n\nVersteht mich bitte nicht falsch - Ihr habt das letzte Mal hervorragende Arbeit geleistet, aber das ändert leider nichts an der Tatsache, dass diese verdammten Dämonen ihre Munitionsvorräte schneller wieder aufzufüllen vermögen, als wir sie vernichten können. Unsere Männer da hineinzuschleusen ist momentan also ein mehr als riskantes Unterfangen, ganz zu schweigen von dem Risiko, das die Dämonen für Ogri'la darstellen.\n\nWas sagt Ihr? Wollt Ihr es noch einmal versuchen?", sourceObjective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", progress = "Wie steht es mit dem Bombenangriff?", completion = "Hervorragend, {name}! Ich würde Euch ja sofort wieder in die Luft schicken und ein paar Bomben werfen lassen, aber unsere Richtlinien hier schreiben vor, dass unsere Piloten ausreichend Ruhe und Erholung erhalten müssen. Es tut mir leid, ich mache die Regeln nicht, aber lasst Euch versichern, dass ich sie durchsetzen werde!\n\nSehen wir uns morgen wieder, Sportskanone?", sourceObjectiveStatus = "unverified-source-field" }
quests[11024] = { id = 11024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Verbündeter im Unteren Viertel", description = "Im Unteren Viertel gibt es einen Arakkoa namens Rilak... ihm kann Vertrauen geschenkt werden. Nehmt das Buch... und bringt es zu ihm.\n\n<Adaris gibt Euch das Buch wieder und verliert daraufhin das Bewusstsein.>", sourceObjective = "Bringt Ishaals Almanach zu Rilak dem Erlösten im Unteren Viertel in Shattrath.", progress = "Ihr seid mit dem Geruch Skettis' behaftet! Was hat das zu bedeuten?", completion = "Das kann nicht sein... dies war einst Eigentum eines Krallenpriesters. Wie ist es nur in Eure Hände gelangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11025] = { id = 11025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kristalle", description = "Beim richtigen Umgang mit den Kristallen der Berge, weisen diese seltsame Kräfte auf, wie zum Beispiel die Klarheit des Geistes, die wir hier in Ogri'la entdeckt haben.\n\nAlle Kreaturen oben auf den Bergen begehren danach und benutzen die Splitter, um ihre eigenen Ziele voranzutreiben. Der Wert dieser Kristalle hat sogar eine regelrechte Wirtschaft aufkommen lassen.\n\nUm uns helfen zu können, müsst Ihr zunächst etwas über die Apexissplitter lernen. Bringt mir ein paar Exemplare. Nicht nur die Kreaturen hier besitzen welche, gelegentlich findet man sie auch bei den großen Kristallen, dort, wo die Hetzer graben.", sourceObjective = "Chu'a'lor möchte, dass Ihr 5 Apexissplitter einsammelt. Bringt sie zu ihm in Ogri'la hoch oben im Schergrat.", progress = "Wenn Ihr mehr über die Splitter und Kristalle lernt, werdet Ihr uns und unsere Ogerbrüder dort unten besser beschützen können.\n\nDie Splitter selbst wurden nach einer uralten und mittlerweile ausgelöschten Arakkoazivilisation benannt, die einst auf den Spitzen dieser Berge lebte.\n\nNun, habt Ihr die Splitter bei Euch?", completion = "<Chu'a'lors linker Kopf beginnt zu sprechen.>\n\nDiese sind genau richtig.\n\nDenkt daran, {name}, der Wert dieser Splitter liegt nicht in ihrem Verkaufspreis. Es ist nicht einmal das, was sie für Euch tun können, sobald sie ordnungsgemäß zusammengeschmiedet wurden... auch wenn sich darüber streiten lässt.\n\n\n\nDer wahre Wert liegt in dem Unterfangen, das es auf sich zu nehmen gilt, um in den Besitz dieser Splitter zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11026] = { id = 11026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannt die Dämonen", description = "Ihr seid genau zur rechten Zeit hier eingetroffen! Wir brauchen dringend Unterstützung. Als Gegenleistung werden wir Euch etwas sehr seltenes und von beiderseitigem Wert für Euch und für uns überlassen.\n\nWir sind keine gewalttätigen Oger mehr, aber die nahegelegenen Dämonen drohen uns und die Himmelswache zu überrennen. Das Problem mit Dämonen ist, hat man sie erst einmal getötet, tauchen sie wenig später in einem neuen Körper wieder auf!\n\nWenn Ihr allerdings mit diesem Kristall ein Bannportal beschwört und ein Dämon in dessen Nähe stirbt, wird seine Essenz in das Portal gezogen und er in seine Heimatebene verbannt!", sourceObjective = "Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen.", progress = "Wir nehmen an, Ihr habt den Bannkristall dazu benutzt, eine ganze Reihe dieser Dinger der Brennenden Legion zum Packen zu bewegen?", completion = "Das wird ihnen eine Lehre gewesen sein! Kommen wir nun zu Eurer Belohnung.\n\nDie Dämonen des Konstruktionslagers: Wut im Norden haben an ihrer südlichen Grenze einen besonderen Transporter errichtet. Sie verwenden dieses experimentelle Transporttor, um den Einfluss des Lagers weiter auszudehnen. Wir brauchen Euch wohl nicht erst erklären, was passieren wird, wenn sie sich zu weit ausbreiten.\n\nAlso, wenn wir Ihr wären, würden wir diese Rune der Dunkelheit zu Gahk schaffen und ihn Fragen, wie Ihr helfen könnt. Geht es langsam mit ihm an, {name}, er ist ebenfalls neu hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[11027] = { id = 11027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr die Rune der Dunkelheit?" }
quests[11028] = { id = 11028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Countdown des Schicksals", description = "Dieser Almanach prophezeit die Rückkehr von Terokk, dem mächtigsten und furchtbarsten Skettiskönig der Arakkoageschichte.\n\nIch habe dies immer für eine Legende gehalten, {name}. Die Wiederkehr der Krallenpriester und Eure Entdeckung dieses Folianten belehren mich jedoch eines Besseren.\n\nMit jedem Tag wächst die Macht Terokks und seine Ankunft naht. Die einzige Chance, die Ihr habt, ist ihn vorzeitig in unsere Welt zu holen. Geht zurück nach Skettis und sprecht mit Adaris über das Ganze. Lasst uns hoffen, dass er die Weisheit besitzt, um die richtige Entscheidung zu treffen.", sourceObjective = "Kehrt zu Himmelskommandant Adaris ins Schattenwindlager in den Wäldern von Terokkar zurück und erzählt ihm die Neuigkeiten über Terokks Rückkehr.", completion = "Die Arakkoa möchten Terokk zurück aus dem Jenseits der Zeit holen und Rilak... möchte einen Weg finden, um diesen Vorgang zu beschleunigen? Hat er denn seinen Verstand verloren?\n\n<Adaris legt sich geschwächt nieder.>\n\nIhr habt Eure Pflicht erfüllt, {name}. Es ist an der Zeit, dass Ihr die Sache meinen Männern überlasst. Das ist jetzt eine rein militärische Angelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11029] = { id = 11029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schäbige Verkleidung", description = "Öffnet das Päckchen, {name}. Es ist eine Verkleidung. Sie sieht nicht sehr überzeugend aus, oder?\n\nIch fertige sie für astrale Schmuggler an, auf der Suche nach seltenen Büchern. Es gibt einen Schreiber der Arakkoa, der auf der zentral gelegenen Insel in Skettis lebt, die als Terokks Ruh bekannt ist; sein Name ist Sahaak. Er ist alt und fast blind.\n\nVerwendet die Verkleidung, um mit ihm zu sprechen und besorgt Euch das Buch, den Stammbaum der Feinde. Seid auf der Hut, {name}. Andere Arakkoa lassen sich von der Verkleidung nicht täuschen.", sourceObjective = "Verwendet die schäbige Arakkoaverkleidung, um den Stammbaum der Feinde von Sahaak zu beschaffen. Kehrt anschließend zu Hazzik zurück.", progress = "Das Buch, {name}. Habt Ihr es?", completion = "Ausgezeichnet! Das Buch beinhaltet eine Aufstellung der Nachfahren von Terokks alten Feinden. Es wurde vorhergesagt, dass ihr Tod Terokks Rückkehr ankündigen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11030] = { id = 11030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Junge möchte der Himmelswache beitreten", description = "Wir haben ein kleines Problem, {class}: Wir haben eine Menge Söhne. Seit die Himmelswache bei uns in der Nähe stationiert wurde, wünschen sie sich nichts sehnlicher, als der Wache beizutreten.\n\nAls stolzer Vater möchten wir natürlich, dass sie zum Zeitpunkt ihrer Bewerbung alle Vorteile haben, die sie kriegen können. Würdet Ihr also für uns die Teufelskristallschmiede in einem der beiden Lager im Norden oder im Süden aufsuchen und ein magisches Fläschchen für unsere Söhne beschaffen? Ihr könnt ihren grünen Rauch kaum verfehlen.\n\nWir denken, die Herstellung eines Fläschchens erfordert zehn Apexissplitter. Gerne würden wir Euch Splitter mitgeben, aber leider haben wir keine mehr zur Hand.", sourceObjective = "Beschafft ein instabiles Fläschchen der Bestie.", progress = "Habt Ihr das magische Fläschchen schon bekommen? Es würde Torkus Junior alles bedeuten.", completion = "Ihr seid ein Lebensretter, {name}!\n\nUnsere Jungs werden von dieser Neuigkeit begeistert sein!\n\nOk, eines geschafft und eines fehlt noch. Wir haben Euch doch bestimmt von dem anderen Fläschchen erzählt, das sie benötigen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11031] = { id = 11031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Erzmagier", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11032] = { id = 11032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Beschützer", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11033] = { id = 11033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Assassine" }
quests[11034] = { id = 11034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Bewahrer", progress = "Ihr habt Euch gegen Eure vorherige Wahl entschieden? Ich denke, dass ich Euch helfen kann, das Ganze wieder rückgängig zu machen. Dalaran geht es in erster Linie um Eure Loyalität und nicht darum, wie Ihr sie beweisen wollt.\n\nEs wird nicht gerade wenig kosten und Ihr müsst mir natürlich auch Euren alten Ring zurückgeben.", completion = "Trefft Eure nächste Entscheidung mit Bedacht. Wir versuchen unseren Verbündeten so gut wie möglich entgegen zu kommen, aber auch Dalarans Ressourcen sind nicht grenzenlos." }
quests[11035] = { id = 11035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatten am Horizont", description = "Am nordöstlichen Ende dieser Insel gibt es ein Dock, das dem Verpacken und dem Transport der Kristalle und Relikte der Netherschwingen dient. Transporter des Drachenmals transportieren die Güter vom Dock zu der Festung des Drachenmals, während die Ahnen des Drachenmals den Boden vor möglichen Angreifern schützen.\n\nUm dem Drachenmal einen Schlag zu versetzen, bleibt nur ein Angriffspunkt offen: der Himmelspfad des Drachenmals.\n\nFliegt zu den zerschlagenen Inseln des Himmelspfads des Drachenmals und lauert den Transportern auf, die diesen Weg einschlagen. Bringt unsere gestohlenen Relikte wieder in Sicherheit!", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 10 Relikte der Netherschwingen sicherstellt.", progress = "Tote Orcs singen nicht, {name}. Stellt sicher, dass keiner der Transporter des Drachenmals entkommt.", completion = "<Yarzill flüstert.>\n\nIhr habt den Netherschwingen einen großen Dienst erwiesen, {name}. Der Fall des Drachenmals rückt in greifbare Nähe. Von innen heraus breitet sich nun eine Krankheit aus - eine unheilbare Krankheit...\n\nSolltet Ihr wieder an Arbeit bei dem Himmelspfads des Drachenmals interessiert sein, so kommt morgen wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11036] = { id = 11036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außerirdische Früchte!", description = "Ich muss ganz ehrlich zugeben, dass ich nicht die leiseste Ahnung habe, wozu diese Lieferung dienen soll, aber Raketenchef Doppeldeckers Anweisungen waren sehr genau - nur die besten Früchte, konserviert, um eine lange Reise zu überstehen und gut versiegelt sollen sie sein.\n\nEs gab noch weitere Anweisungen, irgendetwas über Schwerelosigkeit hier und Niedrigdruck da. Ich gebe nicht mal vor, alles zu verstehen, aber der Preis stimmt, also kriegt er seine Supernahrung. Bringt diese Kiste zu ihm in der Area 52. Nachdem Ihr den Nethersturm betreten habt, folgt der Straße, bis Ihr die Stadt seht.", sourceObjective = "Bringt die konservierten Früchte zu Raketenchef Doppeldecker in Area 52 im Nethersturm.", progress = "Ist das die Lieferung vom alten Orok?", completion = "<Der Raketenchef überprüft den Inhalt der Kiste.>\n\nSieht soweit gut aus. Wieder etwas, dass ich von der Liste streichen kann. Nun müssen wir noch nur dafür sorgen, dass die Rakete vom Boden abhebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11037] = { id = 11037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Vision", description = "{name}, ich hatte eine höchst ungewöhnliche Vision, auf die ich mir keinen Reim machen kann. Ich sah einen Pfeil, einen gigantischen Pfeil, der sich auf einem Feuerschweif gen Himmel erhob. Für einen geübten Magier wäre es ein Leichtes etwas derartiges zu erschaffen, doch ein Gefühl sagt mir, dass dieses Objekt nicht das Produkt von Magie ist.\n\nEs wird anders sein, als alles, was die Völker von Azeroth je erschaffen haben. Ihr müsst diejenigen finden, die an diesem Wunderwerk arbeiten, {name}. Gewährt ihnen Eure Hilfe, denn ohne sie werden sie versagen.", sourceObjective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", completion = "<Der Raketenchef hört Euch aufmerksam zu, als Ihr ihm von der Vision des Sehers erzählt.>\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch die Rakete hinter mir an! Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11038] = { id = 11038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für Exarch Orelis", description = "Vor nicht allzu langer Zeit entsandte Hohepriesterin Ishanah eine kleine Gruppe von Anachoreten unter dem Kommando von Exarch Orelis in den Nethersturm. Sie hatten den Auftrag, die Aktivitäten von Kael'thas und seinen Gefolgsleuten zu untersuchen, doch bisher haben wir keinerlei Nachricht von ihnen erhalten.\n\nIch habe die Befürchtung, dass unsere Präsenz im Zielgebiet nicht stark genug ist, um diesen Auftrag erfolgreich abzuschließen. Sicherlich würde der Exarch von Eurem Wissen und Eurer Erfahrung profitieren. Wäret Ihr bereit zur Area 52 zu reisen und ihn zu unterstützen?", sourceObjective = "Sprecht mit Exarch Orelis in Area 52.", completion = "So, Ihr seid also hierher gekommen, um unsere Untersuchungen über Kael'thas Pläne zu unterstützen? Eure Hilfe ist uns sehr willkommen. Der Nethersturm ist voll von Agenten der Blutelfen, die nichts unversucht lassen, um das Land ins Chaos zu stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11039] = { id = 11039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Spionagemeister Thalodien", description = "Vor einiger Zeit schickte Voren'thal eine kleine Einheit in den Nethersturm, um Kael'thas' Aktivitäten genauer zu beobachten. Unser Anführer hat vollstes Vertrauen in die Fähigkeiten von Spionagemeister Thalodien und seinen Männern und hat sich daher entschlossen, seiner Bitte um Verstärkung nachzukommen.\n\nThalodiens Bericht fiel recht knapp aus, doch geht daraus eindeutig hervor, dass er eine Entdeckung von größter Wichtigkeit gemacht hat. Erstattet ihm in der Area 52 Meldung und unterstützt ihn soweit es Euch möglich ist, {name}.", sourceObjective = "Meldet Euch bei Spionagemeister Thalodien in Area 52.", completion = "<Einen Augenblick lang huscht ein Ausdruck der Enttäuschung über das Gesicht des Spionagemeisters.>\n\nIch hatte wenigstens auf eine ganze Einsatzgruppe gehofft, aber wenn Voren'thal es für sinnvoll hielt, Euch alleine zu entsenden, werde ich meine Pläne entsprechend anpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11040] = { id = 11040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile für den Raketenchef", description = "Wie oft ich mit einem Goblin zusammengearbeitet habe, kann ich an einer Hand abzählen. Normalerweise konkurrieren wir mit ihnen, aber als ich Raketenchef Doppeldeckers Anfrage erhielt, konnte ich sie nicht einfach so ablehnen.\n\nDiese Kiste ist voller Einzelteile für die ich hier keine Verwendung habe, aber die für das Projekt des Raketenchefs sehr nützlich sein könnten. Wäret Ihr so freundlich und würdet Sie bei ihm abgeben, wenn Ihr an der Area 52 vorbeikommt?\n\nWer weiß, vielleicht schaffen es einige gnomische Teile, seine Erfindung vor der Zerstörung zu bewahren!", sourceObjective = "Bringt Bossis Ersatzteile zu Raketenchef Doppeldecker nach Area 52 im Nethersturm.", progress = "Diese Kiste sieht aus, als stamme sie von einem Goblinmeisteringenieur. Hat Bossi Euch geschickt?", completion = "Ich weiß nicht einmal, was einige dieser Teile bewirken! Einige von ihnen werden mir sicherlich sehr nutzen. Ich hätte niemals gedacht, dass ich mal lernen müsste, wie ein Gnom zu denken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11041] = { id = 11041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unerledigte Aufgabe...", description = "Im Namen unseres großen Meisters... zum Ruhme Illidans!\n\nIm Auftrag von Oberanführer Mor'ghor soll das große Plateau der Netherschwingenscherbe gesichert werden. Da fast alle Drachen der Netherschwingen eingefangen oder vom Land vertrieben wurden, nehmen die Felsklauen langsam überhand und bedrohen unsere Kristallernte.\n\nVernichtet sie alle, ihre Höhlenmutter und ihren Gefährten, Arvoar.\n\nMor'ghor befiehlt es so!\n\n<Es scheint ganz so, als hätte der Orc beim Absichern des Plateaus versagt. Es ist an der Zeit, dass Ihr Euch bei Mor'ghor als würdig erweist!>", sourceObjective = "Tötet 10 Felslandschinder und Barash die Höhlenmutter. Kehrt nach erfolgreicher Erledigung zu Oberanführer Mor'ghor beim Basislager des Drachenmals zurück.", progress = "Wer wagt es, an Mor'ghor heranzutreten? Ich hoffe für Euch, dass es von Wichtigkeit ist.", completion = "Ihr habt also bei den Überresten einer meiner Aufseher eine Anordnung gefunden und die Sache selbst in die Hand genommen? Ihr habt es geschafft, Mor'ghor zu beeindrucken. Gut gemacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[11042] = { id = 11042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verblüffende Vision", description = "Mich verfolgt eine seltsame Vision, {name}. Ich sehe eine riesige Rauchwolke, die gen Himmel steigt, und ein gigantisches Feuer, welches sich noch weit höher erhebt. Es ist weder ein natürliches Phänomen, noch ein Werkzeug des Bösen; so viel ist sicher.\n\nIch habe keine Vorstellung davon, wie es aussieht, ich weiß nur, dass es das Werk Vieler ist. Dennoch, ohne weitere helfende Hände, wird diese Vision wohl nie Realität werden.\n\nReist in den Nethersturm, {class}. Findet die Erschaffer dieser Erscheinung und bietet ihnen Eure Hilfe an.", sourceObjective = "Sprecht mit Raketenchef Doppeldecker in Area 52.", completion = "<Der Raketenchef hört Euren Ausführungen über die Vision des Sehers aufmerksam zu.>\n\nNun, das ist alles völlig neu für mich, aber Eure Hilfe können wir allemal gebrauchen. Seht Euch das Ungetüm hinter mir an. Das ist die X-52...\n\nIst sie nicht das Schönste, was Ihr je gesehen habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11043] = { id = 11043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Greif", description = "Wie ich hörte, unterhalten die Wildhammerzwerge in ihrer Festung im südlichen Schattenmondtal einen Greifenhorst. Könntet Ihr, wenn Ihr Euch dorthin begebt, in meinem Namen mit ihnen sprechen? Ich habe da einige Ideen, wie man ihre Greifen noch verbessern könnte!\n\nWarum sie nur mit einer Rüstung ausstatten, wenn man sie noch mit einem Höhenmesser, einem Rückspiegel und einer Rakete bestücken kann? Stellt Euch nur vor, welche Geschwindigkeiten ein Greif mit einer, auf seinem Rücken festgeschnallten, Rakete erreichen würde! Ich nenne meine Erfindung den Turbogreifen 8000!", sourceObjective = "Sprecht mit Brunn Flammenbart in der Wildhammerfeste im Schattenmondtal.", completion = "<Brunns Gesicht errötet, bis es nicht länger von seinem Bart zu unterscheiden ist.>\n\nEr möchte WAS mit meinen Greifen anstellen?\n\nWenn diese kleine Ratte auch nur versucht, irgendetwas anderes als einen Sattel auf meinen Greifen zu befestigen, reise ich persönlich zum Schergrat und stopfe ihm mit seinen Raketen das Maul!", sourceObjectiveStatus = "unverified-source-field" }
quests[11044] = { id = 11044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen voller Zerstörung", description = "Eine Vision voller Zerstörung reißt mich oft aus dem Schlaf. - Ein Regen aus grünem Feuer, der auf die Erde herabregnet und die tapferen Verteidiger einer mächtigen Festung verbrennt. Seit Wochen schon verfolgt mich dieser Traum, doch erst kürzlich ist mir seine Bedeutung offenbart worden.\n\nWeit im Osten, im Schattenmondtal, erwehren sich die Wildhammerzwerge den ständigen Angriffen der Brennenden Legion und zahlloser anderer Feinde. Sie kämpfen tapfer, doch wenn sie nicht bald Entsatz erhalten, werden ihre Feinde triumphieren. {name}, Ihr müsst ihnen zur Seite stehen. Helft ihnen in ihrem verzweifelten Kampf.", sourceObjective = "Sprecht mit Schwadronskommandant Nuainn in der Wildhammerfeste.", completion = "Eine Vision sagt Ihr? Es interessiert mich nicht, ob er es in einer Vision gesehen, in einem Brief gelesen oder es aus dem Mund eines Grubenlords vernommen hat, aber er hat den Nagel auf den Kopf getroffen! Was führt Euch hierher, Freund? Oh, und wir sind für jede Unterstützung dankbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[11045] = { id = 11045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorus der Richter", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Zorus der Richter versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihm jede Hilfe willkommen ist.\n\nSolltet Ihr ins Tal reisen, haltet Ausschau nach Zorus bei der Wildhammerfeste, sie liegt zentral im Süden des Tals.", sourceObjective = "Sprecht mit Zorus dem Richter in der Wildhammerfeste.", completion = "Fantei spricht die Wahrheit, Eure Hilfe kommt mir sehr gelegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11046] = { id = 11046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefapothekerin Hildagard", description = "Die Geschichte des Schattenmondtals reicht lange zurück und ist von Tragödien durchzogen. Aus Furcht davor, alte Schrecken zu neuem Leben zu erwecken, wagen es nur wenige, sich näher mit ihr zu beschäftigen.\n\nDoch nicht alle sind so furchtsam. Chefapothekerin Hildagard versucht die Schleier der Vergangenheit des Schattenmondtals zu lüften. Dies ist eine große Herausforderung und ich bin sicher, dass ihr jede Hilfe willkommen ist.\n\nFalls Ihr Euch jemals dorthin begebt, sucht Hildagard beim Dorf Schattenmond auf, es liegt im nordwestlichen Teil des Tals.", sourceObjective = "Sprecht mit Chefapothekerin Hildagard in Schattenmond.", completion = "Fantei hat ein gutes Gedächtnis. Es ist schon Monate her, dass ich in Shattrath war, um Zutaten zu kaufen. Allerdings hat er Recht. Ich könnte etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11047] = { id = 11047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte des Gesellen", description = "Als ein Windreitermeisterlehrling gehört es zu meinen Aufgaben, die Tiere zu versorgen, wenn sie nicht gerade fliegen. Das Problem ist, dass die Windreiter sich kaum erholen können, da wir über so wenige von ihnen verfügen.\n\nIch fürchte, dass wenn wir nicht bald Ersatz erhalten, sie sich alle zu Tode fliegen werden. Im westlichen Schattenmondtal, im Dorf Schattenmond, gibt es einen großen Stall. Dama Wildmähne überwacht dort die Ausbildung und Versorgung der dortigen Windreiter.\n\nWürdet Ihr in meinem Namen mit ihr sprechen und ihr von unserer Situation berichten?", sourceObjective = "Sprecht mit Dama Wildmähne im Dorf Schattenmond im Schattenmondtal.", completion = "<Dama hört sich Agadais Bitte an.>\n\nIch kann nicht dafür garantieren, dass wir über genügend Windreiter verfügen, aber ich werde sehen, was ich tun kann. In der momentanen Situation haben wir Schwierigkeiten, die Nachfrage der verschiedenen Käufer und Außenposten abzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11048] = { id = 11048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroghans Bericht", description = "Meine ursprünglichen Befehle sahen vor, dass ich für kurze Zeit in Garadar bleibe und ich mich anschließend bei Blutwache Gulmok im Dorf Schattenmond melden sollte. In meiner Zeit hier ist mir klar geworden, dass Garadar von einer langfristigen Zusammenarbeit mit der Horde profitieren würde.\n\nIch weiß, dass Blutwache Gulmok alle verfügbaren Truppen braucht, aber er wird auch einsehen müssen, dass meine Mission hier noch nicht zu Ende ist. Reist nach Schattenmond, im nordwestlichen Teil des Schattenmondtals, und informiert Blutwache Gulmok über meine verspätete Ankunft.", sourceObjective = "Sprecht mit Blutwache Gulmok im Dorf Schattenmond.", completion = "<Gulmok beginnt zu murren, als er von Kroghans Entscheidung hört.>\n\nIch verstehe durchaus seinen Standpunkt, doch unsere Schützengräben besetzen sich nicht von selbst! Die Legion bombardiert uns Tag und Nacht mit Höllenbestien. Wenn Kroghan sich verspätet, könnt Ihr ja seinen Platz auf dem Schlachtfeld einnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11049] = { id = 11049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Eierjagd", description = "Solltet Ihr bei Euren Erkundungen auf Eier der Netherschwingen stoßen, bringt sie zu mir.\n\nEines ist sicher, ein Ei der Netherschwingen ist ein seltener Fund. Lasst den Kopf nicht hängen, falls Ihr keine Eier finden könnt. Die Anhänger des Drachenmals waren beim Einsammeln recht gründlich. Sie haben fast alle aufgespürt und an unbekannte Stellen versendet.\n\nMan findet die Eier im Besitz von Kreaturen der Insel, in der Nähe von Kristallformationen, in den Minen oder auch in Netheritansammlungen oder Netherstaubbüschen.\n\nHaltet Euch bedeckt. Mor'ghor soll wenn möglich nichts von Eurem Unterfangen erfahren.", sourceObjective = "Yarzill der Söldner beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ein Ei der Netherschwingen einsammelt.", progress = "Was macht die Eierjagd?", completion = "Neltharaku wird höchst erfreut sein, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11050] = { id = 11050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer her mit den Eiern", progress = "Diese Eier dürfen auf keinen Fall in die falschen Hände geraten, {name}. Wenn Ihr noch mehr Eier findet, bringt sie mir.\n\nVerhaltet Euch auf jeden Fall unauffällig und erregt bloß keinen Verdacht!", completion = "Ihr seid ein wahrer Held, {name}." }
quests[11051] = { id = 11051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bannt mehr Dämonen", description = "Wenn wir die Dämonen richtig einschätzen, was sehr wahrscheinlich ist, da wir sie ausgiebig studiert haben, werden sie versuchen, den Schaden an ihrem kostbaren Transporter so schnell wie möglich zu reparieren.\n\nAlso, wenn Ihr Eure Chance auf eine weitere Rune der Dunkelheit wahrnehmen möchtet, nehmt den Bannkristall und erledigt dort draußen noch mehr Dämonen für uns. Schließlich wollt Ihr uns doch dabei helfen, die Bedrohung durch die Dämonen in den Griff zu kriegen, nicht wahr?\n\nWir sagten Chance, weil der von uns angewandte Herstellungsprozess nicht immer einwandfrei funktioniert. Manchmal kommt eine Rune der Dunkelheit dabei heraus, dann wieder etwas völlig anderes.", sourceObjective = "Setzt den Bannkristall ein, um 15 Dämonen beim Konstruktionslager: Wut oder Konstruktionslager: Terror zu bannen.", progress = "Jemand mit Eurer Erfahrung dürfte keine Probleme damit haben, ein paar Dämonen zu bannen. Ihr habt doch keine Schwierigkeiten damit, oder {race}?", completion = "Wir wünschten uns, der Herstellungsprozess für Runen der Dunkelheit wäre narrensicher, {name}. Unglücklicherweise ist er das nicht. Nehmt bitte diesen Sack und seht mal, was wir heute hergestellt haben. Wir haben es nicht übers Herz gebracht, selbst nachzusehen.\n\nWenn Ihr eine Rune der Dunkelheit erhaltet, vergesst nicht, Gahk aufzusuchen und sie bei ihm gegen eine kristallgeschmiedete Rune der Dunkelheit einzutauschen. Mit ihr könntet Ihr Shartuuls Transporter erneut ausschalten.\n\nOh, und {name}, denkt daran, morgen wiederzukommen und den Bannkristall abzuholen. Es sind genug Dämonen da, die gebannt werden möchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11052] = { id = 11052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akamas Versprechen", description = "<Akama setzt den Kristall in das Medaillon in seiner Hand ein.>\n\nIch bin nicht mehr so stark wie einst, {name}. All die Jahre, die ich so nahe am Bösen verbracht habe... Ich weiß nicht, ob ich mir selbst mit einem so mächtigen Artefakt wie diesem trauen würde.\n\nNehmt dies als mein Versprechen, dass ich auf Eurer Seite sein werde, wenn Ihr Euch Illidan stellt. Bringt es zu dem Wesen, dem wir seine Macht anvertrauen können. Bringt das Medaillon zu A'dal in Shattrath.", sourceObjective = "Bringt das Medaillon von Karabor zu A'dal in Shattrath.", progress = "<A'dal bemerkt Euch und umarmt Euch mit einem warmen Licht. Er scheint zu wissen, dass Ihr etwas für ihn habt.>", completion = "<Als Ihr A'dal das Medaillon übergebt, verschwindet es mit einem Lichtblitz in seinem Geist.>\n\n<Für einen kurzen Moment erscheint eine Szene vor Euch... vielleicht aus der Zukunft. Ihr seht, wie Akama und Maiev aus dem Kerker des Wächters heraustreten und sich zum Schwarzen Tempel durchschlagen. Eine dritte, in Schatten gehüllte Gestallt hilft ihnen dabei. Als Ihr genauer hinschaut, erkennt Ihr, dass Ihr diese Gestalt seid.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11053] = { id = 11053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Aufseher!", description = "Es ist selten, dass ein Peon so lange überlebt wie Ihr. Es ist allerdings noch seltener, dass sich ein Peon vom Abschaum abhebt und in einen neuen Rang aufsteigt.\n\n<Varkule klatscht.>\n\nDer Oberanführer hat nach Euch verlangt, Grunzer. Sicherlich erwartet Euch ein neuer Rang.", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Ich habe Eure Handlungen mit einem wachsamen Auge verfolgt, {name}. Ihr habt bewiesen, dass Ihr ein unschätzbarer Gewinn für das Drachenmal seid. Daher werde ich Euch zum Aufseher befördern. Ein neuer Rang bedeutet natürlich auch neue Verantwortungen, denen Ihr gerecht werden müsst.\n\nErhebt Euch, Aufseher {name}! Erhebt Euch und sucht diejenigen auf, die Eure Hilfe hier im Basislager brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11054] = { id = 11054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsehen und Ihr: Die richtige Wahl treffen", description = "Ihr seid also der neue Aufseher, was? Tja, es gibt da eine Sache, die jeder gute Aufseher braucht: die richtige Ordnungswaffe. Bevor Ihr dort hinausgehen und diesen Peons etwas Verstand einprügeln könnt, braucht Ihr Eure \"Waffe\". Jeder Aufseher muss die Materialien zur Herstellung seiner eigenen \"Waffe\" sammeln und Ihr seid da keine Ausnahme.\n\nIch benötige Knotenhautleder und den gehärteten Balg von Tyrantus. Ihr findet Tyrantus in der Biokuppel Fernfeld, welche in der nördlichen Gegend des Nethersturms zu finden ist.", sourceObjective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 10 Einheiten Knotenhautleder und 1 gehärteten Balg von Tyrantus bringt.", progress = "Es gilt Peons zur Ordnung zu rufen, {name}! Beeilt Euch!", completion = "Ahh! Vielleicht habt Ihr ja doch das Zeug zum Aufseher. Diese übergroße Echse war schon das Leid vieler Orcs!\n\n<Chefvorarbeiter Lehmklump beginnt mit der Herstellung der Waffe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11055] = { id = 11055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schuhmerang: Das Mittel gegen den wertlosen Peon", description = "Dies hier ist Euer Schuhmerang. Es gibt viele andere, aber dieser ist Eurer.\n\nAls Aufseher werdet Ihr diesen Schuhmerang verwenden, um Furcht in die Herzen aufsässiger Peons zu pflanzen. Der richtige Einsatz des Schuhmerangs wird für Gehorsam und Unterwürfigkeit sorgen.\n\nGeht weit hinaus zu den Kristallfeldern und diszipliniert jeden Peon, den Ihr beim Faulenzen erwischt. Zeigt ihnen die Macht des Schuhmerangs!", sourceObjective = "Chefvorarbeiter Lehmklump beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 faule Peons des Drachenmals zur Ordnung ruft. Gebt anschließend auch Euren Schuhmerang wieder zurück.", progress = "Der Trick liegt im Handgelenk, {name}.", completion = "Ein Tag harter Arbeit! Es zahlt sich aber aus, oder? Beim Anblick der schuftenden Taugenichtse bei den Kristallen wird einem richtig Warm um's Herz... Nun ja, das ist alles für heute. Kommt morgen wieder, dann könnt Ihr ein weiteres Mal den Schuhmerang schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11056] = { id = 11056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hazziks Handel", description = "Erwähnt unsere Unterhaltung nicht. Adaris würde nichts davon gutheißen.\n\nIch gehöre der niedrigsten Kaste der Arakkoa an, {name}. Während Terokks Herrschaft hätte man mich den dunklen Mächten geopfert, die von den Krallenpriestern verehrt werden. Sollte was Ihr sagt, wahr sein und sollten die Krallenpriester wirklich Terokks Rückkehr herbeisehnen, dann müsst Ihr dies unbedingt verhindern - ganz egal, was Euer Anführer sagt!\n\nIch habe etwas für Euch, das Ihr sehr nützlich finden werdet. Bei meiner alten Behausung im Oberen Shil'akversteck liegt ein Päckchen. Bringt es mir.", sourceObjective = "Sucht nach Hazziks Päckchen bei seiner Behausung im östlichen Skettis und kehrt damit zu ihm zurück.", progress = "{name}, Ihr seid zurück! Ich dachte schon, Ihr hättet mich im Stich gelassen.", completion = "Ausgezeichnet, {name}. Ihr werdet sehen, dass ich mein Wort halte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11057] = { id = 11057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwierigkeiten in der Tiefe", description = "Wir wissen Euren Eifer, uns hier in Ogri'la unterstützen zu wollen, sehr zu schätzen, {class}. Doch bevor wir Euer großzügiges Angebot annehmen können, müssen wir Euch zunächst um einen Gefallen bitten.\n\nUnsere Brüder dort unten sind Sklaven der Söhne von Gruul. Bitte, sprecht mit Mog'dorg dem Weisen. Er ist der Anführer einer Widerstandsbewegung der dort heimischen Oger gegen die Gronn.\n\nIhr findet ihn auf dem Turm, auf der östlichen Seite der Arena des Zirkels des Blutes.", sourceObjective = "Sprecht mit Mog'dorg dem Weisen. Ihr findet ihn auf einem der Türme außerhalb des Zirkels des Blutes im Schergrat.", completion = "Man hat Euch von hoch oben zu mir geschickt? Wahrlich, meine Mission ist gesegnet! Ich versuche die Blutschläger vor der Ausrottung durch den Speerspießerklan und Gruuls Söhne zu bewahren.\n\nIch nehme an, dass Ihr unsere geheime Organisation unterstützen und uns die Freiheit bringen werdet?", sourceObjectiveStatus = "unverified-source-field" }
quests[11058] = { id = 11058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Apexisrelikt", description = "Vor langer Zeit lebte hier eine Sekte der Arakkoa, die Apexis. Überreste ihrer seit langem ausgestorbenen Zivilisation sind auch heute noch allgegenwärtig. Wir nennen sie Apexisrelikte.\n\nDas Einzige, was wir mit Sicherheit wissen, ist, dass sie bei richtiger Benutzung einen Segen gewähren. Jedes Relikt repräsentiert eine farbige Sequenz, welche, wenn man die Kristalle in der richtigen Reihenfolge drückt, zu einer Serie von Stufen führen, eine schwieriger als die andere.\n\nEs wird ein Apexissplitter benötigt, um das Relikt zu aktivieren. Kehrt zurück, wenn Ihr mehr über die Apexisschwingungen erfahren habt.", sourceObjective = "Erlangt Apexisschwingungen von einem Apexisrelikt.", completion = "<Chu'a'lors Köpfe nicken Euch anerkennend zu.>\n\nIhr habt einen scharfen Verstand, {name}. Wir haben erheblich länger gebraucht, um das Relikt erfolgreich zu benutzen.\n\nNun, da Ihr wisst wie, könnt Ihr es so oft Ihr wollt verwenden. Denkt jedoch daran, dass für die Aktivierung eines Relikts immer ein Apexissplitter erforderlich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11059] = { id = 11059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wächter des Monuments", description = "Ihr habt erfolgreich herausgefunden, wie man die Ein-Personen-Relikte benutzt. Aber wie Ihr wahrscheinlich schon bemerkt habt, umgeben die kleineren noch größere Relikte.\n\nDiese großen Apexismonumente funktionieren auf die exakt gleiche Weise, allerdings werden 35 Apexissplitter benötigt, um sie zu aktivieren.\n\nViel größere Sorgen bereiten uns die Wächter, die bei der Benutzung eines Relikts beschworen werden. Diese Kristallkonstrukte haben sich vor langer Zeit gegen ihre Arakkoameister gewendet und gefährden nun Ogri'la.\n\nWir möchten Euch bitten, einen von ihnen zu zerstören und uns einen Beweis Eurer Tat zu bringen.", sourceObjective = "Beschafft den Kopf eines Apexiswächters.", progress = "Wir verabscheuen Gewalt, aber wenigstens ist das Konstrukt, das Ihr vernichten sollt, kein lebendiges Wesen.\n\nWo wir schon davon sprechen, habt Ihr den Kopf?", completion = "<Chu'a'lor mustert Euch voller Respekt.>\n\nEure und die geistige Gewandtheit Eurer Freunde ist wahrlich beeindruckend. Dafür, dass Ihr uns und unsere Lebensweise verteidigt habt, stehen wir, nein, stehen ganz Ogri'la und die Himmelswache in Eurer Schuld.\n\nDenkt daran {name}, Ihr könnt jederzeit mit einer Gruppe zurückkehren, um die großen Apexismonumente zu benutzen. Bringt aber genügend Apexissplitter mit, um sie aktivieren zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11060] = { id = 11060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kristallgeschmiedete Rune der Dunkelheit", progress = "Die Dämonen machen das Konstruktionslager: Wut größer. Bald sie zu stark sind und uns vernichten werden. Ihr sie zuerst schlagen müsst!\n\nShartuuls Transporter sein Schlüssel zu Sieg, aber er werden beschützt von magischem Schild und mächtigen Dämon, einem Zerrütter. Wir mächtiger Hexenmeister und wir Euch herstellen werden eine besondere Rune der Dunkelheit, mit der Ihr Zerrütter kontrollieren könnt. {race} geben GahkRune der Dunkelheit, wir geben {race} kristallgeschmiedete Rune der Dunkelheit.\n\nIhr übernehmen den Zerrütter und übernehmen Herrschaft über so viele aus dem Portal kommende Dämonen wie möglich, um sie aufzuhalten!", completion = "Kleiner {race}, nicht vergessen, wenn Ihr einen Zerrütter kontrollieren, Ihr müssen seinen Hammer dazu benutzen, um die Schilde von Warptor zu zerschlagen und den gefangenen Dämonen freizulassen.\n\nDann Ihr müssen zerschlagen diesen Dämon und ihn beherrschen. Dann kommen neuer Dämon, den Ihr auch beherrschen müssen, bis der Aufseher der Eredar auftauchen.\n\nDann Ihr auch ihn erschlagen werdet!!!" }
quests[11061] = { id = 11061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflichten eines Vaters", description = "Was das andere magische Fläschchen angeht, man bekommt es ausschließlich an einem Ort: der Landeplatz von Bash'ir. Es handelt sich um einen Stützpunkt der Astralen und sie sind Fremden gegenüber nicht gerade freundlich eingestellt, daher könnte es etwas gefährlich werden.\n\nSicherlich fragt Ihr Euch jetzt, wo man diesen Landeplatz von Bash'ir findet? Steigt auf Euer fliegendes Reittier und reist in Richtung Nord, Nordosten, bis Ihr ein gutes Stück hinter dem Konstruktionslager: Wut seid, dann müsstet Ihr den besagten Landeplatz sehen. Die Kristallschmiede von Bash'ir befindet sich in der nordöstlichen Ecke des Stützpunkts.\n\nDanke für Eure Hilfe, {name}. Es bedeutet unseren Söhnen alles!", sourceObjective = "Beschafft ihm ein instabiles Fläschchen des Zauberers.", progress = "Dieses Fläschchen des Zauberhexers wird meine Jungs sicherlich noch intelligenter machen, als sie es ohnehin schon sind. Damit sollten ihnen die täglichen Pflichten in der Himmelswache der Sha'tari etwas leichter fallen.", completion = "Wir können Euch gar nicht genug danken, {name}!\n\nSo instabil diese zwei Fläschchen auch sein mögen, mit ihrer Hilfe können wir nun einen unserer Jungs nach Norden zum Außenposten der Himmelswache schicken.\n\nWartet einen kleinen Augenblick, während wir einen von ihnen rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11062] = { id = 11062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Außenposten der Himmelswache", description = "{name}, wir haben uns gefragt, ob Ihr vielleicht nach Norden aufbrechen würdet, um unseren Freunden beim Außenposten der Himmelswache einen Besuch abzustatten?\n\nKommandant Keller und seine Himmelswache führen zu unserem Schutz diverse Unternehmungen durch und erst kürzlich bat er uns, jeden vorbeizuschicken, der Willens ist, sie bei ihrer Arbeit zu unterstützen.\n\nDas wäret dann wohl Ihr!\n\nBrecht so schnell wie möglich dorthin auf und übermittelt ihnen unsere besten Grüße.", sourceObjective = "Sprecht mit Himmelskommandant Keller beim Außenposten der Himmelswache im Schergrat.", completion = "Willkommen im Außenposten der Himmelswache. Wisst Ihr, ich habe den gesamten Posten mit meinen eigenen Händen errichtet.\n\nSchon richtig gehört, alles was Ihr hier vor Euch seht!\n\n<Dem Himmelskommandanten scheint es ernst zu sein.>\n\nIhr müsst ja ganz schön scharf auf einen Kampf sein, wenn Ihr extra hierher gekommen seid, um mit mir zu sprechen. Es war nett vom alten Chu'a'lor, Euch vorbeizuschicken. Wir können hier immer etwas Frischfleisch gebrauchen.\n\nWenn es Euch nichts ausmacht, würde ich vorschlagen, Ihr unterhaltet Euch ein wenig mit meinem Himmelsoffizier Vanderlip. Stört Euch nicht an ihrem Gebaren, ihre Zunge ist womöglich schärfer als das Breitschwert, das sie bei sich trägt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11063] = { id = 11063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich Flügel verdienen...", sourceObjective = "Ihr möchtet also zu den Himmelsteilern gehören, ja? Ihr habt Euch mit Sicherheit als fähiger Anhänger des Drachenmals bewiesen, aber in den Lüften der Scherbenwelt ist dies bedeutungslos. Es gibt eine Frage zu klären: KÖNNT IHR FLIEGEN?\n\nUnd ich frage nicht etwa, ob Ihr auf einen Netherdrachen steigen und wie diese Transportertrottel eine Ladung Kristalle zu der Festung liefern könnt. Ich rede davon, der Beste zu sein... der Toporc...\n\nDort drüben im Westen gibt es sechs Reiter. Besiegt sie alle und ich werde Euch Flügel der Himmelsteiler geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11064] = { id = 11064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Murg \"Grufti\" Moorbiss", description = "Lasst Euch von dem grauen Haar nicht täuschen, Grunzer. Ich bin trotz allem ein zehnmal so guter Reiter! Glaubt bloß nicht, dass dieser Totgesagte keine Tricks mehr im Ärmel hat.\n\nVersucht mir zu folgen und nicht von Eurem Reittier geworfen zu werden, das ist alles. Wenn Ihr das fertig bringt, wird Grufti seine Niederlage eingestehen.\n\nWir heben ab, sobald Ihr bereit seid.", sourceObjective = "Folgt Murg \"Grufti\" Moorbiss und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Murg \"Grufti\" Moorbiss besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ein Kinderspiel? Was ist nur aus den Helden geworden... Ich bin mir sicher, dass die anderen Reiter eine größere Herausforderung sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11065] = { id = 11065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigt ein paar Ätherrochen!", description = "Wollt Ihr der Himmelswache und Ogri'la aushelfen?\n\nHört mir erst zu, bevor Ihr einfach davonrennt, <Junge/Mädel>. Wir benötigen dringend mehr Reittiere. Die Missionen und Bombenangriffe auf den Landeplatz von Bash'ir haben uns so manches Reittier gekostet.\n\nDie Ätherrochen, die beim Vortexgipfel und am Kristallrücken herumfliegen, sollten für unsere Zwecke genügen. Ihr müsst sie nicht einmal hierher zurückbringen, obwohl das nett wäre. Bändigt sie einfach und bindet sie irgendwo an, wir holen sie dann später ab.\n\nSeid Ihr dieser Aufgabe gewachsen?", sourceObjective = "Bändigt mithilfe des Bändigungsseils 5 Ätherrochen.", progress = "Habt Ihr schon ein paar Ätherrochen gebändigt? Ihr seht so aus, als könntet Ihr mit einem Lasso umgehen. Sicher habt Ihr Euren Auftrag schnell abgeschlossen.", completion = "Juhuu! Gute Arbeit, {name}! Diese Rochen werden ein paar hervorragende Reittiere abgeben!\n\nBleibt ruhig noch ein wenig, die Himmelswache der Sha'tari kann Männer mit Euren Talenten immer gut gebrachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11066] = { id = 11066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigt noch mehr Ätherrochen!", description = "Ich hoffe Ihr seid bereit, noch ein paar mehr Ätherrochen zu bändigen! Soweit ich das beurteilen kann, liegt Euch der Umgang mit dem Seil im Blut!\n\nUnd es dient einem guten Zweck, denn so kriegen wir nicht nur frische Reittiere, sondern Ihr helft uns auch noch Ogri'la zu beschützen, wofür die Oger dankbar sind.\n\nNicht vergessen, die Ätherrochen fliegen beim Vortexgipfel und am Kristallrücken im Nordosten herum.\n\nSchafft Ihr es, noch ein paar mehr für mich zu bändigen?", sourceObjective = "Bändigt mithilfe des Bändigungsseils 5 Ätherrochen.", progress = "Ihr leistet hervorragende Arbeit für uns, {name}! Ich möchte Euch nur wissen lassen, dass wir Eure Bemühungen, uns mit frischen Reittieren zu versorgen, sehr zu schätzen wissen!", completion = "Ihr erstaunt mich immer wieder! Ich sage Euch was, warum lasst Ihr das Lasso nicht für heute ruhen und wir sehen uns morgen wieder?\n\n<Khatie lacht.>\n\nNochmals vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11067] = { id = 11067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Trope der Rußhuster", description = "Das Drachenmal behandelt einen richtig, {name}. Selbst so ein ausgelaugtes und gezeichnetes Wesen wie ich bekommt seine Chance. Wenn Ihr Euch den Himmelsteilern als würdig erweisen wollt, dann müsst Ihr mich besiegen.\n\nIch werde Euch wie einen Schwarm lästige Fliegen abschütteln...\n\nWir heben ab, sobald Ihr bereit seid.", sourceObjective = "Folgt Trope dem Rußhuster und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Trope den Rußhuster besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Interessant... Euer nächstes Rennen wird sich zweifellos als viel schwieriger erweisen. Corlok ist kein Weichei.", sourceObjectiveStatus = "unverified-source-field" }
quests[11068] = { id = 11068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Corlok der Veteran", description = "Ihr fordert MICH heraus? Jetzt muss ich aber lachen!\n\nIst das Euer Ernst? Na gut! Achtet lediglich darauf, nicht zu sterben. Ihr schafft das doch, nicht zu sterben, oder?? Auch wenn ich Schädel nach Euch werfe und in Kreisen um Euch und Eure erbärmlichen Flugkünste fliege?\n\nLasst mich einfach wissen, wann's losgehen kann, dann heben wir ab.", sourceObjective = "Folgt Corlok dem Veteranen und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Corlok den Veteranen besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Die nächsten zwei Reiter sind die besten Piloten, die die Zwerge und Orcs von Azeroth zu bieten hatten. Ihr habt keine Chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[11069] = { id = 11069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Schwadronskommandant Ichman", description = "Drei Jahre habe ich in diesem Loch zugebracht. Drei Jahre lang war ich Kriegsgefangener des verdammten Frostwolfklans. Ich musste in ihrem Turm sitzen und ihr endloses Gejammer über die Brücke nach Dun Baldar ertragen. Wie \"ungerecht\" es doch sei, dass bla, bla, bla, bla... Im Krieg gibt es keine Gerechtigkeit! Zur Hölle mit ihnen allen!\n\nIn dem Augenblick, in dem ich befreit wurde, habe ich diesen Ort für immer verlassen und bin hierhergekommen, um ein neues Leben zu beginnen. Mulv und ich konkurrieren jetzt um den Platz des Toporcs. Sollte das auch Euer Ziel sein, dann müsst Ihr erstmal an mir vorbei, Anfänger.\n\nEs geht los, wenn Ihr bereit seid.", sourceObjective = "Folgt Schwadronskommandant Ichman und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Ichman besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ich glaube es nicht! Mulverick ist Eure nächste Herausforderung. Dieses Rennen werdet Ihr auf keinen Fall überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11070] = { id = 11070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Schwadronskommandant Mulverick", description = "Drei Jahre lang Blut, Schweiß und Tränen. Hauptsächlich Tränen... Es ist erstaunlich, wie viele Tränen selbst ein hartgesottener Soldat vergießt, wenn es im Krieg zur Sache geht.\n\n\"Sie springen mit ihren Pferden in unseren Turm!\" \"Warum muss die feindliche Basis so gut verteidigt sein?\" \"Verdammt, der Feind hat die Heilerhütte erobert, ich mache mich vom Acker!\"\n\nVerdammte Feiglinge...\n\nKaum war das Dunkle Portal offen, hab' ich die Möglichkeit beim Schopfe gepackt und mich aus dem Land der Weicheier verabschiedet. Jetzt arbeite ich als Toppilot für die Jungs des Drachenmals. Wenn Ihr also der Toporc werden wollt, müsst Ihr mich erst einmal schlagen.\n\nEs geht los, sobald Ihr bereit seid.", sourceObjective = "Folgt Schwadronskommandant Mulverick und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Schwadronskommandant Mulverick besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Nun Grunzer, es sieht ganz so aus, als gäbe es jetzt nur noch Euch und den Hauptmann. Viel Glück! Ihr werdet es brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11071] = { id = 11071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenmalrennen: Hauptmann Himmelsdonner", description = "Ihr wagt es, Himmelsdonner herauszufordern? Die Welt um Euch herum wird in Dunkelheit versinken, wenn meine Meteore den Horizont zerreißen.\n\nIhr habt keine Chance, Soldat. Offenbar ist es jedoch Euer Wunsch, zu sterben...\n\nIch werde bei Eurem morbiden Vorhaben mitspielen. Vielleicht kann ich anderen Narren, die nach der gleichen Verrücktheit streben, zumindest eine Lehre erteilen.\n\nWir reiten los, wenn Ihr bereit seid!", sourceObjective = "Folgt Hauptmann Himmelsdonner und versucht auf Eurem Reittier zu bleiben. Solltet Ihr Hauptmann Himmelsdonner besiegen, berichtet Ja'y Nosliw beim Basislager des Drachenmals im Schattenmondtal von Eurem Erfolg.", completion = "Ich hätte es mir nie träumen lassen, dass es jemanden gibt, der talentiert genug ist und Himmelsdonner besiegen kann. Wisst Ihr was das bedeutet, ja? Ihr seid jetzt der Toporc! Ihr müsst Euren Titel verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11072] = { id = 11072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindesblut", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Karrog der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Benutzt sie bei den Beschwörungskreisen, die es in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mitzunehmen.", sourceObjective = "Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[11073] = { id = 11073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokks Fall", description = "Ich... ich habe bezüglich Eures Verhaltens gegenüber dem Arakkoagefangenen ein Auge zugedrückt, {name}. Es sieht ganz so aus, als hätte Euch Euer Instinkt nicht getäuscht. Es war richtig, mit ihm zusammenzuarbeiten.\n\nBitte versteht... Ich hätte mich in der jetzigen Lage inmitten eines Aufruhrs wiedergefunden, hätte ich Eure Bemühungen, Terokk in diese Welt zu bringen, gebilligt.\n\nNehmt die Gegenstände, die Hazzik für Euch zusammengestellt hat und führt Euren Plan weiter fort. Ich werde meinen Männern befehlen, Euch Rückendeckung zu geben, wenn es an der Zeit dafür ist. Ich rate Euch, auch selbst Verstärkung mit Euch zu bringen. Ich fürchte Ihr habt nur diese eine Chance.", sourceObjective = "Bringt die Zeitverlorene Opfergabe, die Hazzik angefertigt hat, zu dem Schädelhaufen im Zentrum von Skettis. Beschwört Terokk und bezwingt ihn. Habt Ihr Eure Aufgabe erfüllt, kehrt zu Himmelskommandant Adaris zurück.", completion = "Ihr habt uns alle sehr stolz gemacht, {name}. Ich werde die Kunde von Euren Taten in Shattrath verbreiten. Die Himmelswache steht für immer in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11074] = { id = 11074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Nachfahren", description = "Die Nachfahren, die von den Krallenpriestern von Skettis gefangen gehalten werden, sind alle in diesem Buch aufgeführt. Gezzarak die Jägerin, Garogg der Kristallriese, der Ketzer namens Dunkelkreischer Akkarai und Vakkiz der Windzürner. Sie alle müssen getötet werden, bevor Terokk in diese Welt zurückkehrt.\n\nIhr werdet die Schriftrollen benötigen, die die zeitverlorenen Arakkoa bei sich tragen. Verbrennt sie bei den Beschwörungskreisen, die es überall in Skettis gibt. Bringt mir von einem jeden ein Beweisstück. Eure Gegner sind mächtige Wesen; Ihr tätet gut daran, ein paar Freunde mit Euch zu bringen.", sourceObjective = "Sammelt zeitverlorene Schriftrollen von den zeitverlorenen Arakkoa in Skettis ein und bringt sie zu den Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört und bezwingt die Nachfahren der Gegner Terokks und kehrt zu Hakkiz mit Akkarais Kralle, Garokks Stachel, Vekkaz' Schuppe und Gezzaraks Klaue zurück.", progress = "Ich benötige einen Gegenstand von jedem der Nachfahren von Terokks ärgsten Feinden. Nur dann können wir Terokk beschwören.", completion = "Hervorragend! Hier, nehmt dies. Ich habe dieses Bündel aus den Gegenständen erstellt, die Ihr mir gebracht habt. Damit werdet Ihr Terokk beschwören können.\n\nSeid auf der Hut, {name}. Er ist der mächtigste Arakkoa aller Zeiten. Unterschätzt ihn nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[11075] = { id = 11075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Netherschwingenminen", description = "Wir benötigen Eure Hilfe bei den Netherschwingenminen, Aufseher {name}.\n\nVor zwei Tagen machten wir eine düstere Entdeckung und daraufhin kamen unsere Minenarbeiten zum Stillstand. Ein Minenarbeiter arbeitete in den Tiefen der Mine und hieb seine Hacke in eine ungewöhnliche Kristallformation. Unglücklicherweise war diese Kristallformation mit einem sehr verärgerten Netherdrachen verbunden. Die Bestie erwachte aus ihrem Schlaf und tötete all unsere Arbeiter.\n\nErstattet bei der Herrin der Minen Bericht. Man erwartet Euch beim Eingang der Minen, südwestlich von hier.", sourceObjective = "Sucht die Herrin der Minen auf der Netherschwingenscherbe auf.", completion = "Die Minenarbeiter leisten harte Arbeit, aber keiner von ihnen wagt es, einen Schritt tiefer in die Minen zu setzen. Sie sterben lieber, als dass sie sich tiefer in die Minen zwingen lassen! Es wird Eure Aufgabe sein, die von ihnen vernachlässigten Pflichten zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11076] = { id = 11076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dinge in den Griff bekommen...", description = "Die Mühen unserer harten Arbeit liegen überall in diesen Minen verstreut. Wagenladungen voller Fracht bedecken jeden Zentimeter dieser Mine! Auf Grund der Plage kommen wir nur an nichts von alledem heran.\n\nGenau hier kommt Ihr ins Spiel, {name}. Eure tägliche Arbeit bei der Mine wird aus dem Einsammeln der von den Minenarbeitern und Tiefenminenarbeitern zurückgelassenen Fracht bestehen.\n\nSammelt die Fracht der Netherminen ein und kehrt zu mir oder meiner Schwester zurück.", sourceObjective = "Die Herrin der Minen bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Kisten mit Fracht der Netherminen einsammelt.", progress = "Habt Ihr die Fracht eingesammelt?", completion = "Gut gemacht, {name}. Kommt morgen für einen weiteren Einsatz in den Tiefen der Mine wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11077] = { id = 11077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachen sind unsere geringste Sorge", description = "Als der Drache erwachte, schreckte er in diesen Minen noch ganz andere bösartige Kreaturen auf. Insbesondere zwei Arten sind dem Drachenmal ein Dorn im Auge: Netherminenschinder und Netherminenhetzer. Ihr müsst uns helfen, sie alle zu töten. Ich bitte Euch lediglich einmal pro Tag um Eure Mithilfe.\n\nGeht hinein und vernichtet so viele, wie Ihr nur könnt!", sourceObjective = "Der Vorarbeiter des Drachenmals bei den Netherschwingenminen im Schattenmondtal möchte, dass Ihr 15 Netherminenschinder und 5 Netherminenhetzer tötet.", completion = "Das sollte für heute reichen, Aufseher. Kommt morgen für eine weitere Aufräumrunde wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[11078] = { id = 11078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel beherrschen", description = "Während Ihr herumgeflogen seid, sind Euch sicherlich die Drachen aufgefallen. Schätze, ihr Zorn blieb Euch bisher erspart. Helft uns, diese Biester ein für alle Mal zu erledigen, {name}!\n\nNachtreißer und Obsidia beherrschen dieses Plateau, während Insidion und Zornschwinge den Himmel über den Terrassen im Nordosten für sich beanspruchen. Jeder der Drachen hat ein Nest in seinem Revier gebaut. Ich frage mich, ob Ihr und Eure Freunde einen aufsuchen würdet, <Kumpel/Mädel>. Brecht ein Ei mit 35 Apexissplittern auf, um den Drachen herunterzulocken.\n\nBringt mir ein paar Zähne als Beweis.", sourceObjective = "Beschafft Euch Drachenzähne.", progress = "Wie geht es voran, {name}? Ich brauche Euch sicherlich nicht extra zu sagen, wie wichtig die ganze Angelegenheit für unsere Luftüberlegenheit ist.", completion = "Ja! Diese Zähne sehen scharf aus, als könnten sie beinahe alles wie Butter durchschneiden!\n\nErlaubt mir, Euch und Eure Freunde dazu zu ermuntern, weiterhin so gute Arbeit zu leisten! Diese Drachen sind gefährliche Raubtiere, die unseren Himmel lange genug unsicher gemacht haben.\n\nEuch sind sicherlich die Drachenschuppen aufgefallen. Wie ich hörte, kann man aus ihnen einen mächtigen Umhang herstellen, sofern man eine Schuppe von jedem der Drachen besitzt. Sollte Euch der Umhang nicht zusagen, bin ich jederzeit bereit, ihn gegen einen Apexiskristall einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11079] = { id = 11079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Teufelspeitsche für Gahk", description = "Gahk manchmal glauben, es nicht gut ist, schlau zu sein. Ghak möchten nicht so viel nachdenken müssen. Ich wollen, dass <kleiner/kleine:r> {race} große Dämonen totschlagen!\n\nSie haben einige Anführer und jeder von ihnen haben Peitschen, um den mickrigen Dämonen Verstand einzuprügeln. Gahk wollen so eine Peitsche!\n\nDazu Ihr herausfordern müssen einen Dämonenanführer in Konstruktionslager. Einen solchen Ihr finden bei brennenden, grünen kristallinen Teufelsprisma. Benutzen 35 Apexissplitter, um sie zu rufen. Sie hören auf Namen wie Galvanoth, Braxxus, Zarcsin und der Verbrenner der Mo'arg.", sourceObjective = "Beschafft Euch eine Teufelspeitsche.", progress = "Ihr haben Peitsche?", completion = "Gahk mögen Peitsche. Vielleicht Ghak nehmen Peitsche und bearbeiten ein paar Dämonen!\n\nMich sagen zu {race}, dass {race} kann jederzeit beschwören Dämonenanführer, solange {race} haben viele Freunde und 'ne Menge Splitter.", sourceObjectiveStatus = "unverified-source-field" }
quests[11080] = { id = 11080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strahlung des Relikts", description = "Nachdem Ihr die erleuchtenden Schwingungen der Apexisrelikte am eigenen Leib erfahren habt, ist es an der Zeit, ein tieferes Verständnis für die Funktionsweise der Relikte zu bekommen. Wir würden von Euren Beobachtungen profitieren.\n\nJe mehr Eure Fähigkeiten wachsen, Euch auf die Kräfte der Relikte einzustellen, desto mehr Wissen werdet Ihr über sie erlangen. Ist es erst einmal soweit, wird Euch ein Strahlungsausstoß des Relikts Euren Erfolg anzeigen.\n\nKehrt zu uns zurück, wenn Ihr eine solche Strahlungsaura erlangt habt.", sourceObjective = "Erlangt Apexisstrahlung von einem Apexisrelikt.", progress = "Habt Ihr eine Aura der Apexisstrahlung von dem Apexisrelikt erlangt?", completion = "Euer Geschick im Umgang mit den Relikten erstaunt uns immer wieder, {name}. Dürften wir Euch vorschlagen, mindestens einmal am Tag den Gebrauch der Relikte zu üben, damit Euer Verstand seine Schärfe bewahrt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11081] = { id = 11081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Aufstand der Finsterblut", description = "Dieses Schriftstück beschreibt einen von den Zerschlagenen der Finsterblut geplanten Aufstand. Offenbar diente der Drache der allgemeinen Zerstreuung, um von ihrer Flucht abzulenken. Beim Betrachten der überall in der Mine herumliegenden Leichen, könnte man von einem Fehlschlag ihres Plans ausgehen.\n\nBringt die Fluchtpläne zur Herrin der Minen.", sourceObjective = "Bringt die Fluchtpläne der Finsterblut zur Herrin der Minen.", progress = "Was ist das?", completion = "Ausgezeichnete Arbeit, Aufseher. Man wird Mor'ghor von Euren herausragenden Taten für das Drachenmal berichten.\n\nLasst uns jetzt wieder auf diese Hunde der Finsterblut zu sprechen kommen. Sie planen ihre Flucht, ja? Sie wagen es, sich dem einzig wahren Fürsten der Scherbenwelt zu widersetzen? Ihre Meister werden dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11082] = { id = 11082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Wahrheit", description = "Diese Minenarbeiter sind viel zu dumm, als dass sie irgendeinen Fluchtplan aushecken könnten. Wir müssen die Quelle des Übels finden und bestrafen. Wagt Euch in die Tiefen der Minen und sucht nach den Aufpassern der Finsterblut. Wenn sie nicht schon von den Bewohnern der Minen überwältigt wurden, so halten sie sich zweifellos versteckt.\n\nSolltet Ihr einen von ihnen ausfindig machen, verhört ihn so lange, bis er das wahre Gehirn, das hinter diesem Fluchtplan steckt, preisgibt. Kehrt mit der Identität des Verräters und der Hand des Aufpassers zu mir zurück.", sourceObjective = "Findet einen Aufpasser der Finsterblut und verhört ihn. Kehrt mit den Informationen der Finsterblut und mit der Hand des Aufpassers zur Herrin der Minen zurück.", progress = "Nun? Warum dauert das so lange?", completion = "Nichts zu sagen? Vielleicht erinnert er sich ja, wenn er auf dem Boden dieser verfluchten Mine zu Tode blutet... Vergesst nie, was es bedeutet, die Mächte Illidans herauszufordern!", sourceObjectiveStatus = "unverified-source-field" }
quests[11083] = { id = 11083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrückt und verwirrt", description = "Sorgt Euch nicht wegen diesem Drachen, {name}. Wir haben bereits Pläne für ihn...\n\nTiefer in der Mine gibt es eine verrückte Schar der Finsterblut. Nachdem der Drache ausgebrochen ist, wurde ihnen der Weg zum Ausgang versperrt. Nach zwei Tagen der Abgeschiedenheit scheinen sie auf irgendeine Art und Weise jegliche Würde verloren zu haben.\n\nSie haben sich dem Kannibalismus und der Gewalt verschrieben. Dieser Wahnsinn ist hier alles andere als erwünscht. Findet und tötet sie. Alle!", sourceObjective = "Ronag der Sklaventreiber in den Netherschwingenminen im Schattenmondtal möchte, dass Ihr den verrückten Großknecht der Finsterblut und 5 verrückte Minenarbeiter der Finsterblut tötet.", completion = "Ja, ich verstehe das nicht... Man würde doch meinen, dass sie nach zwei Tagen nicht derart ausgehungert sein können. Finsterblut...\n\n<Ronag schüttelt den Kopf.>\n\nSowas von dämlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11084] = { id = 11084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid gegrüßt, Hauptmann!", description = "Nun sieh einer an... Ihr lebt also noch. Das trifft sich gut, denn Mor'ghor hat nach Eurer sofortigen Anwesenheit in seinem Turm verlangt. Los mit Euch!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "<Mor'ghor nickt.>\n\nGanz recht, ich habe Hauptmann gesagt. Ihr habt Euch eine weitere Beförderung verdient, {name}.\n\nIhr arbeitet wirklich wie keiner der Höllenorcs, die ich bis jetzt gesehen habe. Macht weiter so, dann schafft Ihr es vielleicht eines Tages zum Oberanführer.\n\nZieht jetzt los und übernehmt das Kommando. Ich schlage vor, dass Ihr versucht, Euch Eure Flügel der Himmelsteiler zu verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11085] = { id = 11085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Skettis", description = "Seid gegrüßt, {name}. Ich danke Euch, dass Ihr mir zu Hilfe gekommen seid.\n\nIch war auf einer Erkundungsmission, als mich die riesigen Vögel der Arakkoa von meinem Netherrochen rissen.\n\nVerschwinden wir von hier, solange es noch geht!", sourceObjective = "Begleitet die gefangene Himmelswache in Sicherheit und meldet Euch anschließend bei Himmelsoffizier Doryn.", completion = "Danke, dass Ihr unseren Späher gerettet habt, {name}. Jeden Tag verlieren wir gute Leute und es kommen beileibe nicht genug Rekruten nach, um sie alle zu ersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11086] = { id = 11086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwächt das Portal des Zwielichts", description = "Als Hauptmann des Drachenmals liegt es in Eurem Verantwortungsbereich, sämtliche Unternehmungen der Brennenden Legion in der Scherbenwelt auszulöschen. Es ist Eure Pflicht, die zum Schweigen zu bringen, die sich Fürst Illidan widersetzen!\n\nDie Dämonen versuchen törichterweise das Portal auf der Zwielichthöhe im Westen von Nagrand zu stabilisieren. Sie müssen für ihren Verrat bezahlen. Ihr werdet der Orc sein, der für die Begleichung ihrer Schulden sorgt.\n\nReist zur Zwielichthöhe und vernichtet die dortigen Bewohner. Ihr seid dafür verantwortlich, täglich mindestens einen Angriff auf ihre Stellungen durchzuführen.", sourceObjective = "Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr 20 Agenten der Todesschatten tötet.", completion = "Ausgezeichnete Arbeit, Hauptmann! Fürst Illidan wird von Euren Heldentaten erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[11087] = { id = 11087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flagge von Hyjal", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.\n\nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.", sourceObjective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11089] = { id = 11089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seelenkanone Reth'hedrons", description = "Reth'hedron herrscht jetzt über die Zwielichthöhe in Nagrand. Ein Eredar von solch großer Macht, der auf diese Welt losgelassen wurde, verheißt nichts Gutes für die Illidari. Ach, uns fehlt es einfach an den benötigten Ressourcen, um Reth'hedron vernichten zu können. Schon gar nicht mit dem Krieg, den die Sha'tar zum Schwarzen Tempel getragen haben. Nein... ich habe einen besseren Plan.\n\nIhr werdet Reth'hedron unterdrücken, ihn zurück durch das Portal des Zwielichts verbannen. Für diesen Zweck muss eine Seelenkanone angefertigt werden.\n\nKehrt zu mir mit den Materialien auf der Liste zurück.", sourceObjective = "Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal möchte, dass Ihr ihm 2 Teufelsstahlbarren, 1 Adamantitrahmen, 1 Khoriumkraftkern und 1 makellose arkane Essenz bringt.", progress = "Habt Ihr die benötigten Bauelemente für die Anfertigung der Seelenkanone?", completion = "<Balthas fügt die Elemente, die Ihr ihm gebracht habt, geschickt zusammen.>\n\nIhr seid jetzt bereit für den zweiten Teil des Plans, Hauptmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11090] = { id = 11090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterdrückt den Unterdrücker", description = "<Balthas hält ein fremdartiges Gerät in die Höhe.>\n\nDies ist eine Seelenkanone. Die Auswirkungen können bei der richtigen Abstimmung verheerend sein. Diese ist auf mein Blut abgestimmt. Dasselbe Blut, das auch durch die Adern von Reth'hedron fließt - meinem Bruder. Ja, seine falsche Loyalität wird sein Ende sein.\n\nNehmt die Kanone und fliegt zur Zwielichthöhe im westlichen Nagrand. Findet Reth'hedron und feuert! Ihr müsst auf Eurem Reittier bleiben und Euch in Reichweite befinden, damit die Auswirkungen erfolgreich sind. Behauptet Euch ihm gegenüber und er wird keine andere Wahl haben als zu fliehen!", sourceObjective = "Illidarifürst Balthas beim Basislager des Drachenmals im Schattenmondtal hat Euch den Auftrag gegeben, die Seelenkanone auf Reth'hedron den Unterdrücker in Nagrand anzuwenden.\n\nBringt auch die Seelenkanone wieder zurück.", progress = "Ist es vollbracht?", completion = "Er wird zurückkehren, aber für den Moment hat der Krieg der Legion gegen Fürst Illidan eine Schwäche erfahren. Man wird ihm von Euren Taten berichten, Hauptmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11091] = { id = 11091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Dank an Euch", description = "Die in unserem Namen auf Euch genommenen Anstrengungen ehren uns. Es gibt da jemanden, den Ihr unbedingt kennenlernen solltet.\n\nJho'nass ist unser bester Rüstmeister. Er verwaltet eine ganze Reihe von auserlesenen Waren, die nur den engsten Verbündeten von Ogri'la zum Kauf angeboten werden.\n\nIhr seid ein solcher Verbündeter, {name}.\n\nWenn Ihr etwas Zeit erübrigen könnt, solltet Ihr ihn unbedingt aufsuchen. Soweit wir wissen, hat er, als Zeichen unserer Dankbarkeit, eine Kleinigkeit für Euch vorbereitet.", sourceObjective = "Sprecht mit Jho'nass in Ogri'la im Schergrat.", completion = "Hey, Mann, das ist toll! Wir haben viel von Euren guten Taten gehört. Das ist fantastisch. Wir haben da so ein Gefühl, dass Ihr für Ogri'la alles zum Guten wenden werdet. Ihr werdet uns beschützen und alles wird heiter und sonnig!\n\nHier, nehmt das. Es ist ein kleines Überlebenspaket, dass wir zum Dank für Euch zusammengestellt haben.\n\nWerft doch bitte einen Blick auf unsere Waren. Wir haben eine reichhaltige Auswahl der erlesensten Gegenstände, von denen Euch sicherlich das eine oder andere Stück interessieren wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11092] = { id = 11092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glück auf, Kommandant!", description = "Hauptmann {name}!\n\n<Zuchtmeister Varkule grüßt Euch.>\n\nOberanführer Mor'ghor möchte, dass Ihr Euch umgehend bei ihm meldet!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Fürst Illidan hat mich höchstpersönlich mit Eurer Beförderung zum Kommandanten beauftragt! So etwas hat es noch nie gegeben. Ihr seid der Erste des Drachenmals, der solch einen Rang außerhalb des Schwarzen Tempels erlangt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11093] = { id = 11093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Netherrochen", description = "Hat man einen Netherrochen erst einmal richtig gezähmt, dann ist er ein loyales und gehorsames Reittier. Unglücklicherweise beansprucht der Krieg bei Skettis unsere Netherrochen über Gebühr.\n\nTäglich müssen wir dutzende von Einsätzen fliegen, sodass die armen Tiere kaum zur Ruhe kommen. Und seit uns auch noch das Futter ausgegangen ist, können die armen Biester froh sein, wenn sie einer der Vogelmenschen erledigt, bevor es der Hunger tut.\n\nWenn Ihr uns zur Hand gehen wollt, nehmt Euch einen unserer Rochen und führt ihn in die Wälder im Süden aus. Sie essen das Fleisch der dort lebenden Schattenwindhetzer, vorausgesetzt, man hat sie gerade frisch erlegt.", sourceObjective = "Benutzt den Netherrochenkäfig in den Wäldern südlich des Schattenwindlagers und erlegt in der Nähe des hungrigen Netherrochens einige Schattenwindhetzer. Kehrt anschließend zu Deesak dem Tierführer der Himmelswache zurück.", progress = "Ihr seid also zurück! Hat sich der Rochen auch gut benommen?", completion = "Vielen Dank {name}, dass Ihr Euch um den Rochen gekümmert habt. Mit vollem Magen fliegen diese Burschen gleich viel besser. Schließlich sollen unsere Jungs nicht abgeschossen werden, nur weil ihre Netherrochen zum Fliegen zu schwach waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11094] = { id = 11094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Kommandant {name}, stillgestanden! Ihr werdet mit einem Bataillon von Himmelsteilern losziehen und den Außenposten der Seher am Fuße der Netherschwingenfelder ausradieren. Ist das Sanktum der Sterne erst einmal zerstört, stehen uns die Verbindungswege zu unseren Posten bei der Stätte der Mondfinsternis und bei der Stätte der Illidari erneut wieder offen.\n\nLos jetzt! Benutzt diese Leuchtpistole, um den Himmelsteilern das Zeichen zum Angriff zu geben!", sourceObjective = "Überbringt Arkanist Thelis beim Sanktum der Sterne im Schattenmondtal die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals.", progress = "Beruhigt Euch, Kind.", completion = "Es war gut, dass Ihr zu uns gekommen seid. Vielleicht können wir diesen Angriff des Drachenmals zu unserem Vorteil nutzen und den Spieß umdrehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11095] = { id = 11095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Hobb", description = "Das Drachenmal wagt es nur dann, uns anzugreifen, wenn unsere Abwehr geschwächt ist. Sie hätten einige Niederlagen hinzunehmen, wenn wir auf ihre Angriffe vorbereitet wären.\n\nIch möchte, dass Ihr sie zu uns führt, {name}.\n\n<Thelis nickt.>\n\nJa... in eine Falle. Nehmt die Leuchtpistole, die Euch ihr Oberanführer gegeben hat, und bringt sie zu Kommandant Hobb. Er steht direkt außerhalb dieses Gebäudes Wache.", sourceObjective = "Bringt die Leuchtpistole des Drachenmals zu Kommandant Hobb beim Sanktum der Sterne im Schattenmondtal.", progress = "<Hobb nickt.>", completion = "<Hobb grinst.>\n\nDie tödlichste Falle aller Zeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11096] = { id = 11096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung von oben", description = "So, Ihr wollt also der Himmelswache beitreten? Nun, ich weiß, dass Ihr fliegen könnt, aber vermögt Ihr auch zu kämpfen?\n\nDie Himmelswache hat einst geschworen, Shattrath vor allen drohenden Gefahren, egal ob nah oder fern, zu schützen. Die bei der Hügelwand im Norden lebenden Oger der Gordunni stellen eine unmittelbare Bedrohung für uns dar.\n\nEs erwies sich als sehr schwer für unsere Bodentruppen, die Oger zu erreichen. Hier kommen wir ins Spiel. Seht was Ihr tun könnt, um die Oger im Zaum zu halten.", sourceObjective = "Tötet bei der Hügelwand 20 Oger der Gordunni und kehrt anschließend zu Yuula in Shattrath zurück.", completion = "Gute Arbeit, Fliegerass! Ich habe das Gefühl, dass Ihr hier sehr gut hineinpasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11097] = { id = 11097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tödlichste Falle aller Zeiten", description = "Nehmt diese Medaillen der Seher. Mor'ghor wird einen Siegesbeweis sehen wollen, wenn all das hier vorüber ist. Er wird sie als Beute von den gefallenen Soldaten der Seher wiedererkennen.\n\nJetzt gilt es noch das Leuchtsignal abzufeuern, um die Räuber des Drachenmals herbeizurufen. Sobald Ihr bereit seid, werden wir sie niederschmettern. Gebt mir einfach den Befehl.", sourceObjective = "Helft Kommandant Hobb und den Sehern bei der Verteidigung des Sanktums der Sterne. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Seher zurück.", progress = "Habt Ihr sie mit Euren Fäusten zerschmettert, Kommandant?", completion = "<Mor'ghor lacht.>\n\nHAHA! Ich habe gewusst, dass ich auf Euch zählen kann, Kommandant! Ich möchte, dass Ihr das Sanktum der Sterne mindestens einmal pro Tag überfallt. Sie werden keine andere Wahl haben und das Schattenmondtal verlassen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11098] = { id = 11098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Skettis!", description = "Die Hügelwand ist nur eine der vielen Fronten, an denen wir eingesetzt werden. Eine nicht unmittelbare, aber dennoch sehr große Bedrohung lauert hinter den Skethylbergen, in Form der Arakkoastadt Skettis.\n\nVor einigen Monaten entdeckten unsere Späher dort einen massiven Anstieg der Arakkoaaktivitäten. Daraufhin erfolgte eine ganze Reihe von Angriffen auf Shattrath. Seitdem haben wir einige unserer Streitkräfte außerhalb ihrer Stadt stationiert.\n\nNehmt diese Sprengladungen und bringt sie zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis. Sagt ihm einfach, Ihr wäret <der neue Rekrut/die neue Rekrutin>.", sourceObjective = "Bringt das Paket mit Sprengladungen zu Himmelsoffizier Doryn beim Schattenwindlager außerhalb von Skettis.", progress = "Ihr habt etwas für mich?", completion = "Danke für den Nachschub, wir werden ihn zu verwenden wissen! Ein neuer Rekrut? Dann wollen wir doch mal sehen, aus welchem Holz Ihr geschnitzt seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[11099] = { id = 11099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Kommandant {name}, stillgestanden! Ihr werdet mit einem Bataillon von Himmelsteilern losziehen und den Außenposten der Aldor nordwestlich unseres geliebten Schwarzen Tempels ausradieren. Ist der Altar der Sha'tar erst einmal zerstört, stehen uns die Verbindungswege zu unseren Posten bei der Echsennarbe erneut wieder offen.\n\nLos jetzt! Benutzt diese Leuchtpistole, um den Himmelsteilern das Zeichen zum Angriff zu geben!", sourceObjective = "Überbringt Anachoret Ceyla beim Altar der Sha'tar die Neuigkeiten von Eurem Einsatz zusammen mit der Leuchtpistole des Drachenmals.", progress = "Beruhigt Euch, Kind.", completion = "Es war gut, dass Ihr zu uns gekommen seid. Vielleicht können wir diesen Angriff des Drachenmals zu unserem Vorteil nutzen und den Spieß umdrehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11100] = { id = 11100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Arcus", description = "Das Drachenmal wagt es nur dann, uns anzugreifen, wenn unsere Abwehr geschwächt ist. Sie hätten einige Niederlagen hinzunehmen, wenn wir auf ihre Angriffe vorbereitet wären.\n\nIch möchte, dass Ihr sie zu uns führt, {name}.\n\n<Ceyla nickt.>\n\nJa... in eine Falle. Nehmt die Leuchtpistole, die Euch ihr Oberanführer gegeben hat, und bringt sie zu Kommandant Arcus. Er steht direkt außerhalb dieses Gebäudes Wache.", sourceObjective = "Bringt die Leuchtpistole des Drachenmals zu Kommandant Arcus beim Altar der Sha'tar im Schattenmondtal.", progress = "<Arcus nickt.>", completion = "<Arcus grinst.>\n\nDie tödlichste Falle aller Zeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[11101] = { id = 11101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tödlichste Falle aller Zeiten", description = "Nehmt diese Medaillen der Aldor. Mor'ghor wird einen Siegesbeweis sehen wollen, wenn all das hier vorüber ist. Er wird sie als Beute von den gefallenen Soldaten der Aldor wiedererkennen.\n\nJetzt gilt es noch das Leuchtsignal abzufeuern, um die Räuber des Drachenmals herbeizurufen. Sobald Ihr bereit seid, werden wir sie niederschmettern. Gebt mir einfach den Befehl.", sourceObjective = "Helft Kommandant Arcus und den Aldor bei der Verteidigung des Altars der Sha'tar. Sobald alle Streitkräfte des Drachenmals bezwungen wurden, kehrt zu Oberanführer Mor'ghor beim Basislager des Drachenmals mit den Medaillen der Aldor zurück.", progress = "Habt Ihr sie mit Euren Fäusten zerschmettert, Kommandant?", completion = "<Mor'ghor lacht.>\n\nHAHA! Ich habe gewusst, dass ich auf Euch zählen kann, Kommandant! Ich möchte, dass Ihr den Altar der Sha'tar mindestens einmal pro Tag überfallt. Sie werden keine andere Wahl haben und das Schattenmondtal verlassen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11102] = { id = 11102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomberangriff", description = "Ihr könnt also wie eine Krähe herumfliegen... ja und! Schon mal etwas am Boden ausradiert, während Ihr geflogen seid? Lust, es mal zu probieren?\n\nDas Konstruktionslager: Wut und das Konstruktionslager: Terror, im Norden und im Süden, sind mir schon seit langem ein Dorn im Auge und eine Gefahr für Ogri'la. Mit all diesen Teufelskanonen, die die Himmelswache von rechts und links unter Beschuss nimmt, gibt es einfach kein Hindurchkommen und unser Unterfangen ist zum Scheitern verurteilt.\n\nWürdet Ihr Euch gerne unter Beweis stellen? Nehmt diese Bomben und vernichtet ihre Munitionsvorräte. Lasst Euch aber nicht auch noch vom Himmel herunterholen!", sourceObjective = "Vernichtet mithilfe der Bomben der Himmelswache 15 Stapel mit Teufelskanonenkugeln.", progress = "Habt Ihr schon ihre Stapel mit Teufelskanonenkugeln vernichtet?", completion = "Gut, gut, scheinbar seid Ihr doch härter im Nehmen als ich dachte. Ausgezeichnete Arbeit. Möglicherweise hatte der alte Keller doch Unrecht, was Euch anbelangt.\n\n<Himmelsoffizier Vanderlip grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11103] = { id = 11103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Weise" }
quests[11104] = { id = 11104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Bewahrer" }
quests[11105] = { id = 11105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Held" }
quests[11106] = { id = 11106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mehr Verteidiger", progress = "Man kann die Kräfte Eures Ringes neu formen, doch wird es nicht einfach, Eure Auswahl rückgängig zu machen. Seid Ihr sicher, dass Ihr seine momentane Form durch eine andere ersetzen möchtet?", completion = "Es ist ein Leichtes, die Sande der Zeit vorwärts fließen zu lassen. Man kann den Fluss auch umkehren, doch ist dies mit großen Mühen verbunden." }
quests[11107] = { id = 11107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verneigt Euch vor dem Hochlord", description = "Ich bin der Überbringung einer an Euch gerichteten Nachricht nicht einmal würdig, Sire. Bitte verzeiht dieses ungebührliche Benehmen. Oberanführer Mor'ghor möchte, dass Ihr Euch umgehend bei ihm meldet!", sourceObjective = "Sprecht mit Oberanführer Mor'ghor beim Basislager des Drachenmals im Schattenmondtal.", completion = "Ihr seid der erste Hochlord des Drachenmals, {name}. Der Meister hat beschlossen höchstpersönlich hierher zu kommen, um Euch zu befördern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11108] = { id = 11108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürst Illidan Sturmgrimm", description = "Kommt, Hochlord {name}. Illidan höchstpersönlich erwartet Euch!", sourceObjective = "Trefft Euch mit Illidan Sturmgrimm. Solltet Ihr überleben, sucht Barthamus im Unteren Viertel von Shattrath auf.", completion = "Ich war der Erste, wisst Ihr. Das verlassene Kind eines Monsters...\n\n<Barthamus schüttelt seinen Kopf.>\n\nWir haben Euch alles zu verdanken, {name}. Ganz allein habt Ihr das Reich des Drachenmals zerschmettert und dabei genug Informationen gesammelt, die meine Brüder mehr als ein Leben lang beschäftigen werden.\n\nEs ist zwar nicht viel, aber es gibt da etwas, das wir Euch anbieten können... Ein jeder meines Schwarms hat sich dazu bereit erklärt, Euch bei Euren Abenteuern in der Scherbenwelt zu begleiten. Fragt sie einfach und sie werden mit Euch einen Bund eingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11109] = { id = 11109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorus, der kobaltblaue Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11110] = { id = 11110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfas, der lila Drache der Netherschwingen" }
quests[11111] = { id = 11111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyxien, der onyxfarbene Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11112] = { id = 11112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suraku, der azurblaue Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11113] = { id = 11113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voranaku, der violette Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11114] = { id = 11114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zoya, der viridiangrüne Drache der Netherschwingen", sourceObjective = "Es ist eine Ehre, Euch zu treffen, {name}. Wir alle haben Eure Abenteuer mit großer Aufmerksamkeit verfolgt. Wir sind äußerst dankbar für alles, was Ihr für den Drachenschwarm der Netherschwingen getan habt.\n\nWenn Ihr mich zu Eurem Weggefährten macht, werde ich Euch bis ans Ende dieser Welt und wieder zurück fliegen. Was auch immer Ihr von mir verlangt, ich werde mein Bestes tun, um Euren Wunsch zu befolgen.\n\nIhr sollt jedoch wissen, dass Ihr nur einen von uns für Eure Reisen in der Scherbenwelt erwählen könnt. Habt Ihr Euch einmal entschieden, so könnt Ihr Eure Meinung nicht mehr ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11115] = { id = 11115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal von Vashj" }
quests[11116] = { id = 11116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: (QUEST FLAG)", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr für den Schlüssel der Stürme als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!\n\nWenn Ihr dies erledigt habt, werdet Ihr den Schlüssel der Stürme bekommen.", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11117] = { id = 11117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangt die wilden Wolpertinger!", description = "Da, jetzt. Habt Ihr's gehört? Diese Geräusche in den Hügeln. Das sin' die Wolpertinger! Gerissene Biester sin' das, angelockt vom Duft des Braufests. Ich würd' mir ja gern' ein paar davon fangen, aber ich hab' mir mein Bein aufgeschlagen und kann diese Viecher einfach nich' einholen. Tja, da könnt Ihr mir helfen!\n\nNehmt dieses Netz und werft's über diese kleinen Teufel. Bringt mir fünf der Biester und ich werd' Euch für Eure Mühe belohnen! Oh, eine Sache noch - um die Viecher überhaupt sehen zu können, müsst Ihr entweder gut was intus haben oder Ihr fragt mich einfach nach 'ner Syntheholbrille!", sourceObjective = "Goldark Spatzenjäger möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr entweder ordentlich betrunken sein oder eine Syntheholbrille tragen müsst, um die Biester sehen zu können.", progress = "Na, wart Ihr benebelt genug, um die Viecher zu sehen?", completion = "Na sieh einer an! Da habt Ihr ja 'nen ganzen Packen Wolpertinger gefangen!\n\n<Er nimmt einen herzhaften Schluck aus seinem Maßkrug.>\n\nIch sach' Euch was. Da Ihr so'n fantasch... fantastischer Jäger seid, dürft Ihr eins der Viecher für Euch selbst behalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[11118] = { id = 11118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parade der rosa Elekk", description = "Sich zu betrinken ist eine altehrwürdige Tradition auf dem Braufest - es ist schon fast eine Bedingung! Die Sache ist die. Mir wurde berichtet, dass die Feierlichkeiten in ganz Azeroth von Halluzinationen überschattet werden! Das können wir nicht zulassen!\n\nNormale Waffen können diesen Elekk nichts anhaben - sie gehen einfach durch sie hindurch. Nehmt daher dieses fantastische Stück gnomischer Maschinenbaukunst, reist zu den anderen Biergärten und zappt sie ins Nichts. Vergesst nicht, Ihr müsst entweder betrunken sein oder eine Syntheholbrille tragen, um sie sehen zu können! Sagt es mir einfach, wenn Ihr eine Brille braucht.", sourceObjective = "Reist zu den Biergärten außerhalb von Sturmwind, Darnassus und der Exodar, zappt an jedem Ort drei Elekk und kehrt anschließend zu Goldark Spatzenjäger zurück. Um die rosa Elekk sehen zu können, müsst Ihr betrunken sein oder eine Syntheholbrille tragen.", progress = "Sind die verdammten rosa Elekk nun endlich verschwunden?", completion = "Gute Arbeit! Rosa Elekks... welch unsinnige Vorstellung!", sourceObjectiveStatus = "unverified-source-field" }
quests[11119] = { id = 11119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Landeplatz von Bash'ir!", description = "Hey, <Junge/Mädel>! Auf der Suche nach etwas Spaß?\n\nAlle paar Stunden starten meine Äthertechniker einen Angriff auf den Landeplatz von Bash'ir tief im Nordosten des Schergrats. Sie bestehen darauf, dass sie Bash'irs Kristallschmiede nur 'erforschen', aber egal wie man es dreht, es ist eigentlich nichts anderes, als ein Überfall. Wir benutzen die Kristallschmiede, um uns mit neuer Ausrüstung zu versorgen und meistens bleibt noch genug übrig, um einen guten Gewinn herauszuschlagen.\n\nGeht 'runter zur Landebahn und sprecht mit dem Äthertechnikerlehrling. Er wird Euch sagen können, wann der nächste Einsatz stattfindet.", sourceObjective = "Sprecht mit dem Äthertechnikerlehrling im Außenposten der Himmelswache im Schergrat.", completion = "Egal, was Keller dazu meint, ich bevorzuge es, unsere Einsätze als Forschungsexkursionen zu betrachten.\n\nEs stimmt allerdings, dass wir dort Vorräte für die Himmelswache beschaffen, jedenfalls, wenn wir lange genug dort bleiben können.\n\nIhr seht so aus, als wäret Ihr bereit, uns den Rücken gegen die Astralen freizuhalten. Wenn Ihr uns die Astralen lange genug vom Leib haltet, werden wir Euch alle zusätzlich an der Kristallschmiede hergestellten Gegenstände zum Verkauf anbieten, also bringt Eure Apexissplitter und Kristalle mit!\n\nWir ziehen in 0 |4Minute:Minuten; los.", sourceObjectiveStatus = "unverified-source-field" }
quests[11120] = { id = 11120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parade der rosa Elekk", description = "Schaut doch, wir verdienen hier unser Geld. Betrunkene Leute? Das ist ein ziemlich gutes Geschäft. Es gibt da allerdings eine Sache, die einem die Umsätze völlig vermiest - Halluzinationen. Ich sag's Euch, meine Jungs berichten mir, dass die Saufbo-, äh, ehrenwerten Kunden überall rosa Elekk sehen.\n\nIch kann keine beunruhigten Kunden gebrauchen. Hier, nehmt das, reist zu den anderen Biergärten und kümmert Euch für mich um die Angelegenheit, ja? Achtet darauf, dass Ihr betrunken seid oder eine Syntheholbrille tragt! Sagt es mir einfach, wenn Ihr eine Brille braucht.", sourceObjective = "Reist zu den Biergärten außerhalb von Silbermond, Donnerfels und Unterstadt, zappt an jedem Ort drei Elekk und kehrt anschließend zu Glodrak Jägerspatz zurück. Um die rosa Elekk sehen zu können, müsst Ihr betrunken sein oder eine Syntheholbrille tragen.", progress = "Ihr räumt das kleine Problem, von dem ich Euch erzählt habe, doch aus dem Weg, oder?", completion = "Das habt Ihr gut gemacht, Kindchen. Hier, nehmt dies als Lohn für Eure Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11122] = { id = 11122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin und zurück", description = "Ihr wollt also beim Braufest aushelfen? Ich habe die perfekte Aufgabe für Euch. Ich werde Euch auf einen meiner Rennwidder setzen und nach Kharanos reiten lassen. Es gibt da ein paar Fässchen, die ich abholen muss. \n\nFlynn Feuerbräu wartet auf einem Hügel neben einem Stapel mit Fässchen. Sobald Ihr nahe genug seid, wird er Euch ein Fässchen zuwerfen. Dann eilt Ihr wieder hierher zurück und werft es Pol Bernruh zu. Ihr könnt immer nur ein Fässchen gleichzeitig tragen. \n\nSeid Ihr bereit?", sourceObjective = "Holt ein Fässchen von Flynn Feuerbräu in Kharanos und bringt es zu Pol Bernruh zurück. Macht das Ganze dreimal, bevor Euer Widder verschwindet.", completion = "Vielen Dank für Eure Hilfe! Solange das Braufest noch im Gange ist und die Dunkeleisenzwerge immer wieder angreifen, brauche ich Hilfe bei der Auslieferung der Fässchen. Wenn Ihr Euch noch mehr Marken verdienen wollt, dann kommt jeden Tag wieder zu mir.\n\nSo, jetzt muss ich Euch erst einmal für Eure Arbeit bezahlen. Hier sind Eure Biermarken, viel Spaß auf dem Braufest!", sourceObjectiveStatus = "unverified-source-field" }
quests[11123] = { id = 11123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Der arme James, er ist nie ganz über die Zerstörung des Gasthauses \"Zur Süßen Ruh\" und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Monster, die dafür verantwortlich sind, zu finden.\n\nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertig werden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.\n\nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig, auf Eurer Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.", sourceObjective = "Sprecht mit Inspektor Tarem beim Gasthaus \"Zur Süßen Ruh\".", completion = "Es freut mich, dass Hauptmann Mumm endlich auch andere mit dieser Untersuchung beauftragt.\n\nIch habe diesen Bereich mit reflektierendem Puder abgestaubt. Verdächtige Gegenstände und Hinweise werden dadurch sichtbar. Ihr könnt Euch also wesentlich leichter auf Eure Bemühungen konzentrieren. Seht Euch alles an, was der Staub zum Leuchten gebracht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11124] = { id = 11124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses \"Zur Süßen Ruh\" stoßen.\n\nTheramore hat einen Ermittlungsbeamten entsendet, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Ich habe einen meiner Männer als Spion dorthin abkommandiert und ich möchte mich bei dieser Untersuchung nicht auf die Kompetenz dieser Menschen verlassen.\n\nEgal was Ihr findet, gebt nicht einmal einen kleinen Fetzen davon an den Ermittlungsbeamten weiter. Wir kümmern uns selbst darum.", sourceObjective = "Untersucht das Gasthaus \"Zur Süßen Ruh\" an der Grenze zwischen dem Brachland und den Düstermarschen.", completion = "<Der Inspektor betrachtet Euch mit Misstrauen.>\n\nMan hat mir gesagt, dass Ihr mir bei dieser Untersuchung... helfen werdet. Nun gut.\n\nIch habe dieses Puder verwendet, um die Ruinen nach Hinweisen abzusuchen, die uns beim Identifizieren der Täter behilflich sein könnten. Der Staub bringt alles zum Leuchten, was bei dem Überfall eine Rolle gespielt hat. Nur zu, untersucht alles, was verdächtig erscheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[11126] = { id = 11126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter unter uns", description = "Schön, Euch zu sehen, {class}. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.\n\nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.\n\nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.", sourceObjective = "Konfrontiert 5 Aufwiegler der Deserteure und kehrt zu Calia Hastings nahe der Docks in Theramore zurück.", completion = "Gut gemacht, {name}. Ich glaube, wir haben sie überrascht. Ihre Agenten wähnten sich innerhalb der Stadt vermutlich in Sicherheit.\n\nMit der Zeit werden die Aufwiegler zurückkehren und ihre Lügen wieder verbreiten. Wir werden die Zeit, die Ihr uns verschafft habt, nutzen, um die Deserteure weiter auszusperren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11128] = { id = 11128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propagandakrieg", description = "Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure scheinbar auf einem Schiff zu den Docks geschmuggelt haben.\n\nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kajüte des Kapitäns.", sourceObjective = "Bringt das Propagandamaterial der Deserteure zu Calia Hastings nahe der Docks in Theramore.", progress = "Konntet Ihr die Propagandahandzettel finden und in Beschlag nehmen?", completion = "<Die SI:7-Agentin nickt zustimmend.>\n\nAusgezeichnet. Jetzt müssen wir die Deserteure nur noch diskreditieren, damit sie in Theramore nie wieder Fuß fassen können. Ich weiß auch schon wie.", sourceObjectiveStatus = "unverified-source-field" }
quests[11129] = { id = 11129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyle wird vermisst!", description = "Helft mir, {name}! Mein geliebter Hund Kyle ist mir weggelaufen. Ich weiß nur, dass er irgendwo in der Nähe des Dorfes der Bluthufe einsam und hungrig herumstreunt.\n\nWürdet Ihr ihn für mich finden und füttern? Wenn er erst einmal etwas gefressen hat, wird er sich wieder beruhigen und nach Hause zurückkehren.\n\nUm ihn zu füttern, müsst Ihr etwas zu Essen finden. Schreiterfleisch mag er besonders gerne. Geht einfach Richtung Osten, dort solltet Ihr genügend Schreiter finden. Erlegt einen und bringt sein saftiges Fleisch zu Kyle. Wenn Ihr Kyle im Dorf antrefft, müsst Ihr das Fleisch nur auf den Boden legen und er wird zu Euch kommen.", sourceObjective = "Ahab Weizhuf beim Dorf der Bluthufe in Mulgore möchte, dass Ihr seinen geliebten Hund Kyle den Wilden füttert.\n\nFüttert Kyle mit zartem Schreiterfleisch und kehrt anschließend zu Ahab Weizhuf zurück.", completion = "Gut gemacht, {name}! Nachdem er gefressen hatte, kam Kyle sofort nach Hause und hat sich schlafen gelegt. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[11130] = { id = 11130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es glitzert!", description = "Nur keine Scheu, <Mann/Süße>! Lasst den alten Gaunah mal einen Blick auf Eure Klunker werfen...\n\nHmm. Ja, nicht schlecht, aber das Zeug könnte besser sein. Viel, viel besser.\n\n<Gaunah kommt näher und flüstert.>\n\nSchätze von unschätzbarem Wert lassen sich überall finden, {name}, man muss nur wissen wo! Heute ist Euer Glückstag! Ich kenne da einen Typen, der Euch zu mehr Reichtümern verhelfen kann, als Ihr jemals tragen könntet.\n\nStattet meinem alten Kumpel Budd in der Nähe von Zul'Aman einen Besuch ab und zeigt ihm das hier. Sagt ihm, dass der alte Gaunah Euch geschickt hat, dann wird er Euch bei seinem neuen Projekt mit einsteigen lassen.", sourceObjective = "Gaunah möchte, dass Ihr Gaunahs Notiz zu Budd in den Geisterlanden, direkt außerhalb von Zul'Aman, bringt.", progress = "<Budd beäugt die Notiz misstrauisch.>\n\nWas habt Ihr da, {class}?", completion = "<Budd liest die Notiz.>\n\nAhh! Ein Freund von Gaunah? Willkommen!\n\nIhr kommt genau richtig, mein Freund. Wie es das Schicksal so will, habe ich gerade erst meine Kollegen verloren. Tragisch, wirklich, aber außergewöhnliche Belohnungen haben oft ihren Preis. Lasst uns nicht zu sehr ans Negative denken!\n\nIhr habt sicherlich schon von meinen zahlreichen Ausbeuten und Entdeckungen gehört. Nun, das war alles nichts im Vergleich zu dem hier! Ich sage es Euch, wir sind nahe dran, hier in Zul'Aman Geschichte zu schreiben. Ihr hattet das Glück, rechtzeitig zu kommen, um auf der untersten Ebene dabei zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[11131] = { id = 11131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht das Feuer!", description = "Ihr müsst uns helfen! Der kopflose Reiter greift das Dorf an. Überall brennen Feuer! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, {name}, schließt Euch der Brandwache an. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund, der näher bei den Flammen steht, weiterreichen. Wenn Ihr alle Feuer löscht, könnt Ihr uns vielleicht noch retten!", sourceObjective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", progress = "{name}, Ihr hattet geschworen, die Kinder zu retten!", completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[11132] = { id = 11132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versprechen, Versprechen...", description = "Meine Theorien bestätigen die Gerüchte, dass in Zul'Aman sagenhafte Schätze zu finden sind. Das bedeutet Reittiere und Anwesen für alle!\n\nNun ja, eins nach dem anderen. Ihr müsst Euch Euren Anteil natürlich verdienen...\n\nUnsere anfänglichen Bemühungen haben uns hier doch nicht so weit gebracht, wie ich es mir erhofft hatte. Tatsächlich sieht es so aus, dass meine Karte, und die Tagelöhner, denen ich sie geliehen habe, verschwunden sind. Sie sind aufgebrochen, um einen Troll namens Nalorakk zu jagen. Ich kann zwar die Gruppe ersetzen, aber ich brauche diese Karte!\n\nSolltet Ihr diese Aufgabe bewältigen, dann wird man von Euch sagen, dass Ihr derjenige wart, der Budd Winterhäldler geholfen hat, die Geheimnisse von Zul'Aman zu lüften!", sourceObjective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr bei Hohepriester Nalorakks Terrasse in Zul'Aman nach seiner Karte sucht.", progress = "Ah, wenn das nicht {name} ist!\n\nHabt Ihr meine Karte ausfindig gemacht?", completion = "<Budd scheint etwas geschockt zu sein.>\n\nOh? Ihr habt sie gefunden?\n\nÄhm, ich meine, natürlich habt Ihr das! Gut gemacht, {class}.\n\nLasst mal sehen, ob ich etwas Kleines für Euch habe... ahh, ja, das könnte passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11133] = { id = 11133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskreditierung der Deserteure", description = "Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.\n\nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals wieder Fuß zu fassen.\n\n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>\n\nFangt doch schon einmal an, während ich den nächsten Schritt plane.", sourceObjective = "Calia Hastings möchte, dass Ihr verfälschte Handzettel an 6 Wachen von Theramore verteilt. Erstattet ihr anschließend Bericht nahe der Docks in Theramore.", progress = "Ich dachte, ich hätte Gelächter bei den Kasernen gehört. Habt Ihr die Handzettel verteilt, die ich Euch gegeben habe?", completion = "<Calia kichert, als Ihr von der Reaktion der Wachen auf das Propagandamaterial berichtet.>\n\nGenau wie ich gehofft hatte! Ich bin mir sicher, dass jeder Agent der Deserteure, der versucht Theramore zu infiltrieren, sofort ausgelacht wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[11134] = { id = 11134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Deserteure", description = "Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.\n\nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.", sourceObjective = "Nehmt Gavis Grauschild gefangen und erstattet anschließend Bericht bei Calia Hastings nahe der Docks in Theramore.", completion = "Gavis' Forderung ist nicht so haarsträubend wie sie scheint. Wenn man sie richtig behandelt, gelingt es Lady Jaina vielleicht sogar die Deserteure wieder in unsere Gemeinschaft zu integrieren. Doch diese Entscheidung obliegt alleine ihr.\n\nEs war mir eine große Freude mit Euch zu arbeiten, {name}! Ohne Eure Hilfe wäre die gesamte Operation sicherlich nicht halb so glatt gelaufen. Ich werde Euch in meinem Bericht an Sturmwind lobend erwähnen, so dass alle wissen, dass es Euer Einsatz war, der der Bedrohnung durch die Deserteure ein Ende gesetzt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11135] = { id = 11135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kopflose Reiter", description = "Der kopflose Reiter wurde zwar vertrieben, aber solange die Schlotternächte noch andauern, wird er wiederkehren. {name}, befreit uns von diesem Leid und dem wahnsinnigen Treiben des Kopflosen. Stellt Euch dem Reiter, wenn er und sein Kopf vereint sind, und vernichtet ihn!\n\nEr haust tief im Unglückseligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Findet seinen Kürbisschrein und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nGeht, {name}. Möge das Licht Euch immer beistehen.", sourceObjective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", completion = "Der Ursprung dieses Schreins ist unbekannt, aber es besteht kein Zweifel, wem hier gehuldigt wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[11136] = { id = 11136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Berichte", description = "Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.\n\nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.", sourceObjective = "Erstattet Hauptmann Wymor bei der Späherwacht Bericht.", completion = "<Der Hauptmann versucht ganz offensichtlich Eure Fähigkeiten einzuschätzen.>\n\nIhr habt also von dem Schiffswrack an der Küste gehört? Gut, ich könnte noch etwas Hilfe gebrauchen, um meinen Verdacht gegenüber den Überlebenden zu bestätigen. Willkommen an Bord, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11137] = { id = 11137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in den Düstermarschen?", description = "Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden auch alle rote Kopftücher!\n\nDie Defias sind Handwerker und Zunftgenossen, keine Seefahrer. Was haben sie bei einem Schiffswrack auf einem Kontinent, der sie nicht interessiert, zu suchen?\n\nMan sagt, ihr Anführer residiert auf einer großen Insel, die nicht weit von der Küste entfernt, nordöstlich des Turms liegt. Tötet ihn und nehmt alle Dokumente an Euch, die Ihr in seinem Besitz findet.", sourceObjective = "Besorgt Euch die Befehle der Defias von Garn Mathers und bringt sie zu Hauptmann Wymor bei der Späherwacht.", progress = "Konntet Ihr ihren Anführer finden?", completion = "<Hauptmann Wymor nimmt die Befehle von Euch entgegen und liest sie.>\n\nWas in aller Welt könnte mit 'Kostbare Fracht' gemeint sein? Die Defias haben zwar kleinere Schmuggeleien im Land von Sturmwind betrieben, aber dies hier ist ganz offensichtlich eine Nummer zu groß für sie. Die Sprache in diesen Befehlen lässt auf einen wohlhabenden oder adligen Herren schließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11138] = { id = 11138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.\n\nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.\n\nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.", sourceObjective = "Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe der Schreckensmoorküste.", progress = "Seid gegrüßt, {class}. Was führt Euch hierher?", completion = "<Renn sieht sich die Befehle an.>\n\nEs war also eine kostbare Fracht an Bord! Wir müssen sie finden, bevor sie von den Defias geborgen wird. Diese Kerle sind zwar keine Taucher, aber wir werden Teile ihrer Ausrüstungen benötigen, wenn Ihr mir bei der Bergung der Fracht behilflich sein wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11139] = { id = 11139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauchausrüstung aus zweiter Hand", description = "Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mithilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese \"Leihgabe\" kommt.\n\nSucht diese Insel nach einer Kiste mit einer Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!", sourceObjective = "Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in den Düstermarschen.", progress = "Mal sehen, was Ihr Euch von den Defias \"borgen\" konntet.", completion = "Na super, die Ausrüstung ist in einem weitaus schlimmeren Zustand, als ich befürchtet hatte... und das Werkzeug!\n\nNun gut, ich habe Euch versprochen, das Ganze wieder funktionstüchtig zu machen, also fange ich mal besser mit der Arbeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[11140] = { id = 11140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Nun, ich konnte die Ausrüstung so reparieren, dass Ihr eine Weile damit tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.\n\nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Tauchhelm funktioniert, solltet Ihr versuchen, Teile des Wracks auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Diese Hydras sind gefährlich.", sourceObjective = "Bringt 6 geborgene Geldkassetten zu Renn McGill in den Düstermarschen.", progress = "Konntet Ihr bei Eurer Suche nach Wrackteilen etwas über die Fracht der Defias herausfinden?", completion = "<Renn durchstöbert den Inhalt der Geldkassetten, die Ihr geborgen habt.>\n\nGute Arbeit. Mal sehen, ob wir Eure 'Kostbare Fracht' hier drin finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[11141] = { id = 11141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina muss davon erfahren", description = "Ihr müsst Lady Jaina sofort von Eurem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann stellt sich die Frage, wer es war und ob diese Person noch am Leben ist!\n\nEines ist jedoch sicher, {name}. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", completion = "Ihr und Renn habt ausgezeichnete Arbeit geleistet. Danke, dass Ihr diese Informationen ans Licht und sofort zu mir gebracht habt. Es bestehen keine Zweifel, die Defias haben einen finsteren Plan ausgeheckt und wollen gegen Sturmwind und seine Verbündeten vorgehen. Der Aufwand dieses Unterfangens übersteigt alle bisherigen Operationen der Defias. Sie müssen irgendwo einen wohlhabenden Gönner haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11142] = { id = 11142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtet die Insel Alcaz", description = "Offenbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Um dort hinein zu kommen, bräuchten wir allerdings eine ganze Brigade von Soldaten.\n\nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.\n\nDie Insel birgt den Schlüssel zum Geheimnis darüber, in wie fern die Defias in dieser Entführung verwickelt sind.", sourceObjective = "Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten. Sprecht mit Lady Jaina Prachtmeer in Theramore, wenn Ihr die Beobachtung abgeschlossen habt.", completion = "<Lady Jaina hört sich Euren Bericht über die Beobachtung aufmerksam an.>\n\nEin Runenkreis, Drachkin? Die Defias haben mit Sicherheit unabhängige Magier in ihren Reihen, aber niemanden, der mächtig genug wäre, um von derartigen Dingen Gebrauch zu machen!\n\nWarum sollten schwarze Drachkin Interesse an einer Insel voller Naga haben? Es gibt viele unbeantwortete Fragen, aber eines ist sicher: die Defias haben einen mächtigen Verbündeten aus den oberen Rängen der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[11143] = { id = 11143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entscheidende Grimmweis", description = "Ich habe mich mit Inspektor Tarem über die Beweise, die Ihr bei den Ruinen des Gasthauses \"Zur Süßen Ruh\" gefunden habt, unterhalten. Er ist sich sicher, dass die Hufabdrücke und der Schild auf den Taurenklan der Grimmtotem hindeuten.\n\nBedenkt man die jüngsten Berichte über die zunehmenden Aktivitäten der Grimmtotem in den Marschen, so handelt es sich sicherlich nicht um einen Zufall. Bitte geht und sprecht mit Hauptmann Darill, er ist so eine Art Experte in Sachen Grimmtotem. Folgt der Straße aus dem Dorf Richtung Norden zur Nordwacht. Es ist der zweite Außenposten entlang der Straße.", sourceObjective = "Erstattet Hauptmann Darill bei der Nordwacht Bericht.", completion = "Hauptmann Mumm vermutet, dass die Grimmtotem hinter der Zerstörung des Gasthauses Zur süßen Ruh stecken? Sie würden zwar auf meiner Liste der Verdächtigen nicht ganz oben stehen, aber wenn Hauptmann Mumm Euch hierher geschickt hat, um dieser Spur nachzugehen, dann wird er schon seine Gründe haben. Wie dem auch sei, die Grimmtotem sind uns schon seit einer ganzen Weile ein Dorn im Auge und wir freuen uns über jede Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11144] = { id = 11144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestätigung des Verdachts", description = "Die Grimmtotem sind vielleicht der kriegerischste Klan der Tauren, aber sie sind keineswegs unorganisiert. Sollten sie das Gasthaus \"Zur Süßen Ruh\" wirklich in Brand gesteckt haben, dann nur auf Befehl von einem der Klanältesten.\n\nIm Nordwesten liegt eine große Siedlung der Grimmtotem, das Dorf der Schwarzhufe. Sie haben sie als Ausgangsbasis für ihre Angriffe auf den Turm genutzt, ich bin mir jedoch ganz sicher, dass Ihr dort auch die Befehle finden werdet. Sucht bei den Ältesten im Dorf nach dem Verbleib der Pläne.", sourceObjective = "Bringt die Schlachtpläne der Grimmtotem zu Hauptmann Darill bei der Nordwacht.", progress = "Konntet Ihr die Pläne aufspüren?", completion = "<Hauptmann Darill wirft einen Blick auf die Schlachtpläne.>\n\nIch würde sagen, das ist eindeutig genug. Sie haben sich dazu entschlossen, die Siedlungen der Menschen hier in dieser Gegend zu bekämpfen. Ich bin überzeugt, dass Theramore ihr nächstes Ziel ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11145] = { id = 11145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Grimmtotem", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, {class}, aber bringt mir meine Männer lebend zurück.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 5 Gefangene von Theramore befreit.", completion = "Die befreiten Gefangenen kehren bereits aus dem Dorf der Schwarzhufe zurück. Die Informationen, die sie dem Hauptmann geben können, werden uns im nächsten Kampf gegen die Grimmtotem einen Vorteil verschaffen.\n\nIhr habt meinen Dank und den meiner Männer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11146] = { id = 11146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenfänger", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. Ich an Eurer Stelle würde sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr 6 Raptoren einfangt. Ihr könnt entweder Blutsumpfraptoren oder Blutsumpfkreischer einfangen.", progress = "Habt Ihr diese Raptoren schon eingefangen?", completion = "Scheint, als hättet Ihr ein paar Kratzer abbekommen! Auf jeden Fall seid Ihr in einer wesentlich besseren Verfassung als es die Grimmtotem sein werden, nachdem wir unsere neuen Raptorenfreunde auf sie losgelassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11147] = { id = 11147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Raptoren los", description = "Jetzt, da wir unsere Raptoren haben, besteht unser nächster Schritt darin, sie für einen Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem... nun, eigentlich ist es ja auch völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren werden sich um den Rest kümmern.", sourceObjective = "Unteroffizier Lukas bei der Nordwacht möchte, dass Ihr den Raptorenköder bei der Windmühle im Dorf der Schwarzhufe platziert.", completion = "<Der Unteroffzier versucht erst gar nicht sein Grinsen zu unterdrücken.>\n\nGut, damit werden sie wohl den einen oder anderen Überfall aussetzen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11148] = { id = 11148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Grimmtotem", description = "Wenn die Ausrüstung, die Ihr bei den Ruinen des Gasthauses gefunden habt, zu einem Angriffstrupp der Grimmtotem gehörte, dann gibt es vermutlich noch mehr davon in ihrem Lager im Nordwesten.\n\nBis jetzt konnten wir noch nicht viel über das Dorf der Schwarzhufe in Erfahrung bringen. Ausgehend von der Größe ihrer Angriffstrupps, schätzen wir jedoch, dass sich dort eine größere Streitmacht aufhält.\n\nTut, was auch immer Ihr tun müsst, um einige ihrer Ausrüstungsgegenstände zu erbeuten, damit wir sie mit Eurem Fund beim Gasthaus vergleichen können.", sourceObjective = "Hauptmann Darill bei der Nordwacht möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", progress = "Habt Ihr die Waffen im Dorf der Schwarzhufe erbeuten können?", completion = "<Hauptmann Darill inspiziert die Waffen, die Ihr ihm aus dem Dorf der Schwarzhufe gebracht habt.>\n\nEs gibt keinen Zweifel, sie entsprechen genau der Beschreibung. Allerdings gibt es da ein Problem - diese Waffen wurden nie im Kampf eingesetzt. Das Dorf der Schwarzhufe scheint nicht der einzige Posten der Grimmtotem in den Marschen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11149] = { id = 11149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Unterstützung", description = "Ich kann keine Männer mehr entbehren, um Euch bei der Suche nach einem zweiten Außenposten der Grimmtotem zu helfen. Ich wüsste aber jemanden, der Euch behilflich sein könnte.\n\nTief im Morast, im Süden, liegt ein kleines Gehöft, das Tabetha gehört. Sie mag zwar wie eine alte Einsiedlerin erscheinen, aber in Wirklichkeit ist sie eine Magierin und angesehene Wahrsagerin. Folgt der Straße Richtung Süden bis zu ihrem Hof und bittet sie, Euch bei der Suche nach den Tätern, die für das Massaker beim Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, zu helfen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof.", completion = "Ihr wollt also, dass ich die Grimmtotem ausfindig mache, ja? Was würdet Ihr sagen, wenn ich der Meinung bin, dass das nicht nötig ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[11150] = { id = 11150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", sourceObjective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Ich hoffe, dass die Grimmtotem die Botschaft verstanden haben. Jeglicher Versuch, hier wieder aufzukreuzen, wird mit weit mehr als nur einer Fackel bestraft. Dafür werden meine Schüler und ich sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11151] = { id = 11151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit im Namen der Familie Hyal", description = "Die Grimmtotem waren zwar lediglich eine Plage für mich, aber dennoch sollte Hauptmann Mumm von Euren Taten erfahren. Berichtet ihm, dass Ihr diejenigen, die für den Anschlag auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, gefunden und bestraft habt.\n\nEs ist zwar zu spät, um Jim Hyals Familie zu retten, aber vielleicht denken die Grimmtotem demnächst zweimal nach, bevor sie jemanden aus Theramore angreifen.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm bei der Wehrzitadelle in Theramore.", completion = "<Der Hauptmann hört sich Euren Bericht aufmerksam an.>\n\nWir haben James und seine Familie gerächt, aber selbst das kann den angerichteten Schaden nicht ersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11152] = { id = 11152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich Frieden", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder der Gerechtigkeit überantwortet wurden.\n\n<Hauptmann Mumm fertigt einen kleinen Blumenkranz an.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Steine auf dem Friedhof genau nördlich der Tore von Theramore.", sourceObjective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", completion = "<Hauptmann Mumm lächelt, als ihr ihm von den Ereignissen beim Grab der Familie Hyal berichtet.>\n\nEs ist gut zu wissen, dass sie es verstehen. Ihr habt ihnen doch nichts von James erzählt, oder?\n\nIch werde ihm die Nachricht von seiner Frau überbringen lassen, aber ich bezweifle, dass er es verstehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11153] = { id = 11153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbrecht die Blockade", description = "Alle unsere Schiffe sind gesunken! Wir benötigen Eure Hilfe, um die Piratenblockade in der Straße der Trümmer zu durchbrechen!\n\nNehmt diese Splitterbomben und lasst Euch vom Zeppelin mitnehmen, den Eggenmeiser uns 'ausgeliehen' hat. Er wird Euch über die Schiffe der Piraten, dieser Gauner, hinwegfliegen und Ihr werdet ihnen die Hölle heiß machen!\n\nWenn Ihr sie nicht in Stücke bomben könnt, dann werden wir die Blockade wohl nie durchbrechen können.", sourceObjective = "Nehmt Petrovs Splitterbomben und werft sie auf die Piraten. Beseitigt 25 Piraten der Blockade und 10 Kanonen der Blockade. Kehrt zu Bombenschütze Petrov in Westwacht zurück, sobald Ihr den Auftrag erfüllt habt.", progress = "Wir treffen uns also wieder? Das muss heißen, dass Ihr es geschafft habt! Ihr habt's diesen Fieslingen, diesen Piraten des Nordmeers gezeigt!\n\nStimmt's?", completion = "Das wollte ich hören! Ihr habt was drauf, {name}, so viel ist klar!\n\nDenkt Ihr, dass Ihr morgen wiederkommen könntet? Bis dahin haben wir neue Splitterbomben. Ich würde Euch ja wieder losschicken, aber mein Gehilfe Feknut ist noch nicht vom Guanosammeln zurück - Fledermausguano. Den brauchen wir für die Bomben.\n\nWieso braucht der eigentlich so lange?", sourceObjectiveStatus = "unverified-source-field" }
quests[11154] = { id = 11154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt ihnen eine Guanoangst ein!", description = "Ihr, ja Ihr... Ich brauche Eure Hilfe!\n\nPetrov hat mich hier hochgeschickt, damit ich Fledermausguano für die Splitterbomben, die er in Westwacht herstellt, sammle. Er hat mich in mein Verderben geschickt!\n\nDie Dunkelklauenfledermäuse hängen im nördlichen Bruchwald herum. Ich werde jedoch keinen Schritt von dieser Plattform machen, außer um nach Hause zu gehen!\n\nAber Ihr... Ihr könntet ihn für mich besorgen! Ja? Och büdde!!\n\nHier, nehmt diese Knallfrösche. Ich denke mir, dass wenn man sie unter den Fledermäusen losgehen lässt, sie sich so erschrecken werden, dass der Guano von alleine kommt!", sourceObjective = "Sammelt 10 Stück Dunkelklauenguano ein und bringt sie zu Ingenieur Feknut am Stählernen Tor.", progress = "Bitte sagt mir, dass Ihr den Dunkelklauenguano habt?!", completion = "Iiih, was stinkt denn da so? Puuh, Ihr seid das! Nun, ich hab' Euch eben eine stinkige Aufgabe gegeben!\n\nDanke schön, {class}. Seid unbesorgt, ich werde das Zeugs zu Petrov bringen, sobald wir von hier wegkommen.\n\n\n\nHabt ihr das gehört, Jungs? Machen wir, dass wir von hier verschwinden!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[11155] = { id = 11155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schon wieder Schaufelhauersuppe?", description = "Nachdem ein Großteil unseres Viehs verschwunden ist, sollten wir uns schnell mit neuen Vorräten eindecken - oder die Bestien in dieser Gegend werden unser kleinstes Problem sein!\n\nDa ich für die Versorgung dieser Meute verantwortlich bin, werde ich Euch nach Osten schicken, um mir etwas Fleisch zu besorgen. Genauer gesagt will ich uns ein wenig Schaufelhauerfleisch zubereiten.\n\nNehmt Euch jedoch vor den Hirschen in Acht... die sind gefährlich!", sourceObjective = "Küchenchefin Schwarzkessel hat Euch gebeten, ihr 6 Schaufelhauerfleisch zu beschaffen. Sie befindet sich in Westwacht.", progress = "Nichts geht über das zarte Fleisch, das man aus der Seite eines Schaufelhauers schneidet!", completion = "Damit werde ich eine feine Mahlzeit für die Jungs auftischen können.\n\n<Die Köchin lehnt sich etwas vor und flüstert Euch ins Ohr.>\n\nHier, mein Junge, nehmt Euch etwas hiervon. Ihr seht so aus, als könntet Ihr etwas mehr auf den Knochen vertragen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11156] = { id = 11156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuber des Grollhornpostens", description = "Die Grimmtotem beim Grollhornposten im Norden werden mit jedem Tag dreister. In der Nacht kann man sie oft von ihren Taten singen hören, wie sie diejenigen vertrieben haben, die sich hier niederlassen wollten.\n\nSie haben fest vor, uns von Tabethas Hof zu vertreiben, obwohl sie schon Generationen von Schülern hier ausgebildet hat. Wir haben den Hof so gut es geht verteidigt, aber Lehrling Garion wurde bei dem letzten Angriff verletzt.\n\nGeht zum Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Die Überfälle müssen ein Ende nehmen.", sourceObjective = "Tötet 12 Grimmtotem des Grollhornpostens und kehrt zu Lehrling Morlann auf Tabethas Hof zurück.", completion = "<Lehrling Morlann nickt.>\n\nGut. Wie sagt man so schön? Ich werde ihre Gesellschaft nicht missen. Inmitten des Sumpfs würde man sich normalerweise etwas Zurückgezogenheit wünschen, oder nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[11157] = { id = 11157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gelege des Bösen", description = "{name}, in dieser Sache vertraue ich nur Euch. Die Protowelpen und Eier der Protodrachen im südöstlich gelegenen brennenden Wald müssen beseitigt werden!\n\nSeitdem wir hier angekommen sind, steht die Glutstätte in Flammen. Da muss irgendeine abartige Magie am Werk sein - und seit Kurzem scheint sie zu wachsen. Meine Männer sagen mir, dass wenn wir nicht schon bald etwas unternehmen, wir in ein paar Wochen vom Feuer umgeben sein werden!\n\nBegebt Euch dorthin und beseitigt die Gefahr, indem Ihr die Protowelpen und die Eier zerstört.", sourceObjective = "Zerstört 15 Eier der Protodrachen und 15 Protowelpen. Kehrt danach zu Hauptmann Adams in Westwacht zurück.", completion = "Gute Arbeit! Mit ein bisschen Glück wird die Vernichtung ihres Geleges und ihrer Welpen die feurigen Bestien vertreiben und verhindern, dass sich das magische Feuer ausbreitet.\n\nWartet... Was ist das für ein Geräusch? Hört sich an, wie das Schlagen von Schwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11158] = { id = 11158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsumpffedern", description = "Überrascht Euch Broggs Anwesenheit, {race}? Keine Sorge! Die Goblins von Morastwinkel sind Broggs Freunde und Ihr könntet es auch werden.\n\nBrogg hat Brackenwall verlassen, nachdem der neue Oberanführer nicht Rache an den Drachkin geübt hatte, die für die Zerstörung unserer alten Heimat und den Tod vieler alter Freunde von Brogg verantwortlich sind. Brogg ist hierhergekommen, um die Geister seiner Freunde zur letzten Ruhe zu betten und für sie Rache zu üben, doch Brogg braucht Hilfe. Für das Ritual braucht Brogg Federn mit mächtiger Magie, Federn wie die der Raptoren aus dem Blutsumpfbau.", sourceObjective = "Bringt 5 Blutsumpffedern zu Brogg in Morastwinkel.", progress = "<Brogg sieht Euch hoffnungsvoll an.>\n\nHabt Ihr Federn für Brogg?", completion = "<Brogg nimmt die Federn entgegen.>\n\nBrogg ist zufrieden mit diesen Federn. Starke Magie. Brogg weiß nicht, wie die Raptoren sie mit Macht erfüllen, doch Raptorenfedern sind für Rituale immer am besten geeignet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11159] = { id = 11159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister der Festung der Steinbrecher", description = "Brogg hat das Totem fertig gestellt, mit dem Ihr den Geistern seiner Freunde Frieden geben könnt. Als die Drachkin über uns herfielen, töteten sie alle Steinbrecher, die nicht rechtzeitig fliehen konnten. Brogg entkam zusammen mit Oberanführer Mok'Morokk. Seitdem hoffte er auf einen gemeinsamen Gegenangriff aller überlebenden Steinbrecher.\n\nDoch der Gegenangriff fand nie statt und die Geister der Gefallenen verfolgen Brogg und die anderen noch immer. Nehmt das Totem und begebt Euch zu den Ruinen der Steinbrecher im Norden. Verwendet es in der Nähe von Ogerskeletten, um ihre Geister anzulocken. Besiegt die Geister und ermöglicht ihnen und ihren Knochen die letzte Ruhe.", sourceObjective = "Brogg in Morastwinkel möchte, dass Ihr 10 Geister der Steinbrecher tötet, um sie so ihrer letzten Ruhe zu überantworten.", progress = "Brogg muss wissen, ob Ihr den aufgebrachten Geistern der Steinbrecher Frieden geschenkt habt?", completion = "Brogg ist für Eure Hilfe sehr dankbar, auch wenn es Oberanführer Mok'Morokk wohl nie sein wird. Wenigstens können sich die verbliebenen Steinbrecher jetzt auf die Probleme der Lebenden konzentrieren und die Toten ruhen lassen. Jetzt gibt es für Brogg nur noch eine Sache zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11160] = { id = 11160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Banner der Steinbrecher", description = "Als die Drachen über Broggs alte Heimat herfielen, flohen die Steinbrecheroger und ließen alles zurück, sogar das Klanbanner.\n\nBrogg weiß, dass das Banner tief im Ogerhort, dem heutigen Flammenbau, aufbewahrt wurde. Brogg braucht das Klanbanner für seine Rache an den Drachen, die seine Freunde auf dem Gewissen haben.\n\nDer alte Hort von Broggs Klan, der Flammenbau, befindet sich nordwestlich von Morastwinkel und überall treiben sich Drachkin herum. Das Banner befindet sich tief in der Höhle. Seid vorsichtig, {name}.", sourceObjective = "Beschafft das Banner der Steinbrecher und bringt es Brogg in Morastwinkel.", progress = "Habt Ihr das Banner der Steinbrecher?", completion = "Ihr habt Broggs Dank, {name}. Brogg hat mit dem Klanbanner noch große Pläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[11161] = { id = 11161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz der Feindschaft", description = "Damit Brogg das Totem für sein Ritual herstellen kann, benötigt er die Essenzen der Kreaturen, die seine Freunde getötet haben. Der Hass und die Wut von Broggs Feinden wird die Magie seiner Rache verstärken.\n\nTötet Aschenschweife, Späher oder Bannschuppen der Feuermähnen und wendet Broggs Totem auf ihren Leiche an. Denkt daran, dass nur tote Drachkin ihre Essenzen freigeben!\n\nDie Kreaturen, die Ihr sucht, befinden sich im Flammenbau im Nordwesten und in den Ruinen der Steinbrecher im Norden.", sourceObjective = "Bringt 10 Essenzen eines schwarzen Drachkin zu Brogg in Morastwinkel.", progress = "Habt Ihr die Essenzen? Brogg braucht sie, um seine toten Freunde zu rächen!", completion = "Ihr habt Broggs Dank, {name}. Wenn Brogg erst einmal ihre Magie dem Totem hinzugefügt hat, kann er endlich die Geister seiner gefallenen Freunde erlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11162] = { id = 11162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung für den schwarzen Drachenschwarm", description = "Brogg kann es kaum erwarten, endlich Rache an dem schwarzen Drachenschwarm der Marschen zu üben. {name}, Ihr habt mir sehr dabei geholfen, mich auf diesen Moment vorzubereiten. Werdet Ihr mir auch weiterhin zur Seite stehen?\n\nNehmt Broggs Klanbanner und reist in Richtung Osten, bis Ihr auf eine Höhle trefft, die wie das Maul eines Drachen aussieht. Stellt das Banner der Steinbrecher direkt vor dem Höhleneingang auf und überbringt Onyxia Broggs Herausforderung.\n\nBrogg und die Steinbrecher werden Ihr Land zurückerobern!", sourceObjective = "Stellt das Banner der Steinbrecher nahe des Eingangs zu Onyxias Hort auf, wartet auf ihre Reaktion und kehrt anschließend zu Brogg in Morastwinkel zurück.", progress = "Broggs Rache ist nahe!", completion = "<Brogg hört Euch aufmerksam zu, während Ihr ihm die Geschehnisse am Eingang zu Onyxias Hort schildert.>\n\nBrogg vermutete schon, dass Onyxia zu feige ist, um sich Euch persönlich entgegenzustellen. Sie ist keinen Deut besser als der schwarze Drachenschwarm, der auch nur angreift, wenn der Sieg schon sicher ist.\n\nBrogg ist Euch für Eure Hilfe sehr dankbar, {name}, und er wird nie vergessen, was Ihr für ihn getan habt. Brogg wird weiterhin dafür kämpfen, dass die Steinbrecher zurückerobern, was rechtmäßig ihnen gehört!", sourceObjectiveStatus = "unverified-source-field" }
quests[11163] = { id = 11163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agentin mit Herz", description = "<Donna sieht sich um und beginnt zu flüstern.>\n\n{name}, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", sourceObjective = "Meldet Euch bei Donna Brascoe, um eine Belohnung für Euer Heldentum in Zul'Aman zu erhalten. Donna hält sich momentan in den Geisterlanden, direkt außerhalb von Zul'Aman auf.", completion = "<Donna sieht sich um und beginnt zu flüstern.>\n\n{name}, was ich Euch jetzt erzähle, muss streng vertraulich bleiben, verstanden?\n\nIch wurde von den Friedensbewahrern von Shattrath hierher entsandt, um mich in Budds Bande einzuschleusen. Ich muss gestehen, dass Ihr seit Eurer Ankunft mein Interesse geweckt habt und wohl einer meiner Hauptverdächtigen wart. \n\nAllerdings haben Eure Taten Euch von jeglichem Verdacht befreit. Tatsächlich werde ich Euch sogar dafür belohnen müssen, dass Ihr den wahnsinnigen Kriegsherrn Zul'jin bezwungen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11164] = { id = 11164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger der verlorenen Hauer", description = "Hey Mann! Du bist neu hier, oder? Kannst du mir einen Gefallen tun?\n\nBudd will seiner Waldtrollverkleidung den letzten Schliff verpass'n. Meinte, dass er schon fast fertig is' und nur noch eine letzte Sache braucht. Hauer.\n\nMeine Kürschnerkünste wär'n hier reine Zeitverschwendung. Trollhauer rauszieh'n... ah, bei so was würde mir sofort schlecht werd'n. \n\nBring mir 10 Trollhauer, ja, Mann?", sourceObjective = "Prigmon möchte, dass Ihr 10 Hauer eines Waldtrolls von Trollen in Zul'Aman einsammelt. Bringt sie zu ihm bei Budds Lager in den Geisterlanden.", progress = "Beeilt Euch, Mann!\n\nWenn ich Budd die Hauer nicht bald bringe, lässt er mich seine Maske allein in Zul'Aman testen!", completion = "Ahh... gut, genau danach habe ich gesucht!\n\nHier, der versprochene Lohn, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11165] = { id = 11165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Troll unter Trollen", description = "Hör zu, Mann, da gibt's noch was anderes, was du für den alten Prigmon tun könntest.\n\nZungam, mein alter Taugenichts von Vetter, steckt in Zul'Aman fest. Er lebt auch noch - ich habe sein Rauchsignal erst letzte Nacht geseh'n!\n\nIch sollte ihn eigentlich verrott'n lass'n, dafür, dass er mich in dieses ganze Schlamassel verwickelt hat... allerdings schuldet er mir noch eine Stange Geld.\n\nTu, was du kannst, um ihn da rauszuhol'n, das Abkassier'n kannste mir überlass'n!", sourceObjective = "Prigmon möchte, dass Ihr seinen Vetter Zungam in Zul'Aman ausfindig macht und ihm zur Seite steht.", completion = "Ich bin frei!\n\nAls man mich erwischt hat, hat man mir zwar fast alles entrissen, aber hier - nehmt meine letzten Münzen als Dank für Eure Mühe.\n\nWenn Ihr was braucht, helfe ich Euch natürlich jederzeit aus, Mann. Das ist das Mindeste, was ich tun kann....", sourceObjectiveStatus = "unverified-source-field" }
quests[11166] = { id = 11166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das X markiert Euren Untergang!", description = "Wie konnten diese Narren nur versagen? Ich habe ihnen gesagt, dass sie vorsichtig sein müssen - sogar meine Karte und Verkleidungen habe ich ihnen gegeben, damit sie sich leichter einschleichen können. Ach, was soll's. Das Gute an der Sache ist, dass diese Gelegenheit jetzt Euch und Euren Freunden zuteil wird.\n\nWenn Ihr Euch richtig anstellt, dann seid Ihr auf dem besten Weg, ein Teil meiner Mannschaft zu werden und damit an all dem unermesslichen Ruhm teilzuhaben, der bald mein sein wird. Nicht, dass ich Euch brauchen würde, vergesst das nicht.\n\nEs gibt da noch einige Bereiche auf der Karte, die noch besser erforscht werden müssen, bevor unsere Ausgrabung wirklich beginnen kann...", sourceObjective = "Betretet Zul'Aman und erkundet Halazzis Kammer, Jan'alais Plattform und Akil'zons Plattform. Berichtet Budd bei seinem Lager in den Geisterlanden von den Details dieser Bereiche.", completion = "<Budd versucht, nicht die Fassung zu verlieren.>\n\nÄh - so, {name} - es war aber auch an der Zeit, dass Ihr, äh, wieder zurückkehrt. Ja - Ihr haltet das gesamte Unterfangen auf.\n\nNun, dann lasst uns mal die Karte beschriften...", sourceObjectiveStatus = "unverified-source-field" }
quests[11167] = { id = 11167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die neue Seuche", description = "Nicht lange nachdem uns Arthas zu dieser elenden Existenz verurteilt hatte, arbeiteten wir in der Königlichen Apothekervereinigung an der Herstellung unserer eigenen Pest. Eine Pest, die alles Fleisch verschlingen würde, ob lebendiges, totes oder untotes.\n\nNun ist uns die Herstellung dieser Pest geglückt und wir sind hier, um sie persönlich an die Geißel zu liefern.\n\nDie Allianz hat das Schiff mit dem letzten Erregerstamm, der in unseren Labors in Unterstadt gezüchtet wurde, abgefangen. Begebt Euch zum Wrack, das von hier aus gesehen im Südosten liegt, und bergt so viele Behälter, wie Ihr nur könnt.", sourceObjective = "Apotheker Lysander im Hafen der Vergeltung will, dass Ihr 10 unversehrte Behälter aus dem Schiffswrack im Südosten bergt.", progress = "Konntet Ihr die Behälter bergen, {name}?", completion = "Schön, dass Ihr unverletzt zurückgekehrt seid. Die Gefahr, dass man beim Hantieren der Behälter infiziert wird, besteht. Vermutlich hätte ich Euch schon zuvor davor warnen sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11168] = { id = 11168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mischung verstärken", description = "Ich habe das Gefühl, dass die lange Reise auf See die Effektivität unserer Pest beeinträchtigt hat. Was wir brauchen ist ein starkes Gift, um die Wirksamkeit des Erregerstamms zu erhöhen.\n\nDie Krabben in der Nähe dieses Strands sind entfernte Verwandte der viel kleineren braunen Gezeitenkrabbler. Die kleinere tropische Art produziert ein paralytisches Gift, das stark genug ist, um einen Oger außer Gefecht zu setzen.\n\nWas größer ist, ist ja bekanntlich besser! Das Gift der viel größeren Drüsen der hier ansässigen Art sollte stärker sein. Bringt mir ein paar!", sourceObjective = "Bringt Apotheker Lysander im Hafen der Vergeltung im Heulenden Fjord 3 riesige Giftdrüsen von riesigen Gezeitenkrabblern.", progress = "Konntet Ihr die Giftdrüsen beschaffen, nach denen ich suche, {name}?", completion = "Ihr beweist weiterhin Eure Kompetenz, {name}. Hoffentlich wird dieses Gift genügen, um unsere Pest auf den gewünschten Wirkungsgrad zu bringen.\n\nZumindest sollte es dabei helfen, die Empfänger zu schwächen und sie leichter zu infizieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11169] = { id = 11169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe der Grimmtotem", description = "Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, hatte ich noch ein recht seltsames Totem an mich bringen können, welches unsere Feinde gegen uns eingesetzt haben.\n\nAnscheinend verschießt es im Gefecht Blitze aus wilder Energie. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beherbergen eine ganze Reihe aggressiver, scheckiger Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht die Krokilisken in Reichweite des Totems zu bekämpfen.", sourceObjective = "Lehrling Garion bei Tabethas Hof möchte, dass Ihr das erbeutete Totem an 10 scheckigen Staubsuhlerkrokilisken oder Staubsuhlerdolchrachen ausprobiert.", progress = "Wart Ihr mit dem Testen des Totems erfolgreich?", completion = "<Der Lehrling hört Euch aufmerksam zu, während Ihr ihm den Verlauf des Experiments schildert.>\n\nEin bisschen Dunst und ein paar Blitze? Das war alles? Hinter dem Totem muss noch mehr stecken! Die Grimmtotem würden so etwas doch nicht mit aufs Schlachtfeld bringen, wenn es keinen Nutzen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[11170] = { id = 11170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test auf See", description = "Wir haben soeben die Nachricht erhalten, dass Verstärkungstruppen auf dem Weg sind, um den Streitkräften der Allianz beizustehen. Sie konnten keinen besseren Zeitpunkt dafür wählen!\n\nWir benötigen dringend Testobjekte und diese Reservisten der Nordflotte sind ideal dafür geeignet!\n\nNehmt diese Seuchenphiolen an Euch und sprecht mit Kamilla, der Fledermausführerin. Sagt ihr, dass Ihr eine Reitfledermaus benötigt, um einen speziellen Auftrag für uns auszuführen.\n\nWerft die Phiolen auf die Verstärkungsflotte, sobald Ihr Euch über dem Meer befindet. Ich kann es kaum erwarten, zu sehen, was dabei herauskommt!", sourceObjective = "Sprecht mit Fledermausführerin Kamilla, nehmt eine Reitfledermaus und fangt die Verstärkungstruppen der Allianz ab. Werft die Seuchenphiolen auf 16 Reservisten der Nordflotte, sobald Ihr Euch in Reichweite befindet.", completion = "Hmmpff... die Berichte vom Schlachtfeld sind... nicht ermutigend!", sourceObjectiveStatus = "unverified-source-field" }
quests[11171] = { id = 11171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexlord? Pah!", description = "Ausgezeichnet! Meinem großen Auftritt in Zul'Aman steht fast nichts mehr im Weg.\n\nIhr habt gute Arbeit geleistet, {name}. Ich habe mit meiner Mannschaft gesprochen und sie scheint sich langsam mit Euch anfreunden zu können. Ich würde sagen, dass Ihr schon bald ein festes Mitglied der Gruppe sein könntet. Ihr müsst nur noch eine Sache erledigen - beseitigt diesen Hexlord.\n\nEs ist nichts weiter dabei, wirklich. Knöpft Euch diesen Schuft einfach vor, er wird wahrscheinlich sofort kehrt machen und abhauen. Gebrechlichere, ältere Trolle gleichen ihre Schwächen oft mit einem einschüchternden Titel aus, versteht Ihr?", sourceObjective = "Budd Winterhäldler in den Axthügeln möchte, dass Ihr Hexlord Malacrass in Zul'Aman tötet.", completion = "Endlich! Jetzt, da der leichte Teil der Arbeit erledigt ist, kann ich wenigstens einen weiteren Meilenstein in der Geschichte setzen. Vorerst muss ich mich aber noch einer kleinen Angelegenheit zuwenden - Euch...\n\nIch fürchte, {name}, dass es an der Zeit für mich ist, Euch gehen zu lassen. Ich glaube, dass Ihr Eure Leistung hier vollbracht habt, vielleicht seid Ihr sogar an Eure Grenzen gestoßen.\n\nSeid nicht traurig. Immerhin bedarf es für die Teilnahme an solch einem außerordentlichen Unterfangen schon sehr besonderer Individuen, die nicht gleich den Verstand verlieren. Hier, schaut doch mal, das ist ein kleines Andenken für Euch, damit Ihr mich nicht vergesst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11172] = { id = 11172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeppelinabsturz", description = "Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Erst vor ein paar Tagen kam hier eine Abgesandte des Dampfdruckkartells wegen dieser Sache vorbei.\n\nSie war auf der Suche nach Informationen über die Fracht des Zeppelins und dessen Piloten Beezil, aber keiner von uns hat den Absturz wirklich beobachtet. Ich bezweifle, dass sie die Aufräumarbeiten am Wrack und die Bergung der Fracht alleine bewältigen kann.\n\nWenn Ihr etwas Zeit habt, solltet Ihr mal bei Beezils Wrack vorbeischauen. Ihr findet es östlich von hier, in der Nähe der Berge.", sourceObjective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", completion = "Also haben Euch diese einzelgängerischen Magier hierher geschickt? Wie kann ich sicher sein, dass Ihr auch wirklich vertrauenswürdig seid?\n\nSchätze, ich kann jede Hilfe gebrauchen und eigentlich gibt es hier draußen auch nicht viel, das einen Magier interessieren könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[11173] = { id = 11173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reagenziendieb", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich ihn einfach zu ignorieren, meistens vergebens. Dieses Mal möchte ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Sobald Ihr mir das Gift bringt, werde ich Morlanns Vorräte auffrischen, noch bevor er irgendetwas merkt.", sourceObjective = "Bringt 6 Phiolen Marschengift zu Lehrling Garion bei Tabethas Hof.", progress = "Habt Ihr das Gift bekommen? Morlann wird jeden Moment bemerken, dass nichts mehr da ist...", completion = "<Lehrling Garion überprüft das Gift.>\n\nAbsolut perfekt! Er wird den Unterschied nie bemerken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11174] = { id = 11174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrosionsschutz", description = "Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, sie unter Kontrolle zu halten, werden sie das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann auf keinen Fall mit leeren Händen zurückkehren, {class}! Ihr müsst mir helfen, diese Schlamme aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um es anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 10 Schlamme auflöst.", progress = "Habt Ihr irgendwelche Fortschritte bei Eurer Brühschlammerjagd gemacht?", completion = "Es sieht da draußen schon etwas ruhiger aus...\n\nIch schätze, es ist an der Zeit, die Bergungsarbeiten fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11175] = { id = 11175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Tochter", description = "Sagt mir, ist es wahr? Sind die Forscher, die in die Flüsterschlucht hinabgestiegen sind, verrückt geworden?\n\nMeine Tochter ist die Vorarbeiterin der Forscherliga, die Richtung Norden zum Stählernen Tor gezogen ist. Nach all den schrecklichen Ereignissen, die uns in letzter Zeit zugestoßen sind, habe ich Angst um ihre Sicherheit.\n\nIch bitte Euch, {class} - ich bin zu alt, um mich auf die Reise zu machen. Ihr Name ist Irena. Werdet Ihr Euch dorthin begeben und nachsehen, ob es ihr gut geht?", sourceObjective = "Der alte Zasterstein hat Euch gebeten, seine Tochter, die Vorarbeiterin Irena Zasterstein, zu finden. Sie sollte sich am Stählernen Tor befinden.", completion = "Grrr. Ich hab's gewusst! Er ist viel zu beschützerisch! Das ist so peinlich.\n\nNicht, dass ich nicht darüber froh wäre, Euch zu sehen... Ich freue mich! Wir alle freuen uns. Wir können Eure Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11176] = { id = 11176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "Unsere Arbeit hier draußen fängt eigentlich gerade erst an. Aber jetzt, da wir diese Flugmaschinen aus Westwacht geliefert bekommen haben, sollten wir so richtig zum Arbeiten kommen.\n\nDas Problem ist, dass uns nicht genug qualifizierte Piloten zur Verfügung stehen. Und da sich die Situation im nördlich gelegenen Bruchwald verschlimmert, würde ich die Sache hier gerne schnell unter Dach und Fach bringen und dann wieder gen Heimat aufbrechen.\n\nFalls Ihr noch eine Hand frei haben solltet, dann sprecht mit einem meiner Chefarchäologen. Ihr könnt sie in der Nähe der Flugmaschinen im Norden und Süden der Ausgrabungsstätte finden.", sourceObjective = "Forscherin Irena Zasterstein hat Euch gebeten, mit einem der Chefarchäologen des Stählernen Tores zu sprechen. Diese befinden sich am Stählernen Tor.", completion = "Irena hat Euch hierher geschickt, nicht wahr? Gut, dann haben wir Arbeit für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11177] = { id = 11177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler beim Irrlichtanwesen", description = "Es gibt da einen Burschen, die Einheimischen nennen ihn \"Sumpfauge\" Jarl, der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nDas Irrlichtanwesen befindet sich in der Gegend beim Hexenhügel. Folgt der Straße von Theramore aus in Richtung Nordwesten, Ihr werdet das Anwesen finden, bevor die Straße in Richtung Westen abbiegt.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", completion = "Runter von meinem Grundstück... es sei denn, hm, Ihr wollt dem alten \"Sumpfauge\" beim Kochen zur Hand gehen. Was sagt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11178] = { id = 11178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Kriegsherren", description = "Ihr begutachtet die Phiole mit dem pulsierenden Blut und Eure Gedanken schweifen zu dem launischen kleinen Mann außerhalb von Zul'Aman.\n\nIhr könnt es kaum erwarten, Budds Gesicht beim Anblick dieser Phiole zu sehen!", sourceObjective = "Bringt Zul'jins Blut zu Budd bei seinem Lager in den Geisterlanden, direkt außerhalb von Zul'Aman.", progress = "<Budd versucht seinen Unmut bei Eurer Ankunft zu verbergen.>\n\nIhr schon wieder...\n\nWie sage ich es Euch am besten... Ich bin einfach viel zu beschäftigt, als dass ich Euch während meiner Vorbereitungen noch länger zur Seite stehen könnte, {name}.\n\nGlaubt mir, {name}, es ist zu Eurem Besten. Vielleicht schafft Ihr es ja, nach vielen Jahren harter Arbeit und mit etwas Glück, Euch selbst einen Namen zu machen.\n\nFalls ja, dann könnt Ihr erzählen, dass alles bei dem unvergleichlichen Budd Winterhäldler begonnen hat!", completion = "Da... das Blut von Zul'jin selbst, sagt Ihr?\n\n<Budd reißt sich zusammen und spricht weiter.>\n\nNun gut, ich weiß diese Geste zu schätzen, {class}, aber ich hätte ihn natürlich selbst mit Leichtigkeit vernichten können. Er wird niemals so furchtbar gewesen sein, wie man in den Legenden sagte. So etwas wird oft völlig übertrieben, Ihr werdet das schon noch verstehen. Wahrscheinlich litt der alte Kerl bereits unter Arthritis!\n\nEgal, ich denke, dass dies das Mindeste war, was Ihr im Gegenzug für meine Güte habt tun können.\n\nVerschwindet jetzt - ich muss diese Phiole loswerden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11179] = { id = 11179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finlay ist darmlos", description = "Jetzt seht Euch mal all diese Armbrustschützen an - und wer muss ihre ganzen Waffen instand halten? Ich, Finlay Pfeilmacher!\n\nDer Hauptmann hat meinem Helfer befohlen, sich für den Umzug nach Fort Wildervaar bereitzumachen, und ich habe nicht die Zeit, um allen Katzendarm für ihre Sehnen zu sammeln!\n\n{class}, seid <ein guter Kamerad/eine gute Kameradin> und beschafft mir ein paar Katzendärme. Die Nebelsäbler, die durch den Fjord streifen, werden dafür ausreichen - doch denkt daran, dass Ihr nur die makellosesten Innereien mitbringt! Mit angerissenen Därmen können wir nichts anfangen.", sourceObjective = "Sammelt 7 Stück makellosen Schattensäblerkatzendarm und kehrt zu Finlay Pfeilmacher zurück. Er befindet sich in Westwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11180] = { id = 11180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sucht den Hexenhügel heim?", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", sourceObjective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr Informationen von 10 auferstandenen Gebeinen oder auferstandenen Geistern sammelt.", progress = "Was habt Ihr von den Spukgeistern erfahren können?", completion = "<Mordant holt ein kleines Blatt Papier und einen Stift hervor und beginnt, sich Notizen über Eure Berichterstattung zu machen.>\n\nIhr konntet herausfinden, dass sich die Geister an diesem Ort auf die Anzahl aller belaufen, die jemals auf diesem Land gelebt haben, und nicht nur auf die vorherigen Besitzer.\n\nEtwas hat sie zu Grunde gerichtet und getötet. Wer der Sache verfällt, erfährt die Wahrheit nicht, bis es zu spät ist. Wir müssen dem Ganzen ein Ende bereiten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11181] = { id = 11181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hexenfluch", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, {name}. Es könnte unsere letzte Hoffnung sein.", sourceObjective = "Bringt 9 Zweige Hexenfluch zu Mordant Grimsby beim Irrlichtanwesen.", progress = "Konntet Ihr ein paar Pflanzen finden? Wir müssen schnell handeln, bevor das Übel, das hinter dieser Heimsuchung steckt, in dieser Gegend vollends überhand nimmt.", completion = "<Mordant nimmt das Pflanzenbündel von Euch entgegen.>\n\nDiese entsprechen exakt der Beschreibung! Während Eurer Abwesenheit habe ich die Fackel vorbereitet. Jetzt müssen wir die Pflanzen nur noch hier am Ende befestigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11182] = { id = 11182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursachen", description = "Alles in der Natur strebt nach einem Gleichgewicht -ein Gleichgewicht, das nur dann gestört wird, wenn diejenigen, die nicht mit der Natur im Einklang sind, eingreifen.\n\nIhr verschwendet Eure Kraft, wenn Ihr die Welpen und Drachen tötet. Die eigentlichen Missetäter hinter der Ausbreitung dieser magisch brennenden Wälder sind die vor Kurzem erwachten Vrykul und ihr Gebieter Skeld Drachensohn.\n\nWenn Ihr Blut vergießen wollt, dann fangt mit denen an. Ihr Unterschlupf befindet sich im Süden der Glutstätte.", sourceObjective = "Tötet 5 Tierführer der Drachenschinder und Skeld Drachensohn. Geht in die Glutstätte und sucht ein Urtum der Glutstätte auf, falls Ihr das schaffen solltet.", progress = "Na mein Kleiner, wie steht es im Kampf gegen die Antreiber?", completion = "Schade, dass man ein Raubtier nur mit der Hilfe eines anderen Raubtiers erlegen kann - aber so ist das Gesetz der Natur nun einmal.\n\nVielleicht können die Protodrachen und -welpen jetzt wieder in Frieden leben. Doch angesichts des erneuten Erwachens der Vrykul, bezweifle ich das.", sourceObjectiveStatus = "unverified-source-field" }
quests[11183] = { id = 11183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Hexenhügels", description = "Die Fackel ist fertig. Stellt sie am Ende des Docks auf und seid auf alles gefasst.\n\nIch weiß wirklich nicht, was der Rauch der Fackel bewirken wird... falls überhaupt etwas geschieht. Eigentlich hege ich für gewöhnlich Zweifel an dererlei Hokuspokus, aber wir haben keine andere Wahl. Viel Glück, Ihr und Jarl könnt es brauchen.", sourceObjective = "Mordant Grimsby beim Irrlichtanwesen möchte, dass Ihr die Fackel am Ende des Docks aufstellt und alles bezwingt, was daraufhin erscheint.", progress = "Ist es vorbei?", completion = "Es hat funktioniert?\n\n<Mordant räuspert sich.>\n\nIch meine... es hat funktioniert! Jarl und ich stehen tief in Eurer Schuld, {name}. Jetzt muss ich mich nur noch um den schlechten Einrichtungsgeschmack meines Freundes kümmern. Ich befürchte, dass das nicht allzu einfach wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11184] = { id = 11184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlächterklaue der Gefräßige", description = "Reisende und Mitarbeiter des Dampfdruckkartells werden gebeten, den Blutsumpfbau westlich der Siedlung weiträumig zu umgehen.\n\nDas gesamte Areal wird von äußerst gefährlichen Raptoren bewohnt. Das Leittier, Schlächterklaue der Gefräßige, ist für den Tod von mindestens zwei Ingenieuren des Dampfdruckkartells verantwortlich.\n\nDrazzit Tropfhahn wurde autorisiert, jeden, der der Bedrohung durch Schlächterklaue ein Ende setzt, großzügig zu entlohnen.", sourceObjective = "Tötet Schlächterklaue den Gefräßigen und meldet Euch anschließend bei Drazzit Tropfhahn in Morastwinkel.", completion = "Endlich hat sich jemand um diese Sache gekümmert. Ich dachte schon, dass ich die Belohnung verdreifachen müsste, bevor jemand diesen verdammten Raptor zur Strecke bringt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11185] = { id = 11185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief der Apothekerin", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, enthält alarmierende Beweise für das enge Bündnis der Grimmtotem mit den neuen Herren von Lordaeron.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nAndello Porter, der SI:7-Agent bei Tabethas Hof, sollte umgehend von diesem Brief erfahren.", sourceObjective = "Bringt den versiegelten Brief zu Andello Porter auf Tabethas Hof.", progress = "Was habt Ihr da, {class}?", completion = "<Andello liest den Brief, bestürzt über dessen Inhalt.>\n\nDies bestätigt lediglich unseren Verdacht, den wir seit langem über das Zusammenspiel von Horde und den Verlassenen hegen. Mit Hilfe der Magie und den Waffen der Verlassenen würden die Grimmtotem zu einem noch viel gefährlicheren Gegner werden. Das Gleichgewicht der Macht in Kalimdor könnte ernsthaft in Gefahr sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11186] = { id = 11186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Verrats?", description = "Dieser Brief, der bei dem Leichnam einer Apothekerin der Verlassenen gefunden wurde, deutet auf eine geheime Korrespondenz zwischen Unterstadt und den Anführern der Grimmtotem hin.\n\n\"Apothekerin Cylla wurde als Beweis unserer Treue und als Zeichen für unser neu geschaffenes Bündnis entsandt, um Euch bei dem Kampf gegen unseren gemeinsamen Feind im Land von Kalimdor zur Seite zu stehen. Niemand wird unserer vereinten Macht und Entschlossenheit standhalten können.\"\n\nVielleicht kann Euch Nazeer Blutlanze in Brackenwall sagen, was mit dieser Information geschehen soll.", sourceObjective = "Bringt den versiegelten Brief zu Nazeer Blutlanze in Brackenwall.", progress = "Was habt Ihr da, {class}?", completion = "Wenn es das ist, was es zu sein scheint, dann müssen die Verlassenen eine gute Erklärung dafür finden!\n\nDie Torheiten der Grimmtotem haben die Geduld des Kriegshäuptlings schon seit langem auf die Probe gestellt. Für gewöhnlich war es üblich, dass diese Angelegenheiten unter den {race} ausgemacht werden, aber das könnte nun anders aussehen.\n\nEs wird einige Zeit dauern, bis man den Verdächtigungen nachgegangen ist. Sprecht mit niemandem über das, was Ihr heute gesehen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11187] = { id = 11187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierleutnant Malister", description = "DAS IST UNFASSBAR! Die Protodrachen greifen die Wache an!\n\nBestien wie diese, hätten eigentlich davon abgeschreckt werden sollen, als Ihr Euch um ihr Gelege und ihre Welpen gekümmert habt.\n\nIhr habt Euch doch um sie gekümmert, oder?\n\n{name}, die Situation verlangt direktere Maßnahmen. Sprecht mit meinem Berater Magierleutnant Malister. Er wird Euch das geben, was Ihr benötigt, um diese teuflischen Kreaturen zu erreichen.", sourceObjective = "Hauptmann Adams möchte, dass Ihr mit seinem Berater Magierleutnant Malister sprecht. Er befindet sich in Westwacht.", completion = "<Malister winkt Euch herbei und flüstert Euch zu.>\n\nIch habe befürchtet, dass so etwas passieren könnte. Ich habe versucht, den Hauptmann von seiner Vorgehensweise abzuraten - doch er ist ein Zwerg der Tat, der ein genaues Bild davon hat, wie die Dinge ablaufen sollen.\n\nLasst uns über die Möglichkeiten sprechen, die uns noch offen bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11188] = { id = 11188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Untaten...", description = "Nun da wir diese Protodrachen aus der Glutstätte verärgert haben, könnten sie dazu neigen, ihre Angriffe auf die Wache fortzuführen. Das darf nicht passieren.\n\nIch tue es zwar nur ungern, auf eine Untat eine weitere folgen zu lassen, aber in diesem Fall sieht es so aus, als müssten wir diese Kreaturen vernichten. Eine bedauerliche Vorgehensweise, aber eine, der wir uns nichtsdestotrotz verpflichten müssen.\n\nNehmt meinen Zauberstab. Ich habe zwar versucht, seine Reichweite zu erhöhen, aber austeilen tut er nicht viel. Was er jedoch kann, ist die Aufmerksamkeit der Protodrachen auf sich zu ziehen.", sourceObjective = "Magierleutnant Malister in Westwacht hat Euch damit beauftragt, 3 Protodrachen zu vernichten.", completion = "<Der Magierleutnant seufzt.>\n\nEine unerfreuliche Sache, so viel ist sicher. Tja, was getan ist, ist getan. Wenn wir Glück haben, werden sich die Welpen in der Glutstätte, die einmal zu Drachen heranwachsen werden, nicht mehr an unsere schändlichen Taten erinnern.\n\nUnd wenn wir ein wenig mehr Glück haben, wird sich dieser magische Wald nicht weiter ausbreiten.\n\nHier, {name}. Bitte, nehmt dieses Almosen aus unserer Schatzkammer entgegen... für all Eure Mühen. Es ist das Mindeste, was wir tun können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11189] = { id = 11189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Mal", description = "Tag auch. Bin ich tot? Ich denke schon - ich schwebe ja über meinem eigenen Körper!\n\nOh, welch unglückliche Wendung des Schicksals. Ich wollte gerade um Irenas Hand anhalten, als die Geißel über uns hereinbrach.\n\nIch weiß, dass sie immer noch am Leben ist... Ich kann sie in meinem Herzen fühlen.\n\n{class}, meint Ihr, dass Ihr mich sicher zu ihr hinbringen könntet? Die Geißel kann meinen Geist noch immer sehen und mir zweifellos schreckliche Dinge antun.\n\nIch möchte einen letzten Blick auf ihr wunderschönes Gesicht werfen. Ihr könnt dann für mich sagen, dass ich sie liebe.", sourceObjective = "Eskortiert den Geist von Entdecker Jaren sicher zu Irena Zasterstein. Sie befindet sich am Stählernen Tor im heulenden Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[11190] = { id = 11190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht allen passt dieselbe Größe", description = "Na, <Junge/Mädchen> - welches Genie hat denn unsere Kanonen nicht in der Standardgröße gebaut? Jetzt müssen wir spezielle Kanonenkugeln herstellen, um sie aus den Teufelsgeräten zu feuern!\n\nIch wäre Euch wohlgesinnt, solltet Ihr Euch aufmachen und die Kugeln finden, die wir schon verschossen haben. So wie dieser Haufen schießt, werden sie mit Sicherheit überall im Süden und Osten verstreut sein.\n\n<Der Kanonier breitet seine Arme aus, um Euch eine Vorstellung von der Größe der Kanonenkugeln zu geben.>\n\nDas wäre sicherlich schneller, als wenn wir sie neu herstellen würden.", sourceObjective = "Kanonier Ely hat Euch damit beauftragt, 10 Kanonenkugeln der Westwacht einzusammeln und sie zu ihm zurückzubringen. Er befindet sich in Westwacht.", progress = "Unsere Munition hier in der Gegend wird langsam ziemlich knapp, {class}. Unsere Feinde brauchen eins auf die Mütze - ganz besonders Skorn!\n\nHabt Ihr noch mehr Kugeln für uns?", completion = "Oh, seid gesegnet, {name} - seid gesegnet!\n\nStellt sie doch gleich dort ab, wo Ihr steht. Ich werde einen meiner Jungs schon bald losschicken, um sie zu verladen. Dann müssen wir uns keine Sorgen mehr darum machen, dass uns beim Bombardieren von Skorn die Kugeln ausgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11191] = { id = 11191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Leuchtturm", description = "Der alte Leuchtturm draußen im Osten ist schon seit langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, den ganzen Betrieb wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann wesentlich sanfter zu den Docks gelangen. Was kann ich dagegen noch einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", sourceObjective = "Sprecht mit Babs Zischeldrill bei dem Leuchtturm auf der Insel östlich von Theramore.", completion = "Gut. Ich kann jede Hilfe gebrauchen. Als Allererstes möchte ich die Lampe wieder zum Leuchten bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11192] = { id = 11192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drescheröl", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch unelegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Man findet sie genau unterhalb der Docks von Theramore.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", sourceObjective = "Bringt 4 Behälter mit Drescheröl zu Babs Zischeldrill beim Leuchtturm in der Nähe von Theramore.", progress = "Konntet Ihr etwas Drescheröl auftreiben?", completion = "Nun, ich habe ja meine Zweifel, aber es ist im Moment eben die einzige Lösung. Sobald das Ganze wieder funktioniert, wird sich sicherlich etwas anderes zum Betreiben der Lampe finden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11193] = { id = 11193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimtückische Bewohner der Tiefe", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", sourceObjective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", progress = "Was darf es heute sein? Der Barsch ist ausgezeichnet.", completion = "Nun ja, mir dieses Buch zukommen zu lassen, war ganz schön aufmerksam von der alten Babs. Ich weiß nicht, ob Ihr ein wenig darin geblättert habt, aber in den Geschichten steckt schon die ein oder andere Wahrheit. Seefahrer erfinden sowas nicht einfach, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[11194] = { id = 11194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das wahr?", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut aufgelacht habt. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran ist?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr ganz sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in der Tidenbucht, welche südwestlich jenseits der Bucht der Düstermarschen liegt.", sourceObjective = "Sprecht mit Nat Pagle bei Nats Angelplatz in den Düstermarschen.", completion = "So, Ihr wollt also etwas über Meeresungeheuer wissen? Hmm... na gut, ich hätte da ein Angebot für Euch. Das Ganze beinhaltet aber reichlich Alkohol und Ihr werdet dabei ziemlich in Verlegenheit geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11195] = { id = 11195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spiel mit der Puppe", description = "Ich bin gerührt, {name}, is' kein Scherz, Mann. Ich kann mich nich' daran erinnern, dass <ein/eine:r> {race} Zungam jemals aus der Patsche geholf'n hätte.\n\nDas hier habe ich einem der Wilden weggenomm'n, als man mich festgebund'n hat. Es sieht zwar nich' nach etwas Großartigem aus, aber wenn jemand den Wert einschätz'n kann, dann ist das mein guter alter Freund Gaunah!\n\nSolltest du hier lebend wieder rauskomm'n, dann statte ihm einen Besuch in Shattrath ab, es lohnt sich.", sourceObjective = "Bringt die zerlumpte Voodoopuppe zu Gaunah in Shattrath.", progress = "Hey, {name}! Ich habe gehört, dass Ihr Euch einen Platz in Budds Mannschaft verschafft habt. Ihr werdet keine Zeit haben, dies zu bereuen, Kumpel, das kann ich Euch versprechen.\n\nWas habt Ihr denn da, Mann?", completion = "Hey, wo habt Ihr denn das her?\n\nNein, nein, sagt's nicht - das stammt vom Hexenfürst persönlich! Jetzt ist mir alles klar. Starkes Mojo! Der Träger dieses Relikts, egal wie oft er schon in Ungnade gefallen sein mag, wird vom Hochadel stets verehrt werden. Unglaublich!\n\n<Als Gaunah die Puppe in die Höhe hält, fällt ein kleiner, rostiger Glücksbringer von deren Hals. Der Troll will ihn gerade wegstecken, aber wendet sich Euch dann mit einem Funkeln in den Augen zu.>\n\nIch habe gerade kein Bares bei mir, Mann, aber nehmt doch bitte das hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[11196] = { id = 11196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegsherr der Amani", description = "Die Amani haben ihre Streitmacht wiederaufgebaut und einen neuen Kriegsherrn hervorgebracht, der sie anführt, {name}. Der nennt sich Daakara der Unbesiegbare, aber wir wollen doch mal sehen, ob er seinem Namen gerecht wird.\n\nDu musst erst all seine Handlanger aus dem Weg räumen, bevor du Daakara gegenübertreten kannst. Besieg ihn und bereite den Ambitionen der Zandalari und der Amani ein Ende.", sourceObjective = "Besiegt den neuen Kriegsherrn der Amani, Daakara.", progress = "Dieser neue Kriegsherr muss fallen, bevor die Zandalari hier dauerhaft Fuß fassen können.", completion = "Der Sieg gehört uns, {name}! Die Zandalari fliehen und ohne die Führung ihres Kriegsherrn werden die Amani bald in interne Streitigkeiten verfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11198] = { id = 11198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt Tethyr!", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", sourceObjective = "Major Mühlens bei den Docks von Theramore möchte, dass Ihr Tethyr bezwingt.", completion = "Gut gemacht, {name}! Ich muss gestehen, dass ich beim ersten Anblick des Ungeheuers zu zweifeln begann, ob wir die Docks wirklich verteidigen können. Ihr habt Eure Arbeit jedoch bravourös gemeistert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11199] = { id = 11199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Kundschafter Wisslich", description = "{name}, nun da man sich diese verdammten Proto-Dinger einmal vorgenommen hat, habe ich eine weitere Aufgabe für Euch.\n\nEiner meiner Kundschafter hat mir von verdächtigen Aktivitäten der Verlassenen im Süden berichtet. Es sieht so aus, als würden sie im Vrykuldorf namens Halgrind ihr Unwesen treiben.\n\nIch möchte, dass Ihr die dortigen Ermittlungen persönlich übernehmt. Sprecht mit Kundschafter Wisslich, findet heraus, was er bisher in Erfahrung bringen konnte und macht dort weiter, wo er aufgehört hat.\n\nEr wurde das letzte Mal am Glutspeerturm gleich westlich von Halgrind gesehen.", sourceObjective = "Hauptmann Adams möchte, dass Ihr Euch bei Kundschafter Wisslich am Glutspeerturm meldet.", completion = "Oh, gut, Hilfe - und genau zur rechten Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[11200] = { id = 11200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein bloßer Zufall", description = "Wir haben die Ruinen des Gasthauses so gut es geht nach Beweisen abgesucht. Ich bin beunruhigt, was die Ergebnisse unserer Ermittlungen betrifft, aber wir müssen die Wahrheit erfahren.\n\nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe im Nordosten. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.", sourceObjective = "Krog in Brackenwall möchte, dass Ihr ihm 7 Waffen der Schwarzhufe bringt.", progress = "Was konntet Ihr im Dorf der Schwarzhufe finden?", completion = "<Krog betrachtet die Waffen und die Rüstung, die Ihr ihm aus dem Dorf der Schwarzhufe mitgebracht habt.>\n\nDas ist ganz unverkennbar die Arbeit von Mosarn. Ihn weiter auszufragen würde zu viel Aufmerksamkeit erregen. Wie gut, dass wir bei Angelegenheiten mit den Grimmtotem etwas mehr Handlungsfreiheit haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11201] = { id = 11201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verschwörung der Grimmtotem", description = "Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Hochrangige Vertreter der Grimmtotem hießen bereits Morde und Entführungen gut, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten Ihr nächstes Ziel sein.\n\nDas Dorf der Schwarzhufe im Nordosten, in der Nähe des Blaumoors, ist eine große neue Siedlung der Grimmtotem. Ihre Anführer, die Ältesten, dürften alle Anordnungen von Donnerfels bei sich tragen. Versucht an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.", sourceObjective = "Bringt die Schlachtpläne der Grimmtotem zu Krog in Brackenwall.", progress = "Konntet Ihr die Pläne ausfindig machen?", completion = "<Krog überfliegt die Schlachtpläne.>\n\nIch bin mir jetzt ganz sicher, dass die Grimmtotem einen Angriff auf die Menschen planen. Allerdings weiß ich nicht, was ihre Absichten uns gegenüber sind. Die Handlungen der Grimmtotem haben in der Vergangenheit für gespannte Verhältnisse innerhalb der Horde gesorgt, doch der Kriegshäuptling hat die Lage bis jetzt immer entschärft.", sourceObjectiveStatus = "unverified-source-field" }
quests[11202] = { id = 11202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission 'Ewige Flamme'", description = "Die Verlassen führen nichts Gutes im Schilde und so wie ich das sehe, spielen diese Pestkessel voller Schlamm dabei eine große Rolle.\n\nIch würde vorschlagen, dass wir sie zerstören, bevor man sie für weitere Zwecke verwenden kann. Ich war einmal so frei, ein paar Fackeln aus der Glutstätte schon bereitzustellen. Die Dinger brennen nun schon seit Tagen!\n\nHier, nehmt. Ich kann sie nicht so gut gebrauchen wie Ihr. Sie werden Euch bei der Zerstörung der Kessel von großem Nutzen sein.", sourceObjective = "Kundschafter Wisslich im Glutspeerturm hat vorgeschlagen, dass Ihr mithilfe der Immerbrandfackeln die 4 Pestkessel um Halgrind herum zerstört.", completion = "Fein!\n\nAber was genau war das noch einmal, was Ihr in diesen Kesseln gefunden habt? Wollt Ihr damit sagen, dass die Verlassenen dort unten eine Pest unter den Vrykul verbreiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[11203] = { id = 11203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Tabetha auf", description = "Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zum Üben noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für den Angriff auf das Gasthaus verantwortlich sind, noch immer auf freiem Fuß sind.\n\nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.\n\nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "<Tabetha lächelt.>\n\nKrog möchte, dass ich die Grimmtotem ausfindig mache, ja? Nun gut, dafür braucht es aber keine Magie.\n\nScheinbar haben wir einen gemeinsamen Feind. Die Grimmtotem haben in der Nähe einen Außenposten errichtet und sind mir und meinen Schülern ein ständiger Dorn im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[11204] = { id = 11204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Krog", description = "Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, detaillierte Informationen zu jedem Stück zu behalten.\n\nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, die Grimmtotem hegen auch eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Er hat bestätigt, dass die Grimmtotem seine besten Kunden sind? Mosarn hat uns weit mehr geholfen als er ahnt. Mit dieser Menge an Hinweisen, die die Grimmtotem belasten, dürften wir unsere Hauptverdächtigen gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11205] = { id = 11205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um die Angreifer handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt genau nördlich von meinem Hof, ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems verraten.", sourceObjective = "Brennt das nördliche, östliche und nordöstliche Zelt beim Grollhornposten nieder und kehrt anschließend zu Tabetha auf ihrem Hof zurück.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Unsere letzte Botschaft dürfte bei den Grimmtotem angekommen sein.\n\nWas Euch betrifft, so solltet Ihr Eurer Kontaktperson in Brackenwall von Eurem Erfolg berichten. Ich weiß, dass die Zerstörung des Gasthauses Zur süßen Ruh zwischen Horde und Allianz für Spannungen sorgen könnte. Sollten mir Ermittler von Theramore begegnen, werde ich ihne gerne berichten, dass die Grimmtotem eigenständig gehandelt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11206] = { id = 11206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Walten der Gerechtigkeit", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden. Aber ich habe den Eindruck, dass Euch das vermutlich nicht kümmert. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus \"Zur Süßen Ruh\" bestraft.\n\nGeht und sagt Eurem Vorgesetzten, dass seiner Rache genüge getan wurde.", sourceObjective = "Kehrt zu Krog in Brackenwall zurück.", completion = "<Krog hört sich Euren Bericht an.>\n\nIch bin beeindruckt, {name}. Ich hatte vermutet, dass die verbrecherischen Grimmtotem nicht so einfach auszumachen sind. \n\nTabethas Warnungen stoßen nicht auf taube Ohren, allerdings unterliegt es nicht meiner Verantwortung, die Grimmtotem zu bestrafen. Ich werde es natürlich in meinem Bericht an den Kriegshäuptling erwähnen. Sprecht mit niemandem über die Sache, bevor Thrall sich der Grimmtotem angenommen hat. Ihr habt gute Arbeit geleistet, indem Ihr das Rätsel um das Gasthaus Zur süßen Ruh gelöst und uns vom Verdacht der Einwohner von Theramore befreit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11207] = { id = 11207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Der Zeppelin hatte Morastwinkels Vorräte für die nächsten sechs Monate geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch auf Dauer ist das keine Lösung.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt, was die Sache ziemlich erschwert. Ohnehin denke ich, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir bei der Bergung helfen?", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", progress = "<Moxie scheint beinahe wahnsinnig vor Sorge.>\n\nIst die Fracht intakt? Konntet Ihr irgendetwas bergen?", completion = "Wow! Ich hätte nie geglaubt, dass da draußen noch so viel intakte Fracht liegt. Keine Ahnung, welche Ausbeute Drazzit von uns erwartet, aber zunächst wird er sich mit diesem Fund zufrieden geben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11208] = { id = 11208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Drazzit", description = "Drazzit erwartet sicher bald Nachricht von mir, doch solange die Absturzstelle nicht gesichert ist, kann ich hier nicht weg. Würdet Ihr, sofern Ihr etwas Zeit erübrigen könnt, einen Teil der geborgenen Fracht nach Morastwinkel bringen?\n\nFalls Ihr den Weg nicht kennt: die Siedlung liegt südwestlich von hier, hinter den Ruinen der Steinbrecher. Ihr könnt auch die Straße, die von Tabethas Hof wegführt, nehmen. Nachdem Ihr in Morastwinkel angekommen seid, sucht nach einem Typen namens Drazzit Tropfhahn.", sourceObjective = "Bringt die Zeppelinfracht zu Drazzit Tropfhahn in Morastwinkel.", progress = "Ja?", completion = "<Drazzit nimmt die Fracht entgegen.>\n\nIch bin so hungrig, ich könnte glatt einen ganzen Drachen verschlingen! Schön, dass es Moxie endlich gelungen ist, einen Teil der Fracht hierher zu schaffen. Wir waren zuletzt sogar dazu verdammt, mit dem Oger um seine Jagdbeute zu würfeln, ansonsten wären wir verhungert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11209] = { id = 11209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nats Abmachung", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", sourceObjective = "Nat Pagle bei Nats Angelplatz möchte, dass Ihr seinen neuen Köder ausprobiert.", progress = "Vergesst nicht, die Abmachung lautet \"Kommt nicht eher wieder, bevor Euch etwas gebissen hat\".", completion = "Nicht übel, aber wenn ich Ihr wäre, dann würde ich so schnell wie möglich ein Bad nehmen.\n\nSo, jetzt zu dem Meeresungeheuer...\n\nNehmt Euch ruhig ein oder zwei Bierchen in der Zwischenzeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11210] = { id = 11210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es ist wahr!", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit einem klugen Menschenverstand dergleichen tun.\n\nDas ist also Euer Plan! Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", sourceObjective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", completion = "<Ihr erzählt von Eurem Besuch bei Nat Pagle, lasst dabei den Teil mit dem Ködertest aber vorsichtshalber aus.>\n\nNun, es hört sich ganz so an, als ob wir genau wissen, was es zu tun gilt. Ich treffe schon einmal die Vorbereitungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11211] = { id = 11211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Morastwinkel", description = "Als diese Goblinfrau... wie war doch gleich ihr Name... Boxie, Foxy... Moxie, genau! Egal, jedenfalls erwähnte sie, als sie auf ihrem Weg zum Zeppelinwrack hier vorbeikam, dass die Siedlung Morastwinkel in Schwierigkeiten wäre.\n\nAnscheinend hatte der abgestürzte Zeppelin wohl Vorräte für die Siedlung geladen. Folgt einfach der Straße südlich von hier, vorbei an den Ruinen der Steinbrecher. Kurz danach solltet Ihr Morastwinkel erreicht haben.\n\nSprecht dort unten mit Drazzit Tropfhahn und seht, ob er nicht Eure Hilfe gebrauchen kann.", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Es war gut, dass Tabetha Euch hierher geschickt hat. Solange der Zeppelin noch nicht geborgen ist, muss ich sie um einige Nahrungsmittel bitten. Leider ist sie selbst gerade knapp an Vorräten. Oh, falls Ihr nach einer Herausforderung sucht: ich habe erst kürzlich ein Kopfgeld auf einen besonders gefährlichen Raptor ausgesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11212] = { id = 11212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Hof", description = "Tief im Herzen des Sumpfs lebt eine alte Frau namens Tabetha. Wir wussten noch nie wirklich viel über sie, außer dass sie älter ist, als sie scheint. Sie hat uns hier von Zeit zu Zeit geholfen und auch den Frieden zwischen der Horde und unseren Kräften schon oft bewahrt.\n\nNormalerweise hörten wir regelmäßig von ihr, aber seit Kurzem ist es still geworden.\n\nKönntet Ihr einmal bei ihr vorbeischauen, falls Ihr Zeit habt? Folgt einfach der Straße jenseits der Nordwacht weiter Richtung Süden und in den Morast. Ihr könnt ihren Hof von der Straße aus sehen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "Gut, dass man Euch von Theramore hierher entsandt hat. Der von Eurem Freund gehegte Verdacht entspricht der Wahrheit. Wir haben ein paar neue Nachbarn... und dabei handelt sich nicht um die Sorte, der man gerne ein Stück Kuchen bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11213] = { id = 11213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht nach Tabetha", description = "Eine Menschenfrau namens Tabetha lebt auf einem kleinen Hof, fast inmitten der Marschen. Normalerweise würde ich mich nicht mit einem Menschen abgeben, aber ihre Hilfe hat sich schon so manches Mal als nützlich erwiesen.\n\nLeider habe ich seit geraumer Zeit nichts mehr von ihr gehört und ich würde mir wünschen, dass jemand zu ihrem Hof reist und nach dem Rechten sieht.\n\nWenn Ihr der Straße aus dem Dorf in Richtung Süden und anschließend ins Innere des Sumpfs folgt, werdet Ihr auf ihren Hof im Herzen des Morasts stoßen.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "Welch Glück, dass Nazeer Euch hierher entsandt hat. Wir haben ein paar neue Nachbarn und seit sie ihr Lager hier aufgeschlagen haben, waren sie nichts als Störenfriede.", sourceObjectiveStatus = "unverified-source-field" }
quests[11214] = { id = 11214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission nach Morastwinkel", description = "Das Dampfdruckkartell hat vor Kurzem im südlichen Teil der Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Würdet Ihr für uns dorthin reisen?", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "So, Theramore ist also an Geschäften mit uns interessiert? Nun, ein derartiges Angebot werde ich nicht ablehnen. Neue Vorräte sind hier nur schwer zu beschaffen, also sind neue Handelspartner stehts willkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11215] = { id = 11215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft Morastwinkel", description = "Für den neuen Außenposten des Dampfdruckkartells im südlichen Teil der Marschen sieht es momentan nicht so gut aus. Der Zeppelin mit den Vorräten für Morastwinkel ist abgestürzt und nun fehlt es an Werkzeugen, Nahrung und medizinischen Versorgungsgütern.\n\nFolgt der Straße nach Süden in die Marschen. Bevor Ihr Morastwinkel erreicht, führt Euch die Straße zunächst noch an Tabethas Hof und den Ruinen der Steinbrecher vorbei. Bitte helft den Einwohnern von Morastwinkel, so gut Ihr könnt.", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Jede Hilfe ist willkommen! Wir richten uns hier gerade ein und versuchen, das Beste aus unserer Situation hier zu machen, bis die Vorräte des Zeppelins eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11216] = { id = 11216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzmagier Alturus", description = "Mein Mentor hat mich hierher geschickt, um nach Unterstützung zu suchen, aber unglücklicherweise darf ich mich nicht außerhalb des Unteren Viertels aufhalten. Die Leute, die dieses Etablissement besuchen, sind leider alles andere als hilfreich.\n\nIhr scheint anders zu sein, begebt Euch wohl gerne auf Abenteuer. Wenn Ihr uns bei unserem Unterfangen unterstützen wollt, dann sprecht mit Erzmagier Alturus außerhalb von Karazhan, Medivhs alter Behausung.\n\nIch werde versuchen, mir in der Zwischenzeit Zutritt zum Rest der Stadt zu verschaffen. Man munkelt, dass sich ein ehemaliger Kollege von uns hier aufhält.", sourceObjective = "Sprecht mit Erzmagier Alturus außerhalb von Karazhan im Gebirgspass der Totenwinde.", completion = "Danke, dass Ihr Euch die Zeit genommen habt, um uns hier zur Hilfe zu kommen. Vor uns liegt eine Menge wichtiger Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11217] = { id = 11217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwindet den Drachen", description = "Nachdem der Zeppelin mitsamt unseren Vorräten abgestürzt ist, gehen uns langsam die Medikamente und Verbände aus.\n\nWir tun was wir können, aber inmitten all dieser Insekten, umgeben von Feinden, bleiben Verletzungen nicht aus. Ich habe kürzlich eine Pflanze entdeckt, welche die Wundheilung unterstützt und Schmerzen lindern kann, doch unser Pflanzenvorrat geht ebenfalls zur Neige.\n\nMan nennt sie Drachenwinde und sie wächst im Drachendüster und im Drachensumpf östlich der Siedlung. Die Pflanze besteht aus gewundenen Stengeln und wenn man sie ansieht, scheint sie zu pulsieren.", sourceObjective = "Gizzix Rußgurgel in Morastwinkel möchte, dass Ihr ihm 8 Drachenwinden bringt.", progress = "Habt Ihr einige Drachenwinden gefunden?", completion = "Danke! Damit sollten wir eine Weile überleben können, bis Moxie mit den restlichen Vorräten von der Zeppelinabsturzstelle zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11218] = { id = 11218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung! Sprengstoff!", description = "{name}, der Hauptmann hat mich mit einer Mission beauftragt - und ich hätte gerne Eure Hilfe.\n\nEine Truppe meiner Kameraden bei der Forscherliga wurde verrückt, als sie in der Flüsterschlucht im Norden etwas ausgrub. Sie greifen einen jeden an, der versucht, dort hineinzugelangen.\n\nDer Hauptmann ist nur wegen dem Erz für die Wache beunruhigt. Zu unserem Glück habe ich genau das Richtige für unseren Zweck.\n\nGeht dorthin, jagt das Erz in die Luft und bringt es gemeinsam mit allen Edelsteinen, die Ihr finden könnt, zurück. Diesen Laden zu schmeißen ist nicht gerade billig, müsst Ihr wissen!\n\nMuss Euch jedoch warnen - das Erz ist seltsam!", sourceObjective = "Verwendet Stahlrings idiotensicheres Dynamit, um 6 Erzfragmente aus der Flüsterschlucht und 18 Edelsteine aus der Flüsterschlucht zu beschaffen. Bringt die Gegenstände anschließend zu Pionier Stahlring in Westwacht zurück.", progress = "Diesen Ort aufzubauen scheint eine endlose Aufgabe zu sein. Ich hoffe nur, dass Ihr bekommen könnt, was wir benötigen, um weiterzumachen.", completion = "Ihr habt von dem Erz ein seltsames Gefühl bekommen? Vielleicht werden wir das Zeug dann doch nicht verwenden.\n\nDiese Edelsteine sind wirklich hübsch! Ich frage mich, was ich für die bekommen kann? Es gibt natürlich immer Reparaturen zu erledigen und neue Dinge herzustellen.\n\nDoch, ich finde, dass unsere Zusammenarbeit profitabel war. Nehmt dies... es ist das mindeste, was ich machen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[11219] = { id = 11219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löscht das Feuer!", description = "Die Kinder der Horde brauchen Eure Hilfe, {name}. Der kopflose Reiter, einst ein Paladin der Menschen und jetzt ein wahnsinniger Unhold, hat unser Dorf in Brand gesetzt! Ihr müsst diese Feuer löschen!\n\nSchnappt Euch einen Eimer Wasser und löscht die Flammen damit. Ihr könnt den Eimer auch an einen Verbündeten, der näher bei den Feuern steht, weiterreichen. Löscht alle Feuer und haltet den kopflosen Reiter auf!", sourceObjective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11220] = { id = 11220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kopflose Reiter", description = "Solange der Kopf des kopflosen Reiters nicht vernichtet wird, wird sein verheerendes Wüten kein Ende nehmen.\n\nDer Reiter haust tief im Unglückseligen Kreuzgang des Scharlachroten Klosters in Tirisfal. Geht dorthin und sprecht diese Worte:\n\n Erhebe dich, Reiter\n Deine Zeit ist gekommen\n Heut' Nacht sei dein Leben\n Auf ewig genommen!\n\nDies wird den Unhold hervorrufen. Vernichtet den Kopf des Reiters und er wird uns nie wieder plagen.", sourceObjective = "Sucht nach dem Kürbisschrein des kopflosen Reiters.", completion = "Der Ursprung dieses Schreins ist unbekannt, aber es besteht kein Zweifel, wem hier gehuldigt wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[11221] = { id = 11221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichte vom Schlachtfeld", description = "Unsere Mission in Nordend ist es, Arthas zu zerstören. Die Allianz ist hierbei doch nur ein Hindernis, das wir vernichten werden, wo auch immer wir es finden.\n\nWir konnten ihre östlichste Flotte zerstören, doch die Überlebenden haben sich am Verlassenen Strand im Süden verbarrikadiert.\n\nUnsere Streitkräfte hätten ihre provisorischen Verteidigungsanlagen schon vor langer Zeit überrennen sollen - wir haben ihren Überlebenswillen jedoch unterschätzt. Sucht nach Dunkelläuferin Lyana und Todespirscher Razael, meine Offiziere auf dem Schlachtfeld, und lasst Euch von ihnen über die Situation Bericht erstatten.", sourceObjective = "Sprecht mit Dunkelläuferin Lyana und Todespirscher Razael. Sie befinden sich auf dem Schlachtfeld in der Blutklamm südlich vom Hafen der Vergeltung. Kehrt zu Hochexekutor Anselm zurück, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Kanonen halten uns auf? Ich werd' denen zeigen, was Kanonen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11222] = { id = 11222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis des Verrats", description = "Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen diejenigen, die ihren Plan ausgeführt haben, die Defias, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.\n\nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit König Varian Wrynn in Burg Sturmwind.", completion = "<Hochlord Bolvar hört sich Jainas Botschaft an.>\n\nSeid Ihr sicher? Das ist eine schwerwiegende Anschuldigung...", sourceObjectiveStatus = "unverified-source-field" }
quests[11223] = { id = 11223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Jaina", description = "Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer eine treue Freundin und loyale Verbündete gewesen.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", completion = "Das sind ausgezeichnete Neuigkeiten, {name}! Ich hatte befürchtet, dass der Hochlord an der Aufrichtigkeit unserer Informationen zweifeln würde, aber meine Sorge war wohl unberechtigt.\n\nTheramore und die Allianz werden Euch für Eure Bemühungen reichlich belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11224] = { id = 11224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickt die Packmulis packen", description = "Mir sind Gerüchte zu Ohren gekommen, nach denen in der Flüsterschlucht im Norden schlimme Dinge passieren. Ein Großteil der Forscherliga ging dorthin - und man sagt, dass das, was sie dort entdeckten, sie in den Wahnsinn trieb.\n\nDas ändert jedoch nichts daran, dass sie die meisten unserer Mulis und den überwiegenden Teil unserer Ausrüstung mitnahmen. Aber die Mulis werde ich nicht verlieren!\n\nFalls Ihr Euch dort herumtreiben solltet und Euch zufällig ein paar Mulis über den Weg laufen, dann müsst Ihr Euch ihnen nur nähern und sie mit erhobener Hand bedrohen. Das wird sie so sehr erschrecken, dass sie bestimmt wieder nach Hause kommen werden.", sourceObjective = "Forscherin Abigail möchte, dass Ihr Euch in die Nähe von 10 verlassenen Packmulis begebt, um jedes Mal Eure Hand zu /heben. Kehrt zu ihr zurück sobald Ihr damit fertig seid. Sie befindet sich in der Westwacht.", progress = "Das ist ein schwerer Schlag für uns. Ich wage es nicht einmal mir auszumalen, was sie dort unten entdeckt haben.\n\nEs hält mich schon die ganze Nacht lang wach, wenn ich nur versuche mir vorzustellen, was es denn sein könnte.", completion = "Ich stehe in Eurer Schuld, {class}. Nachdem wir den Großteil unserer Mulis und Ausrüstung wiederbeschafft haben, können wir zumindest darauf hoffen, bald wieder zahlreicher zu sein.\n\nBitte, nehmt dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[11225] = { id = 11225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler des Hexenhügels", description = "Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.\n\nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn \"Sumpfauge\" Jarl, machen sich bereits einige Anzeichen bemerkbar.\n\nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.\n\nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", completion = "Seid Ihr hierher gekommen, um mich auszuspionieren? Nein?\n\nDann seid Ihr vielleicht ein Liebhaber der guten Küche? Gut, ich kann Eure Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11227] = { id = 11227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie Krähen fressen", description = "Der Hochexekutor möchte, dass ich mit meinen Hunden die gegnerischen Späher aufspüre. Aber ich kann Euch das gleich sagen, dass diese Seuchenhunde nirgendwo hingehen, bevor sie nicht richtig gefüttert wurden.\n\nWenn es unserem Militär nicht in den Sinn kommt, dass diese Biester wählerisch genug sind, um den Müll nicht zu fressen, der mir gegeben wurde, dann können sie auch nicht erwarten, dass sie irgendwelchen Nutzen auf dem Schlachtfeld haben werden.\n\nIhr scheint etwas Zeit zu haben. Wieso nehmt Ihr nicht einen der Hunde und geht mit ihm auf Krähenjagd im Westen? Für uns ist ihr Fleisch nicht sehr bekömmlich, doch meine Jungs stehen drauf!", sourceObjective = "Pontius, der Hüter des Zwingers im Hafen der Vergeltung, möchte, dass Ihr mithilfe des Seuchenhundkäfigs einen hungrigen Seuchenhund herbeiruft und diesen dann mit dem Krähenfleisch der Fjordkrähen füttert. Letztere befinden sich westlich des Hafens der Vergeltung.", completion = "Hast du ein paar Krähen gejagt, Junge? Guter Junge, guter Junge!\n\nAh, diese Hunde erinnern mich an die Zeiten, als ich Reinrassige in Tirisfal aufzog... das waren gute Zeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[11228] = { id = 11228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Hölle aus Eis...", description = "Auf Fordragon wird noch etwas zukommen, wenn er denkt, dass die paar Deckschrubber, die er zum Schutz dieses Hafens geschickt hat, noch viel länger durchhalten werden.\n\n<Macalroy begutachtet Eure Ausrüstung und hebt eine Braue.>\n\nEuch könnte es jedoch ein wenig besser ergehen.\n\nWie wichtig es ist, diesen Hafen zu halten, kann nicht genug betont werden - und seitdem diese Monster über unsere Köpfe hinwegfliegen, hat sich die Situation noch verschlechtert.\n\nMeldet Euch bei Vizeadmiral Keller im Nordwesten, nicht weit von hier. Sagt ihm, dass Ihr gekommen seid, um ein paar Hintern zu versohlen und Kaugummi zu kauen - Ihr jedoch keinen Kaugummi mehr habt.", sourceObjective = "Sprecht mit Vizeadmiral Keller im Hafen von Valgarde.", completion = "Der Zwerg spricht die Wahrheit. Wir können es uns nicht leisten, diesen Hafen zu verlieren. Er ist einer von zwei sicheren Häfen in dieser Eishölle, die der Allianz gehören - der andere liegt ein paar Hundert Meilen westlich von hier, an der Küste der boreanischen Tundra.", sourceObjectiveStatus = "unverified-source-field" }
quests[11229] = { id = 11229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windläuferflotte", description = "Östlich des Verlassenen Strands sind die Schiffe 'Windläufer', die 'Vergeltung ihrer Majestät' und die 'Ewige Vergessenheit' stationiert. Schickt dem Flottenkommandant Kapitän Harker den Auftrag, dass die Kanonen der Allianz zerstört werden müssen.\n\nSprecht mit unserer Fledermausführerin Kamilla und fragt nach einer Möglichkeit, um zum Standort der Flotte hindurchzukommen. Beeilt Euch, {name}. Jede Minute, die wir gegen die Allianz kämpfen, ist eine Minute, die wir gegen Arthas kämpfen könnten.", sourceObjective = "Sprecht mit Fledermausführerin Kamilla im Hafen der Vergeltung und fragt nach einer Möglichkeit, zur Windläufer hindurchzukommen. Meldet Euch dann bei Kapitän Harker an Bord des Schiffs.", completion = "Ich hoffe, dass Ihr bereit seid, zu kämpfen, {name}. Die Flotte ihrer Majestät braucht Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11230] = { id = 11230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterhalt!", description = "Das hätte ein Kinderspiel sein sollen. Ihre Streitkräfte sind hungrig, verletzt und schlecht ausgerüstet. Doch irgendwie sind wir geradewegs in ihre Falle gelaufen.\n\nZwecks Deckung näherten wir uns dem Riff vom Süden her, worauf wir dann sofort von der Allianz - diesen Hunden - geentert wurden.\n\nLeider muss ich sagen, dass Ihr uns zuerst dabei helfen müsst, unsere Schiffe zurückzubekommen, bevor unsere Kanonen auf irgendetwas schießen können.", sourceObjective = "Kapitän Harker an Bord der Windläufer möchte, dass Ihr 15 Marinesoldaten der Nordflotte tötet.", completion = "Diese Bastarde zurechtzustutzen, war saubere Arbeit. Meine Männer werden sich um den Rest kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[11231] = { id = 11231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Schlüsseln und Käfigen", description = "Dem Hauptmann mag es egal sein, aber das wenige was wir wissen ist, dass die Vrykul im nördlich gelegenen Gjalerbron abscheuliche Riten durchführen, die Teil einer Art Erweckungsritual sind.\n\nSie bedienen sich lebendiger Opfer für ihre unheiligen Rituale!\n\n{class}, Ihr müsst dem ein Ende bereiten! Es kommt nicht darauf an, wer oder was in diesen Käfigen ist - egal was, es muss befreit werden. Ich wette, dass die Vrykul die Schlüssel bei sich tragen.\n\nBeim Licht, das letzte was wir gebrauchen können ist, dass noch mehr dieser seltsamen Vrykul umherlaufen; oder sogar schlimmer: dass sie etwas erwecken, das noch boshafter ist.", sourceObjective = "Vater Levariol möchte, dass Ihr genug Schlüssel für einen Gjalerbronkäfig sammelt, um 10 Gefangene von Gjalerbron zu befreien. Kehrt zu ihm zurück, sobald Ihr damit fertig seid. Er befindet sich in Westwacht.", completion = "Gesegnet sollt Ihr sein, mein Kind! Mit Eurer Hilfe scheint das Licht selbst an den dunkelsten Orten.\n\nBitte, nehmt dies. Ein gerechter Lohn für Eure guten Taten. So werde ich mich um das Heil derer kümmern, die Ihr befreit habt - oder zumindest um diejenigen der Zurückgekehrten, die dem Licht wahrhaftig angehören und auf der Seite der Allianz sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11232] = { id = 11232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lenkt unseren Blick", description = "Wir sollten uns den Weg zurück zu unseren Kanonen freikämpfen können. Unglücklicherweise sind die Sichtverhältnisse alles andere als wünschenswert, weswegen Ihr unsere Ziele vom Boden aus markieren müsst.\n\nNehmt diese Rauchsignale mit Euch, geht zur Stellung der Allianz am Verlassenen Strand westlich von hier und markiert mit ihnen die Kanonen, die sich entlang der Nordwand befinden.\n\nSagt Lyana Bescheid, sobald der Weg für die Bodentruppen frei ist. Wir können hier drüben auf uns selbst aufpassen.", sourceObjective = "Markiert mit den Rauchsignalen die Stellen entlang der Nordwand am Verlassenen Strand, an denen sich die Kanonen der Allianz befinden. Meldet Euch bei Dunkelläufer Lyana in der Blutklamm, sobald Ihr die Aufgabe abgeschlossen habt.", completion = "Ausgezeichnet. Ich werde unseren Bodentruppen signalisieren, dass sie sich in Bewegung setzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11233] = { id = 11233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Todesstoß landen", description = "Ihr habt Euren Wert auf dem Schlachtfeld bewiesen, {name}. Womöglich habt Ihr das Blatt zu unseren Gunsten gewendet.\n\nNun habe ich einen wichtigen Auftrag für Euch. Ich bin mir nicht sicher, wie lange die von uns entdeckte Schwachstelle vorhanden sein wird. Wir müssen uns das Überraschungsmoment zu Nutze machen.\n\nIch möchte, dass Ihr die Verwirrung, die unser Angriff ausgelöst hat, nutzt und Euch hinter die feindlichen Linien begebt, um ihre Anführer zu töten. Diese sind wie folgt nach Rang geordnet: Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric. Viel Glück, {class}.", sourceObjective = "Dunkelläuferin Lyana südlich des Hafens der Vergeltung möchte, dass Ihr Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric tötet. Ihr findet sie am Verlassenen Strand.", completion = "Dies ist Ausdruck des unumstrittenen Sieges unserer Streitmacht. Anselm wird sehr erfreut sein, wenn er davon erfährt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11234] = { id = 11234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Anselm", description = "Dann lasst uns doch mal den alten Anselm benachrichtigen. Der Sieg kam später als erwartet - doch besser spät als nie. Sagt ihm, dass unsere Streitkräfte ein paar Stunden benötigen werden, um der Nachhut hier den Rest zu geben.\n\nHoch lebe die Bansheekönigin!", sourceObjective = "Erstattet Hochexekutor Anselm Bericht. Er befindet sich im Hafen der Vergeltung im Heulenden Fjord.", completion = "Wurde auch langsam Zeit. Die Allianz ist uns jetzt schon eine ganze Weile lang ein Dorn im Auge.\n\nWir haben jedoch keine Zeit zum Feiern. Richtet Euren Blick nach Westen - es sieht aus, als hätten wir Besuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11235] = { id = 11235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Gjalerbron fertig werden", description = "Und nun haben wir ein anderes Problem. Diejenigen meiner Späher, die mit dem Leben davon gekommen sind, haben mir berichtet, dass die Vrykul in ihrer Hauptfestung gen Norden nichts Gutes im Schilde führen.\n\nSie nennen den Ort Gjalerbron - obwohl man das 'Gj' wie ein 'Sch' ausspricht. Seltsame Kreaturen sind das.\n\nAber das ist nicht wichtig. Was wichtig ist, ist, dass Ihr Euch dorthin begebt und das Leben so vieler dieser Kreaturen auslöscht, wie Ihr nur könnt. Findet gleichzeitig heraus, was sie dort treiben.\n\nIch weiß, dass ich mich auf Euch verlassen kann, {name}.", sourceObjective = "Hauptmann Adams möchte, dass Ihr 15 Krieger von Gjalerbron, 8 Runenmagier von Gjalerbron und 8 Schlafwächter von Gjalerbron tötet. Kehrt danach zu ihm zurück. Ihr findet ihn in Westwacht.", completion = "Gute Arbeit, {name}. Ein Glück, dass wir sie los sind!\n\nAber was Ihr über diesen Ort zu berichten habt, macht mir noch immer Sorgen. Ich denke, dass unsere Eindämmungsaktion noch nicht ganz beendet ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[11236] = { id = 11236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrogroßfürst Mezhen", description = "Die Geißel ist in Gjalerbron und sie haben Nekromanten bei sich! Sie versuchen sicherlich, die Vrykul zu Arthas' Gefolgsleuten zu machen.\n\nIch will, dass der Anführer der Nekrolords eliminiert wird!\n\nTut alles was Ihr könnt, {name}. Aber sorgt dafür, dass Nekrogroßfürst Mezhen und das, was er versucht zu bewerkstelligen, aus der Welt geschafft wird.\n\nEine Allianz zwischen den Vrykul und der Geißel werde ich nicht dulden!\n\nGeht zur Plattform in der hinteren rechten Ecke von Gjalerbron, dort werdet Ihr Mezhen finden.", sourceObjective = "Tötet Nekrogroßfürst Mezhen. Kehrt dann zu Hauptmann Adams zurück. Ihr findet ihn in Westwacht.", completion = "<Der Hauptmann seufzt erleichtert auf.>\n\nTja, das sollte es uns ein wenig einfacher machen.\n\n{name}, Ihr habt immer wieder bewiesen, dass Ihr für Westwacht und die Allianz insgesamt von unschätzbarem Wert seid. Sucht Euch etwas aus der Schatzkammer aus! Es ist das mindeste, was wir tun können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11237] = { id = 11237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriffspläne von Gjalerbron", description = "In diesen Plänen wird ein unmittelbar bevorstehender Angriff auf Westwacht bis ins Detail beschrieben. Es scheint, als würde der Frostwyrm Glacion, der hoch am Himmel seine Bahnen zieht, für diese Offensive eingesetzt werden.\n\nMagierleutnant Malister könnte in dieser Sache sicherlich behilflich sein. Überbringt ihm die Pläne. Ihr findet ihn in der Feste gen Süden.", sourceObjective = "Übergebt die Angriffspläne von Gjalerbron an Magierleutnant Malister. Er befindet sich in Westwacht.", progress = "Was?! Pläne für einen Angriff auf die Wache?\n\nEIN FROSTWYRM?!!!", completion = "{name}, wir dürfen das nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11238] = { id = 11238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Frostwyrm und sein Meister", description = "Das hier zu mir zu bringen, war die richtige Entscheidung, {name}. Ihr müsst zum nördlich gelegenen Gjalerbron gehen und den Wyrm und seinen Meister, Wyrmrufer Elend, niederstrecken.\n\nNoch während wir hier reden könnte der Frostwyrm schon unterwegs sein.\n\nWenn ich die Pläne jedoch richtig verstehe, dann wird Glacion zurückgerufen, wenn man das Wyrmruferhorn auf seiner Plattform in der hinteren linken Ecke von Gjalerbron bläst. Ihr müsst das Wesen besiegen, sobald es landet!\n\nUnd {name}: Bitte bringt mir das Horn. Wir würden es nicht gerne sehen, wenn es wieder in falsche Hände geraten sollte.", sourceObjective = "Erschlagt Wyrmrufer Elend und benutzt das Wyrmruferhorn, um Glacion herbeizurufen und ihn niederzustrecken. Kehrt anschließend gemeinsam mit dem Horn zu Magierleutnant Malister zurück. Er befindet sich in Westwacht.", progress = "Ist der Angriff abgewendet? Wurden der Frostwyrm und sein Meister vernichtet?\n\nHabt Ihr das Horn zurückgebracht?", completion = "Wahnsinn, das Horn ist kalt!\n\nIhr habt Westwacht wieder einmal vor ihrem sicheren Untergang bewahrt. Welch ungewöhnlicher Mann Ihr seid, {name}. Wenn es nur mehr wie Euch geben würde.\n\nTja, das verlangt allerdings nach einer Belohnung. Was würdet Ihr bevorzugen?", sourceObjectiveStatus = "unverified-source-field" }
quests[11239] = { id = 11239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Lichts", description = "Euer Dienst ist beispielhaft gewesen, {name}. Doch es gibt etwas, das mir Sorgen bereitet: die Geißel.\n\nDas Licht kann ihre Anwesenheit nicht dulden und genau so wenig sollen wir es tun. Ich hoffe, dass es nicht zu viel verlangt ist, wenn ich Euch zurück ins nördlich gelegene Gjalerbron schicken würde, damit Ihr die Geißel in diesem abscheulichen Unterschlupf vernichtet! Seht zu, dass Ihr auch in den Hallen des Erwachens unter Gjalerbron nachseht.\n\nReinigung ist der Weg zur Erlösung, mein Kind. Macht uns stolz!", sourceObjective = "Erschlagt 10 ewige Beobachter, 4 furchterregende Schrecken und 2 eitrige Kreaturen. Informiert danach Vater Levariol von Eurem Erfolg. Er befindet sich in Westwacht.", completion = "<Der Priester spricht einen kaum hörbaren Segen für Euch aus.>\n\nSeid gesegnet, {name}. Ihr habt meine Gebete erhört. Steht mit Stolz und erhobenem Kinn im Lichte. Wisset, dass Eure Taten höchst heilig waren!\n\nIch bin mir sicher, dass Euch die Truhen der Kirche etwas Brauchbares bieten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11240] = { id = 11240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anführer der Verwirrten", description = "Also, ich sag es nicht gerne, mein Freund, aber während Ihr fort wart, fing der Hauptmann an, ein stärkeres Interesse an diesem Ort zu hegen.\n\nSieht so aus, als wollte er meinen alten Boss bei der Forscherliga dort drin tot sehen. Ich schätze mal, dass wir uns für eine Offensive rüsten, um den Rest von ihnen zu beseitigen. Der Hauptmann will gewissermaßen, dass sie einen Kopf kürzer gemacht werden.\n\nWollt Ihr mir einen Gefallen tun? Geht zurück zur Flüsterschlucht und bereitet Squeeg Götzenjäger ein Ende. Meiner Erinnerung zufolge könnte er sich in der Höhle in der nordwestlichen Ecke befinden.", sourceObjective = "Erschlagt Squeeg Götzenjäger und meldet Euch dann bei Pionier Stahlring in Westwacht.", completion = "<Der Pionier murrt, als wünschte er sich, dass Ihr es nicht geschafft hättet.>\n\nDer Hauptmann wird erfreut darüber sein, dass Ihr Erfolg hattet.\n\nNun ja, Ihr habt so gut bei der Flüsterschluchtsache mitgemacht, wieso sucht Ihr Euch nicht hiervon etwas aus?", sourceObjectiveStatus = "unverified-source-field" }
quests[11241] = { id = 11241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenspur", description = "Danke, dass Ihr mir aus diesem Schlamassel geholfen habt, {name}. Ich habe mich nicht danach gesehnt, zu sehen, was diese Allianzmistkerle für mich auf Lager hatten.\n\nLasst uns von hier verschwinden und schauen wir mal, ob wir es ihnen irgendwie heimzahlen können. Ist das ein Lagerfeuer dort drüben?", sourceObjective = "Eskortiert Apotheker Hanes vom Verlassenen Strand. Meldet Euch bei Apotheker Lysander, sobald Ihr diese Aufgabe abgeschlossen habt. Er befindet sich im Hafen der Vergeltung im Heulenden Fjord.", completion = "Apotheker Hanes ist am Leben? Ihr habt die Vorräte der Allianz verbrannt? Das hat ihm garantiert Riesenspaß gemacht.\n\nAuf jeden Fall steht die königliche Apothekervereinigung in Eurer Schuld, {name}. Unser Dank für Euch kommt aus den Tiefen unserer schwarzen Herzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11242] = { id = 11242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei!", description = "Zorn hielt mich gefangen, {name}, Ihr habt mich befreit. Obgleich meine Taten mir nicht unrecht erschienen, so krümmt sich meine Seele jetzt bei dem Gedanken an all das Leid und den Tod, den ich den Bewohnern Azeroths gebracht habe, vor Schmerz.\n\nDanke, dass Ihr mich zurück zum Licht geführt habt. Möge ich nie mehr vom rechten Pfad abkommen.\n\nBringt dieses zerfetzte Gebetsbuch zu einer Waisenmatrone, damit die Kinder erfahren, dass ich sie nicht länger heimsuchen werde.", sourceObjective = "Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Goldhain, Kharanos oder bei der Azurwacht.", progress = "Ihr habt etwas für mich, {name}?", completion = "Was ist das? Der Foliant von Thomas Thomson, sagt Ihr? Aber das ist doch der Name des kopflosen Reiters, bevor er dem Flucht zum Opfer fiel! Heißt das, seine Seele ist endlich frei? Bedeutet dies wirklich, dass er die guten Einwohner von Azeroth nie wieder heimsuchen wird? Was für ein Freudentag! {name}, von Euren Heldentaten wird man noch lange zu berichten wissen. Die Kinder und sogar ihre Kinder werden sich stets an Euren Namen erinnern!", sourceObjectiveStatus = "unverified-source-field" }
quests[11243] = { id = 11243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falls Valgarde fällt...", description = "Falls Valgarde fällt, wird unser Hauptversorgungsweg nach Nordend zum Stillstand kommen. Von da an wäre es nur eine Frage der Zeit, bis wir alle Diener des Lichkönigs sind. Nun, ich weiß nicht, wie es um Euch steht, aber ich habe eine Frau und drei Kinder in Elwynn - soll mich der Teufel holen, wenn ich ohne einen Kampf unterginge.\n\nDie Situation hier ist kritisch. Wir können jede Unterstützung gebrauchen, die Ihr aufbringen könnt. Begebt Euch zum Eingangstor und helft den Wachen, die Stadt gegen die Eindringlinge zu verteidigen!", sourceObjective = "Vizeadmiral Keller möchte, dass Ihr 12 Eindringlinge der Drachenschinder oder Worge der Drachenschinder tötet. Er befindet sich im Hafen von Valgarde im Heulenden Fjord.", progress = "Es ist gut möglich, dass das Schicksal der Welt in unseren Händen liegt.", completion = "Ihr habt unseren Verteidigern die nötige Unterstützung gegeben, {name}. Dank Euch ist die Moral höher denn je. Ich denke, dass sie den Rest des Ansturms alleine bewältigen können. Ich habe großes mit Euch vor...", sourceObjectiveStatus = "unverified-source-field" }
quests[11244] = { id = 11244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Retter retten", description = "Wir waren hier seit einem Monat, als diese missgestalteten Riesen aus dem Nichts auftauchten. Für einen Angriff waren wir schlecht vorbereitet und so mussten wir für unsere Selbstgefälligkeit bitter bezahlen. Ein komplettes Archäologenteam war verschwunden und einige Einwohner wurden entführt und zu den Ruinen gebracht. Seitdem sind wir in der Defensive.\n\nZu allem Übel wurden die Späher, die wir zur Rettung unserer Leute aussandten, von den Vrykul mit Harpunen beschossen und im Wald direkt nördlich von Valgarde zum Sterben liegen gelassen. Räumt diese Harpunen aus dem Weg und befreit unsere Späher!", sourceObjective = "Vizeadmiral Keller möchte, dass Ihr 8 Späher von Valgarde rettet, die mit Harpunen beschossen und zum Sterben liegen gelassen wurden. Er befindet sich im Hafen von Valgarde im Heulenden Fjord.", completion = "Was die Vrykul unseren Spähern angetan haben, war ein grausamer Akt der Barbarei. Es war zur Abschreckung gedacht, um unseren Willen zu schwächen... und uns in die Flucht zu schlagen.\n\nEs hat nicht funktioniert.\n\nWir werden diesen Monstern zeigen, was es bedeutet, gegen die Allianz Krieg zu führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11245] = { id = 11245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Türme des sicheren Untergangs", description = "<Gnädiger Herr/Gnädige Frau>, wenn wir durch Skorn ziehen, müssen wir die Türme zerstören!\n\nWenn Ihr sie Euch anseht, dann werdet Ihr feststellen, dass sich viele Zauberer auf den Türmen befinden. Sich zu nah an sie heranzuwagen, würde für uns den sicheren Tod bedeuten!\n\nWir verfügen jedoch über die Möglichkeit, Kanonensalven aus Westwacht anzufordern. Um das zu tun, müssen wir nahe genug herankommen und ein Leuchtsignal auf die Stelle schießen, wo sich die Magier befinden.\n\nKommt nur nicht zu nah ran!", sourceObjective = "Der Unteroffizier der Westwacht meint, dass es sinnvoll wäre, wenn man mit dem Leuchtsignal des Unteroffiziers die Türme in Skorn markiert, damit sie anschließend unter Kanonenbeschuss genommen werden können.", progress = "Sich zu nah an die Türme heranzuwagen bedeutet den sicheren Tod, solange die Zauberer dort oben sind.", completion = "Ausgezeichnetes Zielen, gnädiger Herr! Ich darf nicht vergessen, den Kanonieren in der Wache eine Runde auszugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11246] = { id = 11246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausam, aber notwendig", description = "Wir haben Berichte erhalten, nach denen die Vrykul von den Toten auferstehen können - ähnlich der Geißel, doch eine andere Art des Untodes.\n\nLasst uns kein Risiko eingehen.\n\nHier, nehmt meine Machete. Wir werden durch diesen Ort ziehen und Ihr werdet die Überreste der von uns erschlagenen Vrykul zerstückeln müssen. Ich würde es tun, wenn ich keinen empfindlichen Magen hätte.\n\n<Der Unteroffizier lächelt selbstgefällig.>\n\nIch habe den ganzen Morgen damit verbracht, sie zu schärfen - sie sollte also für die Aufgabe geeignet sein.", sourceObjective = "Der Unteroffizier der Westwacht möchte, dass Ihr nach Skorn geht und mit der Machete des Unteroffiziers 20 Vrykul des Winterskornstammes zerstückelt.", completion = "Nun ja, mein Herr - ich muss sagen, dass Ihr mit besonderem Eifer an diese spezielle Sache herangegangen seid.\n\n<Der Unteroffizier blickt Euch misstrauisch an.>\n\nNaja, ich werde meine Machete jetzt wieder zurücknehmen, wenn es Euch recht ist. Sie sieht stumpf aus und wir wollen doch nicht, dass Ihr aus Versehen ausrutscht und mich genau so zerstückelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11247] = { id = 11247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenne, Skorn - brenne!", description = "Hauptmann Adams gab mir strikte Anweisungen, sicherzustellen, dass die Infrastruktur dieses Ortes starken Schaden nimmt.\n\nDa Ihr jedoch hier draußen das Kommando habt, liegt es in Eurem Ermessen, <Sire/Mylady>.\n\nDürfte ich vorschlagen, dass wir beide Langhäuser und die Kaserne, die sich im niedriger gelegenen Teil Skorns befinden, niederbrennen? Dazu müssen wir nur in jedes Gebäude eindringen und diese Fackel hier werfen.", sourceObjective = "Der Unteroffizier der Westwacht hat Befehle erhalten, nach denen Ihr mit der Fackel des Unteroffiziers die beiden Langhäuser und die Kaserne in Skorn in Brand stecken sollt.", progress = "Dürfte ich vorschlagen, dass wenn wir die Gebäude in Brand setzten, wir uns dann nicht zu lange in ihnen aufhalten?", completion = "Sehr gut, Sire. Das wäre ohne Eure Hilfe nicht zustande gekommen.\n\nIch bin mir sicher, dass sich der Hauptmann über meinen Bericht freuen wird, sobald wir hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11248] = { id = 11248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Skorns Zorn", description = "{name}, ich muss Euch nun darum bitten, eine Operation durchzuführen, die so gefahrvoll und tödlich ist, dass nur Ihr sie bewältigen könnt.\n\nAn unserer östlichen Grenze befindet sich die Vrykulfestung Skorn. Meine Späher berichten mir, dass diese 'Riesen' kurz davor sind, uns anzugreifen. Meine Streitkräfte sind jedoch über den ganzen Fjord verstreut, weswegen ich nicht über genügend Männer verfüge, um den Ort gewaltsam in Besitz zu nehmen.\n\nIhr werdet stattdessen gerissen sein müssen. Ich habe schon einen Unteroffizier, der über Details in Kenntnis gesetzt ist, vorgeschickt. Zeigt diese Befehlsinsignie in Skorn vor und er wird sich Euch zeigen und Eure Befehle befolgen.", sourceObjective = "Hauptmann Adams möchte, dass Ihr die Befehlsinsignie der Westwacht in Skorn benutzt und anschließend mit dem Unteroffizier der Westwacht sprecht.\n\nBereitgestellter Gegenstand:", completion = "Sehr angenehm, Euch kennen zu lernen, Sire! Ich freue mich auf unsere Zusammenarbeit.\n\nWo wir gerade davon reden: Wir haben jede Menge zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[11249] = { id = 11249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhindert seinen Aufstieg!", description = "Diese riesige Schriftrolle ist aus Drachenhaut gefertigt. Ihr entrollt die mehr als zehn Meter lange Schriftrolle und seht, dass die Bilder auf ihrer schuppigen Oberfläche ein rätselhaftes Vrykulritual darstellen.\n\nEin Than der Vrykul, umgeben von engelhaften Wesen, steigt in den Himmel auf. Eine rätselhafte finstere Figur zeichnet sich vom Hintergrund des Bildes ab.\n\nIhr habt eine ungute Vorahnung, dass der Than von Skorn im Begriff ist, genau dies zu tun. Ihr müsst das verhindern! Vor der Hütte des Thans, auf Skorns höchstem Punkt, steht ein großer Scheiterhaufen.", sourceObjective = "Präsentiert die Vrykulrolle des Aufstiegs in der Nähe des Scheiterhaufens vor der Hütte des Thans, um ihn herauszurufen und ihn niederzustrecken. Ihr seid Euch sicher, dass Vater Levariol an dem Ritual und damit auch an der Schriftrolle Interesse finden wird. Er befindet sich in Westwacht.", progress = "Ja? Wie kann ich Euch behilflich sein, mein Kind?", completion = "Ja, mein Sohn, dies könnte Unheil bedeuten. Ihr habt offenbar richtig gehandelt.\n\nDanke, dass Ihr mir diese Schriftrolle gebracht habt. Ich kann es kaum erwarten, herauszufinden, was sie zu bedeuten hat. Würde ich es wagen, eine Vermutung anzustellen, dann würde ich behaupten dass die Vrykul einen Weg haben, um den Tod zu überwinden. Oder zumindest diejenigen, die dessen würdig sind.\n\nIndem Ihr den Than der Winterskorn besiegt habt, habt Ihr bewiesen, dass er unwürdig war. Nur das Licht weiß, was aus ihm geworden wäre und welch Schrecken er über uns gebracht hätte, hättet Ihr ihn nicht erschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11250] = { id = 11250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch lebe der Eroberer von Skorn!", description = "Wir - oder eher Ihr - haben alles getan, zu dessen Erfüllung wir hier her gekommen sind, <Sire/Mylady>. Ich muss sagen, dass es mir eine Freude war, von solch <einem jungen Mann/einer jungen Frau> Befehle zu erhalten.\n\nDer Hauptmann will höchstwahrscheinlich von Eurem Erfolg in Kenntnis gesetzt werden. Solltet Ihr jedoch aus irgendeinem Grund hier bleiben wollen, dann stehe ich Euch zur Verfügung.", sourceObjective = "Bringt die Befehlsinsigne der Westwacht zu Hauptmann Adams zurück. Ihr findet ihn in Westwacht.", progress = "Ich schließe mal aus Eurer Anwesenheit, dass es Skorn nicht mehr gibt. Lieg' ich da richtig?", completion = "Das sind unglaublich gute Neuigkeiten! Ich wusste, dass Ihr es schaffen würdet, {name}!\n\nWenigstens einer, der hier Resultate liefern kann!\n\nTja, das verlangt nach einer Belohnung. Nur zu, sucht Euch etwas aus - für Euch steht die Schatzkammer offen.", sourceObjectiveStatus = "unverified-source-field" }
